window.__D("text/torat-menachem/c074",{"p":[[1400330013,"(הנחה בלתי מוגה)\n<b>עשר</b> תעשר את כל תבואת זרעך<sup data-n=\"1258\">1</sup>, ואמרו רז\"ל<sup data-n=\"1259\">2</sup> עשר בשביל שתתעשר, כי, בפסוק זה אי אפשר לפרש כפי שמפרשים בכ\"מ שהכוונה בכפל הלשון היא אפילו מאה פעמים<sup data-n=\"1260\">3</sup>, שהרי מעשר הוא דבר קצוב, ולכן פירשו שעשר תעשר הם ב' ענינים, עשר ותתעשר, שנתינת המעשר הוא בשביל שתתעשר. והיינו, דאע\"פ שאמרו רז\"ל<sup data-n=\"1261\">4</sup> הוו כעבדים כו' שלא על מנת לקבל פרס, מ\"מ, הנה במצות צדקה בכלל, ובמעשר בפרט, מבקש הקב\"ה ובחנוני נא בזאת גו'<sup data-n=\"1262\">5</sup>, שזהו גם תוכן הענין דעשר בשביל שתתעשר.\nב) <b>ולהבין</b> זה צריך להקדים תחילה ענין המעשר. דהנה<sup data-n=\"1263\">6</sup>, ידוע ומבואר בספרי הקבלה<sup data-n=\"1264\">7</sup> שספירת המלכות נקראת מעשר, וטעם הדבר אינו רק לפי שספירת המלכות היא ספירה עשירית, אלא גם לפי שהיא כמו המעשר שהוא חלק קטן בלבד בערך לשאר החלקים, וכך ספירת המלכות היא רק חלק קטן בערך לשאר הספירות. ויובן זה עד\"מ בכחות הנפש באדם למטה, שכח המלוכה וההתנשאות חלוק מכל שאר הכחות, שכל הכחות הם לעצמו, לא מבעי כח השכל שהוא לעצמו, שלא זו בלבד שאינו צריך לזולת, אלא עוד זאת, שהזולת מבלבל לשכל, וכידוע הראיות על זה, אלא גם המדות שהם לזולתו, וכמו בחסד ורחמים שצריך שיהי' זולת על מי להתחסד ועל מי לרחם, וכפי שמצינו באברהם אבינו שנצטער על שלא היו לו אורחים<sup data-n=\"1265\">8</sup>, לפי שאי אפשר להיות התפשטות מדת החסד בלי זולת, מ\"מ, הרי עצם המדות הם לעצמו, שבלעדי המדות הרי הוא חסר, והיינו, שכאשר לא תהי' אצלו אחת מהמדות אזי חסר אצלו גילוי כח מהנפש, משא\"כ כח המלוכה וההתנשאות שזהו רק לזולתו, וגם כאשרלא תהי' אצלו מדת ההתנשאות בגילוי אינו חסר כלל. והדוגמא מזה יובן למעלה בענין ספירת המלכות, שהיא בשביל הזולת. וזהו גם שבספר יצירה נזכרו רק ג' יסודות אש מים רוח, ואינו נזכר יסוד העפר, ומבואר על זה בפרדס<sup data-n=\"1266\">9</sup> שזהו עד\"מ קדירת מים ע\"ג האש שע\"י רתיחת המים נבדל העפר וניכר בפ\"ע, והיינו, שבחי' המלכות נכללה בשאר הספירות, והיא גילוי כללות הספירות או גילוי כל ספירה וספירה, וכמבואר בלקו\"ת ד\"ה לבאר ענין המסעות<sup data-n=\"1267\">10</sup> שהמלכות היא בחי' הגילוי שבכל מדה. ובמק\"א<sup data-n=\"1268\">11</sup> מבואר גם ההפרש בין אופן האצלת כל הספירות לאופן האצלת ספירת המלכות, שכל הספירות נאצלו בכמה נקודות, וספירת המלכות נאצלה נקודה אחת, ובנינה הוא מגילוי שאר הספירות. ומכל זה מובן איך שהמלכות היא רק חלק קטן בערך שאר הספירות, ולכן נקראת בשם מעשר.\nג) <b>והנה</b> נתינת המעשר היא ללוי, והו\"ע עליית המלכות בבינה, דגבי לויים כתיב<sup data-n=\"1269\">12</sup> ועבד הלוי הוא, שזהו בחי' בינה<sup data-n=\"1270\">13</sup>, ולכן היתה עבודת הלויים באמירת שירה על היין, כי ענין השירה וכן ענין היין הוא בספירת הבינה<sup data-n=\"1271\">14</sup>. והנה, אמירת השירה היא על היין שיש בו גם הניסוך ע\"ג המזבח, אלא שניסוך היין הוא ע\"י כהנים, ואמירת השירה היא ע\"י הלויים. וההפרש בין ניסוך לשירה יובן מענין ההפרש בין כהנים ללויים, כידוע<sup data-n=\"1272\">15</sup> שעבודת הכהנים היא המשכה מלמעלה למטה, וכמ\"ש בזהר<sup data-n=\"1273\">16</sup> דכהני בחשאי וברעותא דלבא, ועבודת הלויים היא העלאה מלמטה למעלה, ובאופן שהוא היפך ענין החשאי, וכמו\"כ יובן גם ההפרש בין כהנים ולויים בעבודתם בענין היין, שעבודת הכהנים היא בניסוך היין שענינו המשכה מלמעלה למטה, כידוע<sup data-n=\"1274\">17</sup> בענין כל הקורא ק\"ש בלא תפילין כאילו הקריב עולה בלא מנחה וזבח בלא נסכים<sup data-n=\"1275\">18</sup>, דק\"ש הו\"ע העלאה מלמטלמ\"ע, ותפילין הו\"ע המשכה מלמעלמ\"ט, וכן הוא גם בענין עולה ונסכים, שעולה היא העלאה מלמטלמ\"ע, כמ\"ש<sup data-n=\"1276\">19</sup> כליל תקטר, ונסכיםענינם המשכה מלמעלמ\"ט. משא\"כ ענין השירה הוא העלאה מלמטלמ\"ע, ולכן הי' זה ע\"י הלויים, שעבודתם היא בדרך העלאה מלמטלמ\"ע.\n<b>אך</b> צריך להבין, איך אפשר שבענין היין עצמו יהיו שני הפכים. והענין בזה, דהנה, יין הוא בחי' בינה, שהיא בחי' רחובות הנהר<sup data-n=\"1277\">20</sup>, והיינו, שחכמה היא באופן של נקודה בלבד, בחי' מעין, ובינה היא באופן של התרחבות, בחי' נהר, ולכן ענין הבינה הוא המשכה מלמעלמ\"ט, מבחי' הנקודה לבחי' ההתרחבות. אך מ\"מ הרי ידוע שבינה היא בחי' יסוד האש<sup data-n=\"1278\">21</sup>, והרי אש הו\"ע הכיווץ שזהו היפך ההתרחבות וההתפשטות. אך הענין הוא, שההתרחבות דבינה היא ע\"י צמצום דוקא, שצריך להיות תחילה צמצום והעלם בנקודת החכמה, ורק אז אפשר להיות ההתרחבות דבינה, והיינו, שכל זמן שמאיר תוקף האור דחכמה, אי אפשר שתהי' בזה התחלקות פרטים, כי בתוקף האור ו(לפעמים איתא הלשון ב)פנימיות האור אין בחי' אותיות, ואי אפשר שיהיו בזה פרטים, ודוקא כאשר נתעלם פנימיות האור, ונשאר רק חיצוניות האור שיש בו אותיות, אזי אפשר שיבוא להתחלקות פרטים. ונמצא, שאף שענין ההתרחבות דבינה הוא בחי' המשכה, שנמשך מן הנקודה לבחי' התרחבות, מ\"מ הרי זה בחי' גבורות והעלאה, לפי שבאה ע\"י צמצום. והרי ענין הצמצום שבבינה אינו דומה להצמצום שבנקודת החכמה, דהנה, גם נקודת החכמה באה ע\"י צמצום, אבל, הצמצום שבנקודת החכמה הוא ע\"ד לעולם ישנה אדם לתלמידו בדרך קצרה<sup data-n=\"1279\">22</sup>, שענין זה הוא באופן שהרב נותן להתלמיד את כל האור, אלא שזהו בדרך קצרה<sup data-n=\"1280\">23</sup>, וכלשון הרמב\"ם<sup data-n=\"1281\">24</sup> דברים מועטים ועניניהם מרובים, וכמו\"כ הוא בנקודת החכמה, שיש בה כל תוקף ופנימיות האור, אלא שזהו באופן של נקודה, אבל יש בזה כל התוקף והפנימיות, ולכן אי אפשר שתהי' בזה התחלקות פרטים כנ\"ל. משא\"כ בבינה הרי הצמצום הוא התעלמות האור, שמתעלם פנימיות האור דחכמה, ומה שנמשך בבינה הוא רק חיצוניות בלבד. ומשום זה הנה החכמה היא בחי' מים והבינה היא בחי' אש.\n<b>והנה</b> כשם שחכמה ובינה חלוקים במהותם, כמו\"כ חלוקים הם גם בענין העבודה הבאה מהם. והענין בזה, שמצד הבינה נעשהצמאון ואהבה כרשפי אש, דכיון שבבינה חסר פנימיות האור, הנה הגם שמשיג את הענין בהתרחבות בכל הפרטים, מ\"מ, כיון שמרגיש שכל זה הוא רק חיצוניות בלבד, והפנימיות חסר אצלו, לכן הוא מתעורר באהבה כרשפי אש ובתשוקה וצמאון לפנימיות האור. ועוד זאת, דכיון שבבינה יש רק חיצוניות האור בלבד, לכן היא בבחי' מציאות, ומשום זה שייך בה ענין הצמאון והרצוא. משא\"כ מצד החכמה, כיון שמאיר פנימיות האור, הרי הוא בביטול דשוב. ועוד זאת, שלא שייך בה ענין הצמאון כיון שמאיר בה פנימיות האור, והיינו, שבחי' זו שאלי' הוא הצמאון דבינה, הרי היא בגילוי בחכמה, ובמילא לא שייך שיהי' צמאון לבחי' זו.\n<b>אמנם</b> עם היות שהבינה באה ע\"י הצמצום כנ\"ל, מ\"מ, להיותה בחי' מרחב, הנה ע\"י הרצוא והצמאון והשוב שלאחרי הרצוא, נמשך מבחי' שלמעלה גם מנקודת החכמה, והו\"ע מרחב העצמי. והיינו, שבחי' החכמה, עם היות שיש בה כל תוקף ופנימיות האור כנ\"ל, מ\"מ, הרי היא בחי' נקודה בלבד, היינו, שהאור הוא באופן של צמצום בבחי' נקודה. אך ע\"י הרצו\"ש שבבינה נמשך בחינת מרחב העצמי ובא בגלוי בהמרחב דבינה, והוא בחי' פנימיות בינה, שנמשך בה מבחי' פנימיות החכמה שהיא פנימיות עתיק. וזהו ענין נתינת מעשר ללויים, שצריך להעלות את בחי' המלכות שנקראת מעשר לבחי' הבינה, ועד כפי שנמשך בה מרחב העצמי.\nד) <b>וביאור</b> הענין, דהנה, ספירת המלכות היא שרש הנבראים, ואופן התהוות הנבראים מספירת המלכות הוא בדרך התלבשות, שזהו מ\"ש<sup data-n=\"1282\">25</sup> בראשית ברא אלקים, וכמשנ\"ת במאמרים הקודמים<sup data-n=\"1283\">26</sup> בענין ההפרש בין ההתהוות שמשם אלקים לההתהוות שמשם הוי', שההתהוות שמשם הוי' היא התהוות שבדרך ממילא, וכמ\"ש<sup data-n=\"1284\">27</sup> כי הוא צוה ונבראו, שזהו לפי שהיא התהוות שבדרך קירוב, אמנם בכדי שתהי' התהוות היש, ובפרט יש נפרד, יש צורך בהתהוות שבדרך התלבשות דוקא, שזוהי ההתהוות שמשם אלקים, שהתהוות זו אינה כענין עילה ועלול, כי אם התהוות שבדרך ריחוק דוקא, עד שנעשה יש נפרד, וזהו אופן ההתהוות שמצד ספירת המלכות. אמנם תכלית הבריאה היא כמ\"ש<sup data-n=\"1285\">28</sup> אשר ברא אלקים לעשות, לתקן<sup data-n=\"1286\">29</sup>, והתיקון הוא עי\"ז שיהי' ויכולו השמים והארץגו'<sup data-n=\"1287\">30</sup>, ויכולו מלשון כליון וצמאון<sup data-n=\"1288\">31</sup>, והו\"ע העלאת המלכות לבינה, היינו, שגם העולמות שהם בבחי' יש לפי שנתהוו מצד המלכות, יהי' בהם הכליון והצמאון שמצד הבינה. וזהו גם מ\"ש<sup data-n=\"1289\">32</sup> ברוך הוי' אלקי ישראל מן העולם ועד העולם, שהם ב' בחי' עולמות, עלמא דאתכסיא ועלמא דאתגליא, בינה ומלכות, שבהם ההפרש בין דעת עליון שמלמעלמ\"ט לדעת תחתון שמלמטלמ\"ע, והיינו, שהדעה שלמטה היא שלמטה יש ולמעלה אין, לפי שהנברא מרגיש את עצמו ליש, אלא שמשיג ובא גם לידי הרגשה שישנו אין שמהווה ומקיים אותו, וזהו בחי' עלמא דאתגליא. אך הכוונה היא שיומשך מן העולם ועד העולם, שבבחי' עדאת\"ג יומשך הביטול דדעת עליון שבעדאת\"כ, היינו, שיורגש בהנבראים שכל מציאותם היא כפי שהם כלולים במקורם, וכמו דגים שבים שמיד שפורשים מן הים אין בהם חיות כלל<sup data-n=\"1290\">33</sup>, כיון שכל מציאותם היא בהיותם בתוך הים, כמים לים מכסים<sup data-n=\"1291\">34</sup>, והיינו שיהי' בהם לא רק הביטול שמצד הרגש כח הפועל שבנפעל, אלא שיורגש בהם גם הביטול שמבחי' כי הוא צוה ונבראו.\nה) <b>אמנם</b> ע\"פ משנת\"ל שגם הבינה היא בצמצום, והתכלית היא להמשיך בחי' מרחב העצמי, הרי מובן שלא מספיק ענין העלאת המלכות לבינה, שגם בעדאת\"ג יהי' הביטול דדעת עליון, אלא צריך להמשיך בחי' נעלית יותר, שזהו בחי' א-ל דעות הוי'<sup data-n=\"1292\">35</sup>, שכולל ב' הדעות יחד (ע\"ד המבואר בלקו\"ת ד\"ה ושמתי כדכד<sup data-n=\"1293\">36</sup>, להוי כדין וכדין), לפי שהוא למעלה מב' הדעות, שלכן כוללם יחד. וזהו\"ע בחי' מרחב העצמי. ובחי' זו נמשכת בספירת המלכות דוקא, וכמ\"ש<sup data-n=\"1294\">37</sup> מן המיצר קראתי גו' ענני במרחב, שהמשכת המרחב העצמי היא בהמיצר דמל' דוקא. וע\"ד מעלת בעלי תשובה על צדיקים, שעבודתם היא בחילא יתיר<sup data-n=\"1295\">38</sup>, להיות שעד הנה היתה נפשם בארץ צי' וצלמות כו'<sup data-n=\"1296\">39</sup>. וכמו\"כ יובן גם בענין הנבראים שנתהוו מספירת המלכות להיות בבחי' יש ודבר נפרד, שמצד זה יש אצלם הצמאון דמן המיצר, ועי\"ז נמשך בחי' מרחב העצמי.וזהו גם ענין התפלה שיש בה ב' בחי', תפלת עני ותפלת עשיר<sup data-n=\"1297\">40</sup>, והיינו, שההתחלה היא בבחי' תפלת עני, שעי\"ז נעשה המשכת האור שבערך הנבראים להיות מילוי החסרון, אבל המשכה זו היא רק די מחסורו אשר יחסר לו, ואין אתה מחוייב לעשרו<sup data-n=\"1298\">41</sup>, ואח\"כ היא בחי' תפלת עשיר, המשכת בחי' מרחב העצמי, שהו\"ע העשירות, בלי גבול. והמשכת המרחב העצמי היא בבחי' המיצר דמלכות דוקא. וזהו שאמרו רז\"ל<sup data-n=\"1299\">42</sup> שהטעימן הקב\"ה להאבות בעוה\"ז מעין עוה\"ב, כמ\"ש באברהם<sup data-n=\"1300\">43</sup> והוי' ברך את אברהם בכל, ואמרו רז\"ל<sup data-n=\"1301\">44</sup> בת היתה לאברהם אבינו ובכל שמה, ומבאר כ\"ק אדמו\"ר הצ\"צ באור התורה<sup data-n=\"1302\">45</sup>, שבחי' כל הו\"ע כל דאחיד בשמיא ובארעא<sup data-n=\"1303\">46</sup>, דבכללות הוא בחי' די מחסורו, ובחי' בכל הוא למעלה מבחי' כל, והו\"ע העשירות, בחי' מרחב העצמי. והמשכת בחי' בכל היא בבחי' בת דוקא, היינו בבחי' המלכות שנקראת בת, דאף שאמרו רז\"ל<sup data-n=\"1304\">47</sup> לא זז מחבבה עד שקראה בתי כו' עד שקראה אחותי כו' עד שקראה אמי, מ\"מ, אמיתית העלי' היא למעלה גם מבחי' אמי, בחי' הבינה, כי, התכלית היא בחי' העשירות והמרחב העצמי, וענין זה נמשך בבחי' בת דוקא, בחי' בת ציון<sup data-n=\"1305\">48</sup>. וזהו ג\"כ מ\"ש<sup data-n=\"1306\">49</sup> אז תשמח בתולה (בחי' בת, כנס\"י) במחול, שענין המחול הוא הקירוב שאחרי הריחוק, והיינו, שלאחרי הריחוק נעשה קירוב גדול יותר, ואז גם השמחה היא גדולה יותר (כמשל בן מלך שהי' בשבי' ושב אל אביו המלך, שאז השמחה והתענוג הם ביותר<sup data-n=\"1307\">50</sup>). והענין בזה, ששמחה היא בספירת הבינה<sup data-n=\"1308\">51</sup>, וגם תשובה היא בספירת הבינה<sup data-n=\"1308\">51</sup>, אמנם התכלית הוא המרחב העצמי שנתגלה בבינה. וזהו שבתשובה יש בחי' תשוב ה' תתאה ויש בחי' תשוב ה' עילאה<sup data-n=\"1309\">52</sup>, והיינו, שהיא למעלה גם מבחי' ה' עילאה, בינה, דהיינו בחי' המרחב העצמי דוקא. וזוהי גם השמחה היתירה שבאה אחר הריחוק דוקא, שדוקא מן המיצר נעשה ענני במרחב.ו) <b>וזהו</b> עשר תעשר, עשר בשביל שתתעשר, שנתינת המעשר צריך להיות ללוי, והיינו, שצריך להעלות את בחי' המלכות (שנקראת מעשר) לבחי' בינה (מדריגת הלויים), אבל, ענין זה הוא בחי' די מחסורו אשר יחסר לו, ועל זה מוסיף בשביל שתתעשר, שהוא המשכת בחי' העשירות והמרחב עצמי שנמשך ע\"י הבינה בבחי' המלכות, וכנ\"ל שדוקא מצד הריחוק באים לקירוב היותר גדול.\n<b>וזהו</b> ג\"כ ענין חודש אלול, דהנה, אלול הוא ר\"ת <b>א</b>ני <b>ל</b>דודי <b>ו</b>דודי <b>ל</b>י<sup data-n=\"1310\">53</sup>, היינו, שבתחילה צ\"ל אני לדודי ואח\"כ ודודי לי, שהו\"ע העבודה שמלמטה למעלה, שזהו אופן העבודה דחודש אלול עד יוהכ\"פ, ועבודה זו היא בבחי' לב נשבר ונדכה, ועי\"ז בא אח\"כ לשמחה היותר גדולה בשמע\"צ, שזהו מש\"נ אז תשמח בתולה במחול, אז בגימטריא שמונה, והו\"ע גילוי השמחה בשמיני עצרת<sup data-n=\"1311\">54</sup>, שהוא שמן בכל השמנונית והעשירות דמרחב העצמי בבחי' בלי גבול, וגילוי זה בא ע\"י העבודה דלב נשבר ונדכה בחודש אלול, כי, מן המיצר דוקא נעשה ענני במרחב, המשכת המרחב העצמי, כפי שנמשך בכתיבה וחתימה טובה לשנה טובה ומתוקה, בבני חיי ומזוני רויחי, למטה מעשרה טפחים.\n**********<b>בס\"ד. שיחת ש\"פ ראה, מבה\"ח אלול, ה'תשי\"ט</b>.\nבלתי מוגה\n<b>א</b>. התחלת פרשתנו היא: \"ראה אנכי נותן לפניכם היום ברכה וקללה, את הברכה אשר תשמעו גו' והקללה אם לא תשמעו גו'\".\nוידועה השאלה<sup data-n=\"1312\">1</sup>: מדוע גבי ברכה נאמר לשון \"אשר\" (\"אשר תשמעו\"), הרי ברכה זו היא <b>על תנאי</b> [וכפי שמבהיר רש\"י: \"את הברכה – <b>על מנת</b> אשר תשמעו\"], וא\"כ הול\"ל בלשון \"<b>אם</b>\", כמ\"ש גבי קללה \"אם לא תשמעו\", ולמה נאמר בלשון \"אשר\"?\nיש מתרצים<sup data-n=\"1313\">2</sup>, שכיון ש\"לא ידח ממנו נדח\"<sup data-n=\"1314\">3</sup>, הרי בודאי שסוכ\"ס יזכה כאו\"א מישראל לברכה, ולכן לא נאמרה הברכה בלשון \"אם\", אלא בלשון \"אשר\", שהוא לשון ודאי; משא\"כ בנוגע לקללה אי אפשר לומר בלשון ודאי, אלא רק בלשון \"אם\", דכיון שהאדם הוא בעל בחירה, הרי בידו לבחור בטוב, ולהיות במדריגת הבינוני (ש\"היא מדת כל אדם ואחרי' כל אדם ימשוך\"<sup data-n=\"1315\">4</sup>) ש\"לא עבר עבירה מימיו ולא יעבור לעולם\"<sup data-n=\"1316\">5</sup>, ואז לא יהי' צורך בענין הקללה כלל.\nאבל, אין זה ביאור מספיק, שהרי מצינו שנאמר לשון \"אם\" גם בנוגע לקו הטוב, כמו: \"אם בחוקותי תלכו\"<sup data-n=\"1317\">6</sup>, \"אם בקולו תשמעו\"<sup data-n=\"1318\">7</sup>.\nויש מתרצים<sup data-n=\"1319\">8</sup>, שהטעם שנאמר לשון \"אשר\" הוא לפי שלשון זה הוא סיוע ונתינת כח מלמעלה לקבלת הברכה (ע\"י הענין ד\"תשמעו אל מצוות גו'\").\nאבל, גם תירוץ זה אינו מספיק, שהרי גם לשון \"אם\" מורה על סיוע ונתינת כח, כדברי הגמרא<sup data-n=\"1320\">9</sup> עה\"פ \"אם בחוקותי תלכו\", \"אין אם אלא לשון תחנונים\", וידוע שענין התחנונים שלמעלה הוא סיוע ונתינת כח<sup data-n=\"1321\">10</sup>.<b>ב</b>. ויש להקדים – שלא מדובר כאן על הזמן דלעתיד, כאשר \"את רוח הטומאה אעביר מן הארץ\"<sup data-n=\"1322\">11</sup>, וכל הענינים יהיו בקו הטוב, דכיון שלא יהי' אז ענין הבחירה (ולכן יהיו אז \"שנים אשר גו' אין גו' בהם חפץ\"<sup data-n=\"1323\">12</sup>), הרי גם ענין הברכה לא יהי' אז בשלימות; אלא המדובר הוא על הזמן דעתה, ימים אשר <b>יש</b> בהם חפץ, ואעפ\"כ ישנם חילוקי לשונות – שבפסוקים \"בחוקותי תלכו\" ו\"בקולו תשמעו\" נאמר לשון \"אם\", ואילו בפ' ראה נאמר לשון \"אשר\".\nוהביאור בזה<sup data-n=\"1324\">13</sup>:\n\"אם בחוקותי תלכו\" – קאי על עבודת הצדיקים, שעבודתם היא הליכה בדרך ישרה, עבודת התורה והמצוות: \"בחוקותי תלכו\" – \"שתהיו עמלים <b>בתורה</b>\" (כפירוש רש\"י, מספרא), \"ואת מצוותי תשמרו\" – קיום המצוות.\n\"אם בקולו תשמעו\" – קאי על עבודת התשובה, כדאיתא בגמרא<sup data-n=\"1325\">14</sup> ששאלו את משיח \"אימתי קאתי מר\", והשיב \"היום\" – \"היום אם בקולו תשמעו\"&lt;7&gt;, והרי ההכנה לגאולה היא תשובה, כמארז\"ל<sup data-n=\"1326\">15</sup> \"ישראל שעושין תשובה נגאלין\" (וכהוספת הרמב\"ם<sup data-n=\"1327\">16</sup> ורבנו הזקן באגרת התשובה<sup data-n=\"1328\">17</sup> – \"<b>מיד</b>\"). וכן מוכח מכללות הסוגיא שם, דקאי על ענין התשובה.\nואילו בפרשתנו מדובר אודות <b>ב' העבודות</b>, עבודת הצדיקים ועבודת התשובה, שזהו \"ברכה וקללה\": \"ברכה\" – עבודת הצדיקים, ו\"קללה\" – עבודת התשובה, כדלקמן.\n<b>ג</b>. ובהקדם הביאור במש\"נ בנוגע לב' הענינים דברכה וקללה – \"ראה אנכי נותן לפניכם\":\nהפירוש \"לפניכם\" (ולא \"לכם\") הוא – \"לפנימיותכם\"<sup data-n=\"1329\">18</sup>, ע\"ד המבואר בפירוש הכתוב<sup data-n=\"1330\">19</sup> \"ואלה המשפטים אשר תשים לפניהם\", ש\"לפניהם\" פירושו \"לפנימיותם\"<sup data-n=\"1331\">20</sup>.ולכאורה, בשלמא בנוגע לברכה מובן הפירוש ד\"לפניכם\", \"לפנימיותכם\" – שקיום המצוות יהי' בפנימיות, ולא באופן ד\"פנו אלי עורף\"<sup data-n=\"1332\">21</sup>, ועי\"ז יהי' גם <b>שכר</b> המצוות (שהו\"ע הברכה) בפנימיות, דהיינו שיחדור (\"דורכנעמען\") באדם כולו, מן הקצה אל הקצה.\nובסגנון אחר – שהשכר דבני חיי ומזוני רויחי יהי' בפנימיות: \"בני\" – בנים עוסקים בתורה ובמצוות; \"חיי\" – לא סתם לחיות (\"אָפּלעבן\") מאה ועשרים שנה, אלא שהשנים יהיו מלאים בתוכן פנימי של תורה ומצוות; \"ומזוני רויחי\" – לא רק כדי להשקיט את רעבונו, אלא גם כדי להרגיש את \"מוצא פי הוי'\"<sup data-n=\"1333\">22</sup> שבמאכל.\nאבל בנוגע לענין הקללה – איך שייך שיהי' הדבר בפנימיות? הרי ידוע שיהודי אינו רוצה וגם אינו יכול להיות נפרד מאלקות<sup data-n=\"1334\">23</sup>, ומה שעובר לפעמים עבירה, אין זה אלא לפי ש\"נכנס בו רוח שטות\"<sup data-n=\"1335\">24</sup>, וא\"כ מובן שאין זה בפנימיות אלא בחיצוניות בלבד. וכמ\"ש הרמב\"ם<sup data-n=\"1336\">25</sup> בביאור הטעם שגט מעושה בישראל כשר, כי בפנימיותו \"רוצה להיות מישראל ורוצה הוא לעשות כל המצוות ולהתרחק מן העבירות\". וא\"כ, איך שייך לומר בנוגע לענין הקללה \"לפניכם\", \"לפנימיותכם\"?\nוכן בנוגע ללשון \"נותן\" – ענין של מתנה, ש\"כל הנותן בעין יפה הוא נותן\"<sup data-n=\"1337\">26</sup> – הרי זה שייך רק בנוגע לענין הברכה, ולא על ההיפך ח\"ו.\nוכן בנוגע ללשון \"אנכי\" – שהוא למעלה משמות הוי' ואלקים, כמ\"ש במתן-תורה<sup data-n=\"1338\">27</sup> \"אנכי הוי' אלקיך\" (שהסדר בזה הוא מלמעלה למטה: \"אנכי\", אח\"כ \"הוי'\", ואח\"כ \"אלקיך\"), \"אנכי מי שאנכי\"<sup data-n=\"1339\">28</sup>, \"דלא אתרמיז לא בשום אות ולא בשום קוץ\"<sup data-n=\"1340\">29</sup> – איך שייך שמשם יומשך ענין של היפך הברכה?\nועכצ\"ל, שפירוש \"קללה\" כאן אינו כפשוטו ח\"ו, אלא ע\"ד מ\"ש<sup data-n=\"1341\">30</sup> \"ויהפוך ה' אלקיך לך את הקללה לברכה\".וע\"ד המבואר<sup data-n=\"1342\">31</sup> בנוגע לענין הקללות שבתוכחה, בפרשת בחוקותי ובפרשת תבוא, שאינם קללות כפשוטו ח\"ו, אלא <b>אדרבה</b> – ברכות נעלות יותר, ודוקא מצד גודל מעלתן נאמרו באופן שלא תזיק להן עינא בישא של המקטרגים. וכפי שמצינו בגמרא<sup data-n=\"1343\">32</sup> ברכות שנאמרו באופן שהזולת הי' יכול לפרשם באופן הפכי, מטעם הנ\"ל.\nותוכן הענין – שברכות אלו נמשכות מחסדים המכוסים שלמעלה מחסדים הגלויים, והכוונה היא שגם החסדים המכוסים יומשכו בטוב הנראה והנגלה.\nוע\"פ הידוע שכל המשכה מלמעלה באה ע\"י עבודה המתאימה להמשכה זו, כיון ש\"כל מדותיו של הקב\"ה מדה כנגד מדה\"<sup data-n=\"1344\">33</sup>, הרי מובן, שכדי להמשיך מחסדים המכוסים, צריכה להיות העבודה ד\"בכל מאדך\" (שלמעלה מבחי' \"בכל לבבך ובכל נפשך\")<sup data-n=\"1345\">34</sup>, שהו\"ע העבודה דפנימיות הנפש, ובכללות הו\"ע עבודת התשובה שהיא \"בחילא יתיר\"<sup data-n=\"1346\">35</sup> (למעלה מעבודת הצדיקים שהיא בסדר מסודר), ומגעת בפנימיות הנפש; ולכן גם למעלה מגעת עבודה זו בבחי' מאד שלמעלה, פנימיות אלקות.\nוכשם שהתשובה פועלת באדם ש\"זדונות נעשות לו כזכיות\"<sup data-n=\"1347\">36</sup> – הנה עי\"ז פועלים גם למעלה \"ויהפוך גו' את הקללה לברכה\", כיון שעבודת התשובה מגעת בבחי' מאד שלמעלה, ששם אין מקום לקללות (ע\"ד פתגם אדמו\"ר האמצעי<sup data-n=\"1348\">37</sup> \"כשאבא קורא הערט זיך ניט קיין קללות\"), והכל נהפך לברכה, בטוב הנראה והנגלה.\nועפ\"ז מובן שמ\"ש \"ראה אנכי נותן לפניכם\" קאי על שני הענינים – עבודת הצדיקים (\"ברכה\") ועבודת התשובה (\"קללה\"), ואדרבה – ענין זה הוא בתוקף עוד יותר בעבודת התשובה, שמגעת בפנימיות יותר, כנ\"ל.\n<b>ד</b>. ועפ\"ז יובן טעם חילוקי הלשונות בכתובים – שגבי \"בחוקותי תלכו\" ו\"בקולו תשמעו\" נאמר הלשון \"אם\", ואילו בפרשתנו נאמר הלשון \"אשר\":\nבב' הכתובים \"בחוקותי תלכו\" ו\"בקולו תשמעו\" – כיון שבכלאחד מהם מדובר אודות <b>קו אחד</b>, הקו דעבודת הצדיקים (\"בחוקותי תלכו\") או הקו דעבודת התשובה (\"בקולו תשמעו\"), לכן נאמר בהם לשון \"אם\", כיון שאין וודאות שהעבודה תהי' בקו זה, שהרי יתכן שתהי' העבודה בקו השני.\nמשא\"כ בפרשתנו שמדובר אודות <b>ב' הקוים</b> – הרי ודאי הדבר שאצל כאו\"א מישראל יהי' אחד משני הקוים,\n– בביאת המשיח יהי' כאו\"א מישראל שייך <b>לשני</b> הענינים, כמאמר<sup data-n=\"1349\">38</sup> \"משיח אתא לאתבא צדיקייא בתיובתא\"; אבל גם קודם לכן, הנה מצד \"לא ידח ממנו נדח\", יהי' כאו\"א מישראל שייך עכ\"פ <b>לאחת</b> מב' עבודות אלו –\nולכן נאמר \"אשר\", לשון ודאי.\n***\n<b>ה</b>. ספר משנה-תורה נאמר לדור שנכנסו לארץ (כמובא בתניא<sup data-n=\"1350\">39</sup>), בתור הכנה להכניסה לארץ. ולכן נאמרו בו הרבה מצוות התלויות בארץ.\n[ואף שקצת מהם נאמרו גם בספרים שלפנ\"ז – הרי מה שנזכרו בספרים אלו הוא מצד טעם מיוחד, וכמו בפ' שלח, שכיון שנפלה רוחם מצד מעשה המרגלים, לכן \"בישר להם שייכנסו לארץ\"<sup data-n=\"1351\">40</sup>, ועד\"ז בנוגע לשאר המקומות שנזכר אודות מצוות התלויות בארץ. משא\"כ בספר דברים נאמרו מצוות התלויות בארץ בהתאם לענינו של כללות הספר שהוא הכנה להכניסה לארץ].\nוביניהם ישנו גם הציווי שנאמר בפרשתנו<sup data-n=\"1352\">41</sup>: \"כי ירחיב הוי' אלקיך את גבולך גו'\",\n– לכאורה הי' מקום לפרש דקאי על הזמן דלעתיד [ע\"ד מ\"ש גבי ערי מקלט (שזהו פנימיות הענין דחודש אלול<sup data-n=\"1353\">42</sup>) \"ואם ירחיב ה' אלקיך את גבולך גו' ויספת לך עוד שלש ערים גו'\"<sup data-n=\"1354\">43</sup>], שאז תהי' הרחבה אמיתית. אבל, הפירוש האמיתי הוא דקאי על הכניסה לארץ ישראל, שזהו ענין של הרחבה לגבי המצב שקודם הכניסה לארץ ישראל –\"בכל אות נפשך תאכל בשר וגו'\".\n<b>ו</b>. נתבאר תוכן מחלוקת ר' ישמעאל ור' עקיבא<sup data-n=\"1355\">44</sup> אם במדבר נאסר להם בשר תאוה, או אדרבה הותר להם בשר נחירה (בפנימיות הענינים) – שאכילת ובירור בשר תאוה אפ\"ל רק כשישנה הרחבה בכחות הרוחניים<sup data-n=\"1356\">45</sup>, משא\"כ במדבר שבהיותם נשמות בגופים היו שייכים לענינים רוחניים בלבד<sup data-n=\"1357\">46</sup>; ואעפ\"כ לדעת ר\"ע הותר להם בשר נחירה (אף שאכילת בשר<sup data-n=\"1358\">47</sup> הו\"ע של ירידה גדולה<sup data-n=\"1359\">48</sup>), כי, מצד מעלתם הי' בכל עשיותיהם (גם בענין של ירידה) איזה ענין של בירור וזיכוך<sup data-n=\"1360\">49</sup> (ומ\"מ לא הוצרכו לשחיטה<sup data-n=\"1361\">50</sup>, ולדעת הרמב\"ם נאסר להם בשר שחיטה, שהי' נחשב כמו חולין בעזרה<sup data-n=\"1362\">51</sup>) – הוגה ע\"י כ\"ק אדמו\"ר שליט\"א (באידית), ונדפס בלקו\"ש ח\"ד ע' 1108 ואילך.\n***<b>ז</b>. צוה לנגן ואמר מאמר ד\"ה עשר תעשר גו'.\n***\n<b>ח</b>. עומדים לקרוא עתה \"שופטים ושוטרים תתן לך בכל שעריך גו'\"<sup data-n=\"1363\">52</sup>, שתוכנה, שהאדם צריך לשפוט עצמו בכל הענינים.\nוהרי זהו תוכן העבודה דחודש אלול<sup data-n=\"1364\">53</sup>, כפי שמסר לנו כ\"ק מו\"ח אדמו\"ר<sup data-n=\"1365\">54</sup>, שחודש אלול הוא חודש החשבון, שבו יש לערוך את חשבון הנפש על כל הענינים שהיו בי\"א החדשים שלפנ\"ז, ובשנת העיבור – גם על חודש העיבור.\nוזהו \"שופטים ושוטרים גו' ושפטו את <b>העם</b> גו'\" – דקאי על כל איברי הגוף, כדאיתא בגמרא<sup data-n=\"1366\">55</sup> \"עיר קטנה זה הגוף, ואנשים בה מעט אלו אברים\", שכל אבר צריך לקיים בו מצוה מיוחדת, וכפי שמצינו בספרי מוני המצוות<sup data-n=\"1367\">56</sup> שמונים פרטי המצוות השייכים לכל אבר, וכללות רמ\"ח מצוות עשה הם כנגד רמ\"ח איברי הגוף<sup data-n=\"1368\">57</sup>. ובענין זה צריך להיות המשפט – \"משפט צדק\" – כיצד ניצל האדם כל אבר במשך השנה, האם קיים בו את הענינים והמצוות שעליו לקיים בו.\nונוסף על ענין המשפט שע\"י ה\"שופטים\", יש צורך גם ב\"שוטרים\" – \"הרודין את העם . . במקל\"<sup data-n=\"1369\">58</sup>, שזהו המקל שבו רודים את היצר הרע, כמארז\"ל<sup data-n=\"1370\">59</sup> \"כשם שדרכו של כלב ללקות במקל כו'\".\n[וזהו הטעם שמונה במדרש<sup data-n=\"1371\">60</sup> את מספר הכלבים שהיו ליעקב אבינו – דלכאורה למאי נפק\"מ? – כי, כלבים הם ענין הפכי כו', ויעקב הפכם לטוב, ע\"י העבודה ד\"מקל\"].\n<b>ט</b>. והנה, בהמשכים של כ\"ק אדמו\"ר מהר\"ש<sup data-n=\"1372\">61</sup> מבואר בארוכה שישנם ב' בחי' מקל: (א) מקל הנ\"ל שבו רודים את היצה\"ר, (ב) \"מקל נועם\"<sup data-n=\"1373\">62</sup> שיהי' לעתיד.\nומ\"ש \"שופטים ושוטרים תתן לך בכל שעריך\" – הרי זה (לא רק ע\"י המקל שרודין בו את היצה\"ר, אלא) גם ע\"י \"מקל נועם\".והענין בזה:\nענינו של \"שער\" (\"שעריך\") – שיש בו כמה אופנים: שער של בית, שער של חצר, ועד לשער של עיר, דקאי על כללות העולם, שנתהווה מבחי' \"עיר אלקינו\"<sup data-n=\"1374\">63</sup> – שהוא משמש לכניסה ויציאה.\nכלומר: צריך לדעת שלא די בכך שהאדם מקבל מהעולם את הענינים שהוא זקוק להם (\"יציאה\"), ומלבד זה אין לו קשר עם העולם, אלא עליו גם להשפיע השפעת וגילוי אלקות בעולם (\"כניסה\").\nיש צורך לפתוח \"שער\" ולעשות \"דרך\" – \"ושמרו <b>דרך </b>הוי' לעשות צדקה ומשפט\"<sup data-n=\"1375\">64</sup>, וכפי שמבאר אדמו\"ר האמצעי<sup data-n=\"1376\">65</sup>, שענינה של \"דרך\" הוא שעל ידה מקשרים אפילו פינה נידחת עם \"עיר הבירה\", ועד ל\"היכל המלכות\", ועד לחדר לפנים מחדר, ששם נמצא המלך בעצמו.\nוזהו תוכן העבודה ד\"שער\" ו\"דרך\" – לקשר גם פינה נידחת שבקצה העולם עם מלך מלכי המלכים הקב\"ה, בב' האופנים ד\"כניסה\" ו\"יציאה\" – העלאה והמשכה.\nועבודה זו צריכה להיות באופן ד\"מקל נועם\", דהיינו שההשפעה בעולם היא ע\"י נועם ואהבת ישראל, שצריכה להיות לכאו\"א מישראל, כמאמר הבעש\"ט<sup data-n=\"1377\">66</sup> שאהבת ישראל צ\"ל גם ליהודי הנמצא בקצוי תבל.\n<b>י</b>. וזהו \"שופטים ושוטרים תתן לך בכל שעריך\":\nלכל לראש צריך להיות ענין המשפט (\"שופטים\"): כשם שבגשמיות, כשעוברים את גבול המדינה מבקרים ובודקים מה מותר להביא למדינה זו – כן הוא ברוחניות, שכאשר נוסעים בשליחות לאיטליא, לאוסטרליא, לאנגליא או לאה\"ק ת\"ו, צריך להביא לשם את הענינים שעל ידם בונים ומחזקים את היכל כ\"ק מו\"ח אדמו\"ר, ש\"אתפשטותא דמשה בכל דרא ודרא\"<sup data-n=\"1378\">67</sup>, ו\"יפתח בדורו כשמואל בדורו\"<sup data-n=\"1379\">68</sup>, ששמואל שקול כנגד משה ואהרן<sup data-n=\"1380\">69</sup>.\nואופן העבודה צ\"ל ע\"י הענין ד\"שוטרים\", ובאופן ד\"מקל נועם\", שע\"י דרכי נועם מקרבים אפילו פינה נידחת (כנ\"ל).ובפרט בחודש אלול, שבו ישנו גילוי י\"ג מדות הרחמים, שהם כנגד<sup data-n=\"1381\">70</sup> י\"ג מדות שהתורה נדרשת בהן<sup data-n=\"1382\">71</sup>.\n**********",[["1258","1","פרשתנו (ראה) יד, כב."],["1259","2","תענית ט, א."],["1260","3","ראה ב\"מ לא, א."],["1261","4","אבות פ\"א מ\"ג."],["1262","5","מלאכי ג, יו\"ד. תענית שם."],["1263","6","בכל הבא לקמן – ראה ד\"ה עשר תעשר עטר\"ת (סה\"מ עטר\"ת ס\"ע תרכא ואילך)."],["1264","7","תקו\"ז תי\"ז. פרדס שער כג (שער ערכי הכינויים) ערך מעשר. ועוד."],["1265","8","רש\"י ר\"פ וירא. וראה גם ב\"ר פמ\"ח, ט."],["1266","9","שער ט (שער המכריעין) פ\"ג."],["1267","10","מסעי פט, סע\"ד."],["1268","11","ראה ביאורי הזהר לאדהאמ\"צ ק, א ואילך. ולהצ\"צ (כרך א) ע' תצו. המשך תער\"ב ח\"ג ע' א'שנז ואילך. ובכ\"מ."],["1269","12","קרח יח, ג."],["1270","13","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380535\" data-slug=\"likkutei-torah\" data-id=\"4001380535\">ראה זח\"ג קעח, ב</a>. לקו\"ת קרח נה, ב."],["1271","14","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381043\" data-slug=\"likkutei-torah\" data-id=\"4001381043\">לקו\"ת</a> דרושים לסוכות עט, ד. שה\"ש ב, ד. ובכ\"מ."],["1272","15","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381045\" data-slug=\"likkutei-torah\" data-id=\"4001381045\">לקו\"ת סוכות פ, ב</a>. ביאוה\"ז לאדהאמ\"צ קלג, א. ולהצ\"צ ח\"א ע' קב."],["1273","16","ראה זהר ח\"ג לט, א. פח, ב. קעז, ב."],["1274","17","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380472\" data-slug=\"likkutei-torah\" data-id=\"4001380472\">לקו\"ת שלח מ, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380478\" data-slug=\"likkutei-torah\" data-id=\"4001380478\">מא, ג</a>. ד\"ה ושאבתם תרמ\"ד. תרנ\"ד. תרח\"ץ. ד\"ה כי תבואו דש\"פ שלח תשי\"ב (תו\"מ ח\"ו ע' 8). וש\"נ."],["1275","18","ברכות יד, סע\"ב."],["1276","19","צו ו, טו."],["1277","20","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380789\" data-slug=\"likkutei-torah\" data-id=\"4001380789\">זח\"ג קמב, א</a>. עץ חיים שער ח (שער דרושי נקודות). לקו\"ת ראה יח, ב."],["1278","21","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא פ\"ג</a>. ובכ\"מ."],["1279","22","פסחים ג, ב. חולין סג, ב."],["1280","23","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380042\" data-slug=\"likkutei-torah\" data-id=\"4001380042\">לקו\"ת בשלח א, א</a>. ביאוה\"ז לאדהאמ\"צ (עו, ד) ולהצ\"צ (ע' שסג-ד). ובכ\"מ."],["1281","24","הל' דעות פ\"ב ה\"ד."],["1282","25","בראשית א, א."],["1283","26","ד\"ה לא הביט דש\"פ חו\"ב י\"ב תמוז פ\"ג ואילך, וד\"ה אר\"א כל אדם לעמל נברא די\"ג תמוז פ\"ו (לעיל ע' 62 ואילך. ע' 87)."],["1284","27","תהלים קמח, ה."],["1285","28","בראשית ב, ג."],["1286","29","ראה ב\"ר פי\"א, ו. ובפרש\"י שם."],["1287","30","בראשית שם, א."],["1288","31","ראה אוה\"ת בראשית מב, ב ואילך."],["1289","32","תהלים קו, מח. וראה זח\"א קנג, ב. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560055\" data-slug=\"or-hatorah-hb\" data-id=\"8316560055\">אוה\"ת בראשית (כרך ג) תצד, א</a>. תקנא, א. המשך חייב אדם לברך תרל\"ח ע' ג'. ובכ\"מ."],["1290","33","ראה ברכות סא, ב. ע\"ז ג, ב."],["1291","34","לשון הכתוב – ישעי' יא, ט."],["1292","35","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380811\" data-slug=\"likkutei-torah\" data-id=\"4001380811\">שמואל-א ב, ג</a>. וראה לקו\"ת פרשתנו (ראה) כג, ד."],["1293","36","פרשתנו (ראה) כד, ד ואילך. כו, ג ואילך."],["1294","37","תהלים קיא, ה."],["1295","38","ראה זח\"א קכט, ב. מאמרי אדה\"ז תקס\"ה (כרך א) ע' תפז ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770283\" data-slug=\"or-hatorah-hb\" data-id=\"8316770283\">אוה\"ת שה\"ש (כרך ב) ע' תרנא</a> ואילך."],["1296","39","ירמי' ב, ו."],["1297","40","ראה זח\"א קסח, ב. ד\"ה תפלה למשה תר\"ס (סה\"מ תר\"ס ע' מט ואילך). ד\"ה פדה בשלום תשי\"ב (תו\"מ ח\"ד ע' 174). וש\"נ."],["1298","41","ראה כתובות סז, ב."],["1299","42","ב\"ב טז, סע\"ב ואילך."],["1300","43","חיי שרה כד, א."],["1301","44","ב\"ב שם."],["1302","45","חיי שרה קכה, ב."],["1303","46","ראה זהר ח\"א לא, א. ח\"ב קטז, א. ח\"ג רנז, סע\"א."],["1304","47","שהש\"ר פ\"ג, יא."],["1305","48","זכרי' ב, יד. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370165\" data-slug=\"torah-or\" data-id=\"3901370165\">תו\"א לו, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370168\" data-slug=\"torah-or\" data-id=\"3901370168\">לו, ד</a> ואילך. ועוד."],["1306","49","ירמי' לא, יב. וראה מאמרי אדמו\"ר הזקן תקס\"ה ח\"א ע' ריד ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650155\" data-slug=\"or-hatorah-hb\" data-id=\"8316650155\">אוה\"ת נ\"ך ח\"ב ע' תתפד</a> ואילך."],["1307","50","כ\"ה בזכרון אחדים (<b>המו\"ל</b>)."],["1308","51","ראה לקו\"ת שמע\"צ פו, ב."],["1309","52","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310075\" data-slug=\"tanya\" data-id=\"3401310075\">תניא אגה\"ת פ\"ד</a>. ובכ\"מ."],["1310","53","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380844\" data-slug=\"likkutei-torah\" data-id=\"4001380844\">שה\"ש ו, ג</a>. אבודרהם סדר תפלת ר\"ה. פע\"ח שער ר\"ה פ\"א. ב\"ח לטור או\"ח סימן תקפא (ד\"ה והעבירו). לקו\"ת פרשתנו (ראה) לב, א ואילך."],["1311","54","ראה לקו\"ת פרשתנו כד, ד. כז, א-ב. ובכ\"מ."],["1312","1","ראה מפרשים עה\"פ. וראה גם שיחת ש\"פ ראה, מבה\"ח אלול תשט\"ז ס\"ב (תו\"מ חי\"ז ע' 167). וש\"נ."],["1313","2","ראה כלי יקר עה\"פ."],["1314","3","ע\"פ שמואל-ב יד, יד. וראה תניא ספל\"ט. הל' ת\"ת לאדה\"ז פ\"ד סה\"ג."],["1315","4","<a class=\"ft-cite\" href=\"#/read/tanya/3401310019\" data-slug=\"tanya\" data-id=\"3401310019\">תניא רפי\"ד</a>."],["1316","5","שם רפי\"ב."],["1317","6","ר\"פ בחוקותי."],["1318","7","תהלים צה, ז."],["1319","8","ראה אלשיך עה\"פ."],["1320","9","ע\"ז ה, סע\"א."],["1321","10","ראה סה\"מ ה'ש\"ת ע' 88. תש\"ב ע' 114 (נעתק ב\"היום יום\" כד אייר)."],["1322","11","זכרי' יג, ב."],["1323","12","קהלת יב, א. וראה שבת קנא, ב."],["1324","13","ראה ד\"ה ראה אנכי דש\"פ ראה עטר\"ת (סה\"מ עטר\"ת ס\"ע תרט ואילך). וראה גם שיחת ש\"פ עקב, מבה\"ח אלול תשח\"י סי\"א (תו\"מ חכ\"ג ע' 262). וש\"נ."],["1325","14","סנהדרין צח, א."],["1326","15","שם צז, ב."],["1327","16","הל' תשובה פ\"ז ה\"ה."],["1328","17","פי\"א (ק, א)."],["1329","18","ראה לקו\"ת פרשתנו יח, סע\"ד. סה\"מ שם ס\"ע תרי."],["1330","19","ר\"פ משפטים."],["1331","20","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370336\" data-slug=\"torah-or\" data-id=\"3901370336\">תו\"א משפטים עה, ג</a>."],["1332","21","ירמי' ב, כז. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380191\" data-slug=\"likkutei-torah\" data-id=\"4001380191\">לקו\"ת אחרי כו, ד</a>. ובכ\"מ."],["1333","22","עקב ח, ג. וראה לק\"ת להאריז\"ל עה\"פ."],["1334","23","ראה אג\"ק אדמו\"ר מוהריי\"צ ח\"ד ע' שפד (נעתק ב\"היום יום\" כה תמוז). שם ע' תקמז (נעתק ב\"היום יום\" כא סיון). ועוד."],["1335","24","סוטה ג, א."],["1336","25","הל' גירושין ספ\"ב."],["1337","26","ראה ב\"ב נג, רע\"א. וש\"נ."],["1338","27","יתרו כ, ב."],["1339","28","לקו\"ת פרשתנו שם. וראה זח\"ג יא, א."],["1340","29","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380641\" data-slug=\"likkutei-torah\" data-id=\"4001380641\">לקו\"ת פינחס פ, ב</a>. וראה זח\"ג רנז, ב."],["1341","30","תצא כג, ו."],["1342","31","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380282\" data-slug=\"likkutei-torah\" data-id=\"4001380282\">לקו\"ת בחוקותי מח, סע\"א</a> ואילך. ובכ\"מ."],["1343","32","מו\"ק ט, ב."],["1344","33","סנהדרין צ, סע\"א. וראה סוטה ח, ב ואילך."],["1345","34","ואתחנן ו, ה."],["1346","35","ראה זח\"א קכט, ב."],["1347","36","יומא פו, ב."],["1348","37","\"רשימות\" חוברת קיב ע' 8 (נעתק ב\"היום יום\" יז אלול)."],["1349","38","ראה זח\"ג קנג, ב. לקו\"ת דרושי שמע\"צ צב, ב. ובכ\"מ."],["1350","39","ספכ\"ה."],["1351","40","ראה פרש\"י שלח טו, ב. אוה\"ח שם."],["1352","41","יב, כ."],["1353","42","ראה שיחת ש\"פ עקב, מבה\"ח אלול תשי\"א ס\"ה ואילך (תו\"מ ח\"ג ס\"ע 285 ואילך). וש\"נ."],["1354","43","פ' שופטים יט, ח-ט."],["1355","44","חולין טז, ב."],["1356","45","וע\"ד מארז\"ל (פסחים מט, ריש ע\"ב) \"עם הארץ אסור לאכול בשר\", דכיון שאין לו בחי' בשר הרוחני, כלשון חז\"ל (ב\"ב כב, א) \"בישרא שמינא בי רבא\" – אינו יכול לברר את הבשר הגשמי (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380436\" data-slug=\"likkutei-torah\" data-id=\"4001380436\">לקו\"ת בהעלותך לא, ג</a> ואילך. ובכ\"מ)."],["1357","46","וע\"ד המבואר ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380916\" data-slug=\"likkutei-torah\" data-id=\"4001380916\">לקו\"ת (נצבים מט, ב</a>), ש\"יש בחי' אצילות גם בעשי'\", והיינו, שאצילות אינו \"אי-שם\" (\"ערגעץ וואו\"), אלא למטה בעוה\"ז, וראי' לזה – שהרי \"נשמת משה רבינו עליו השלום היתה מבחינת אצילות\", גם בהיותו למטה, כשעמד ליד פרעה ודבר עמו כו'.\nומכ\"ש בנוגע לבנ\"י בהיותם במדבר, שע\"י זיכוכם נעשו שייכים רק לרוחניות – שלכן ניזונו ממן, שהוא לחם המלאכים (ראה יומא עה, ב), ושתו מים מבארה של מרים, שהיתה מטהרת אפילו את המצורע (ראה שבת לה, א ובפרש\"י ד\"ה טהור), וענני הכבוד היו מכבסים את לבושיהם (מדרש תהלים כג, ב. דב\"ר ס\"פ תבא. פרש\"י עקב ח, ד)."],["1358","47","ובפרט שהיו יכולים לטעום טעם בשר גם באכילת המן, שהרי היו טועמים בו כל הטעמים (יומא עה, א)."],["1359","48","ולגבי ערך גודל מדריגת דור המדבר, הרי זה נחשב לירידה גדולה עוד יותר – ע\"ד שמצינו (שבת קיד, א) ש\"תלמיד חכם שנמצא רבב על בגדו חייב מיתה\", משא\"כ \"מרדעת של חמור\" (ועד\"ז \"עם הדומה לחמור\" (יבמות סב, א)), שבה לא נוגע ענין של רבב."],["1360","49","וכמו שהוא בנוגע לכל ישראל, שמחד גיסא, מצד גודל מעלתם הרי הירידה אצלם היא יותר מאשר אצל אוה\"ע, כי, כל הגבוה גבוה ביותר נופל למטה מטה יותר (ראה לקו\"ת פרשתנו יט, ג. ובכ\"מ), אבל לאידך גיסא, כיון ש\"ישראל . . פסקה זוהמתן\" (שבת קמו, רע\"א), לא יתכן שתהי' אצלם ההגשמה בדומה לאוה\"ע ש\"לא פסקה זוהמתן\" (ובפרט מצד אכילת שקצים ורמשים, כמבואר בגמרא (שם קמה, ב))."],["1361","50","(בענין השחיטה שהוא כדי למנוע צער בעלי חיים:) ולהעיר ממ\"ש בספרי קבלה (ס' התמונה תמונה ג אות ה – הובא בעבוה\"ק ח\"ב פל\"ד. של\"ה פרשתנו שעה, א) שענין זה נכלל במ\"ש (קדושים יט, יח) \"ואהבת לרעך כמוך\", \"ברור לו מיתה יפה\" (פסחים עה, א. וש\"נ)."],["1362","51","וע\"ד המבואר בענין יוסף הצדיק, שע\"י שמל את המצריים נעשית יניקת הלעו\"ז מקדושה (ראה גם תו\"מ חכ\"ב ע' 223 ובהערה 38 שם). ועד\"ז בנדו\"ד, שע\"י השחיטה במדבר היו נמשך ענין הקדושה במקום בלתי רצוי."],["1363","52","ר\"פ שופטים."],["1364","53","ראה שיחת ש\"פ ראה, מבה\"ח וער\"ח אלול תשי\"ד סט\"ז ואילך (תו\"מ חי\"ב ע' 183 ואילך). וש\"נ."],["1365","54","ראה סה\"מ תרצ\"ו ס\"ע 141. וש\"נ."],["1366","55","נדרים לב, ריש ע\"ב."],["1367","56","ספר חרדים (וראה גם תו\"מ חכ\"ב ריש ע' 256. חכ\"ג ס\"ע 59)."],["1368","57","ראה מכות כג, סע\"ב. זח\"א קע, ב."],["1369","58","פרש\"י עה\"פ."],["1370","59","שמו\"ר פ\"ט, ב."],["1371","60","ב\"ר פע\"ג, יא."],["1372","61","המשך וככה תרל\"ז פקט\"ו ואילך."],["1373","62","זכרי' יא, ז. וראה סנהדרין כד, א."],["1374","63","תהלים מח, ב."],["1375","64","וירא יח, יט."],["1376","65","ביאוה\"ז ר\"פ וישלח (יט, ב ואילך)."],["1377","66","ראה כש\"ט (הוצאת תשנ\"ט) בהוספות סקל\"ג. וש\"נ (נעתק ב\"היום יום\" טו כסלו. וראה שם ג אד\"א)."],["1378","67","תקו\"ז תס\"ט (קיב, רע\"א. קיד, רע\"א)."],["1379","68","ר\"ה כה, רע\"ב."],["1380","69","ברכות לא, ב. תנחומא קרח ה. פרש\"י קרח טז, ז."],["1381","70","ראה או\"ת להה\"מ ס\"פ בהעלותך. ובכ\"מ."],["1382","71","חסר סיום הענין (<b>המו\"ל</b>)."]]],[1400330014,"(הנחה בלתי מוגה)\n<b>כי</b> כארץ תוציא צמחה וכגנה זרועי' תצמיח כן אד' הוי' יצמיח צדקה ותהלה נגד כל הגוים<sup data-n=\"1383\">1</sup>. ומפרש רבינו בלקו\"ת<sup data-n=\"1384\">2</sup> דפסוק זה קאי על קיום התומ\"צ שנקראים בשם זריעה, כמ\"ש<sup data-n=\"1385\">3</sup> זרעו לכם לצדקה, וכשם שהצמיחה היא ע\"י זריעת גרעין בארץ, כך גם זריעת המצוות היא בישראל שהם בחי' ארץ, כמ\"ש<sup data-n=\"1386\">4</sup> ארץ חפץ, ועי\"ז נעשה הצמיחה. ובכללות ענין המצוות יש ג' מדריגות, שזהו אומרו כארץ תוציא צמחה, שהיא בחי' א', וכגנה זרועי' תצמיח הם ב' בחי', כי זרועי' הוא לשון רבים, ומיעוט רבים שנים<sup data-n=\"1387\">5</sup>. והענין בזה, דמ\"ש כגנה זרועי' תצמיח הם ב' הבחי' דמעשה המצוות וכוונת המצוות, שממעשה המצוות נעשית הצמיחה בג\"ע התחתון, ומכוונת המצוות נעשית הצמיחה בג\"ע העליון. ועז\"נ כגנה, שזהו כמו הגנן שמטפל בהזריעה כו'. אמנם ענין כארץ תוציא צמחה הוא בחי' נמוכה יותר, והיא הצמיחה אשר תצמח מעצמה בלי זריעה, שהרי יש פירות שצומחים מעצמן בלי זריעת גרעין, אלא שאינם משובחים כ\"כ כמו הפירות שצומחים ע\"י זריעה ונטיעה, אבל מ\"מ הרי זו גם צמיחה. וענינו במצוות הו\"ע מצוות מעשיות שנעשים בלי כוונה, כי אם בדרך מצות אנשים מלומדה<sup data-n=\"1388\">6</sup>, שגם עי\"ז נעשה צמיחה, והיינו לפי שהמצוות הם בארץ חפץ, בנ\"י, שיש בהם בחי' הרחימו שהיא האהבה מסותרת, ונכלל בה גם דחילו<sup data-n=\"1389\">7</sup>, ולכן נעשית עי\"ז הצמיחה. והנה, כל זה הוא במי שלא חטא ולא פגם ועבר את הדרך, אמנם במי שחטא ופגם ועבר את הדרך, הן בהעדר קיום מ\"ע והן כשעובר על ל\"ת, הנה על זה כתיב כן אד' הוי' יצמיח צדקה ותהלה, שהו\"ע הצמיחה וגילוי האור מלמעלה בר\"ה ויוהכ\"פ ועשי\"ת, והיינו, שע\"י עבודת התשובה והתגלות י\"ג מדה\"ר בחודש אלול עד יוהכ\"פ, שהם ארבעים ימי רצון<sup data-n=\"1390\">8</sup>,והיינו, שגם בחטא שהי' כמו חטא הראשון נאמר בהם מה הראשונים ברצון אף האחרונים ברצון<sup data-n=\"1391\">9</sup>, הנה עי\"ז יצמיח צדקה ותהלה נגד כל הגוים, והיינו, שגם כשחסר בתומ\"צ, וגם כשישנו ענין קליפת נוגה וגם ענין גקה\"ט, שזהו\"ע כל הגוים, מ\"מ יצמיח צדקה ותהלה, עד שגם זדונות נעשים לו כזכיות<sup data-n=\"1392\">10</sup>. וזהו כללות הענין דיגמה\"ר שבהם נאמר<sup data-n=\"1393\">11</sup> ויעבור הוי' על פניו ויקרא הוי' הוי', דפניו הו\"ע תומ\"צ שהם פנימיות הרצון, אמנם בחי' יגמה\"ר הם על פניו, שהם למעלה גם מהפנימיות דתומ\"צ, ולכן נאמר הוי' הוי' ב\"פ, קודם שיחטא ולאחר שיחטא<sup data-n=\"1394\">12</sup>, שגם אז הוא נושא עון ועובר על פשע, ועד שזדונות נעשים כזכיות.\nב) <b>ולהבין</b> מעלת יגמה\"ר שממשיכים האור גם כשחסר בעבודה דקיום תומ\"צ כו', הנה<sup data-n=\"1395\">13</sup> ענין הרחמים הוא בקו האמצעי, שהוא למעלה מב' הקוין, קו הימין וקו השמאל, שהם בהתחלקות ובהגבלה, שהרי על קו הימין יש התנגדות דקו השמאל, ועל קו השמאל יש המניעה שמצד קו הימין, אמנם קו האמצעי הרי לכאורה הוא נותן מקום לשניהם, אך האמת היא שקו האמצעי הוא למעלה משניהם, שלכן כולל אותם ומכריע ביניהם. וביאור מעלת קו האמצעי שהוא למעלה מב' הקוין, דעם היות שגם ב' הקוין עולים בכתר, הרי זה רק בחיצוניות הכתר, משא\"כ קו האמצעי עולה בפנימיות הכתר<sup data-n=\"1396\">14</sup>. ועוד חילוק בין קו האמצעי לב' הקוין, שבב' הקוין יש התחלקות מדריגות, וקו האמצעי הוא בכל המדריגות בשוה מתחלתו ועד סופו. ושני חילוקים אלו תלויים זה בזה, דכיון שקו הימין וקו השמאל שרשם בחיצוניות הכתר, שהוא הארה בלבד, לכן יש בהם התחלקות מדריגות, וקו האמצעי שהוא בפנימיות הכתר, שהוא בחי' עצם, הוא בכל המדריגות בשוה, כידוע ההפרש בין הארה לעצם, שהארה הנה ככל שנמשכת הרי היא מתמעטת ומתצמצמת, משא\"כ העצם הנה בכל מקום שנמשך הרי הוא בשוה.\n<b>ויובן</b> זה ממה שאנו רואים באדם למטה, שיש בו ג' קוין אלו, קו הימין הוא יד ימין ורגל ימין, קו השמאל הוא יד שמאל ורגל שמאל, וקו האמצעי הוא הראש והגוף עד סיומא דגופא. ולכאורה הרי הראש והמוחין (שהם הכחות הנעלים) הם בקו האמצעי. אמנם באמת הנה גםבהראש יש התחלקות ג' קוין, דמאחר שיש התחלקות קוין בידים וברגלים שהם בחי' המדות, חג\"ת ונה\"י, ושרש המדות הוא מהמוחין, הרי מוכח שגם בהמוחין יש התחלקות קוין, והיינו, שמוח החכמה הוא בקו הימין, ומזה נמשך אח\"כ יד ימין ורגל ימין, ומוח הבינה הוא בקו השמאל כו', ומוח הדעת בקו האמצעי. והנה, בב' הקוין, קו הימין וקו השמאל, יש חילוקי מדריגות, הרי אינו דומה מדריגת המוחין כפי שהם בעצם למדריגת המוחין שמהם נמשכים המדות ובפרט להמוחין שבמדות. וחילוק זה הוא בתוקף, שהרי יש ריחוק גדול בין המוחין להמדות, דכאשר הוא עסוק בשכל אזי אין מקום להתפעלות, וכאשר הוא בהתפעלות המדות אזי אי אפשר לו להשיג כו'. וכמו כן יש כמה מדריגות במדות גופא, וכמו במדת האהבה, שיש בה בחי' חב\"ד חג\"ת ונה\"י, דחב\"ד של האהבה הוא הטעם שמחייב את האהבה, אם מצד העילוי או לפי שהטיב עמו, וענינו בעבודה הוא החילוק בין קרבת אלקים טוב לקרבת אלקים לי טוב<sup data-n=\"1397\">15</sup>, והחג\"ת של האהבה הוא התעוררות והרגש האהבה, והנה\"י של האהבה הוא התגלות האהבה בדיבור כו'. וכמו\"כ גם במדת החסד שהיא חיצוניות לגבי האהבה (כמ\"ש באגה\"ק<sup data-n=\"1398\">16</sup>), יש בחי' חב\"ד חג\"ת ונה\"י, דחב\"ד של החסד הוא הטעם על החסד, והוא האהבה, שמפני שאוהב אותו (מצד העילוי אם מצד שהטיב עמו) הרי הוא מתעורר בחסדו עליו, והחג\"ת של החסד הוא הרגש החסד, והנה\"י הוא השפעת החסד בפועל. והרי ג' ענינים אלו הם חלוקים זה מזה, דבחב\"ד של החסד ישנו הטעם, ובחג\"ת ישנו רק ההרגש, ובנה\"י ישנה רק ההשפעה בפועל, היינו, שאין בהם לא טעם ולא הרגש, כי אם הפועל בלבד, שזהו הטעם שנה\"י נקראים בשם בדי ערבות<sup data-n=\"1399\">17</sup>, שאין בהם לא טעם ולא ריח. וכל זה הוא בקו הימין וקו השמאל. אבל קו האמצעי הוא בכל הבחי' בשוה, והיינו, שגם כפי שבא בבחי' היסוד סיומא דגופא, יש בזה כל העצם, וכידוע בענין אין קישוי אלא לדעת<sup data-n=\"1400\">18</sup>. וכן הוא גם בענין הרחמים, שהתעוררות הרחמים על זולתו הוא ע\"י ההרגש דוקא, שמרגיש את הזולת, ומתקשר ומתאחד עמו, ובמילא מתעורר ברחמים עליו. וכל זה הוא לפי שקו האמצעי מגיע בפנימיות הכתר, שהוא בחי' העצם, ולכן המשכתו היא עד סוף המדריגות, ובאופן שנמשך בכולם בשוה.<b>והנה</b> כמו\"כ הוא גם בענין התורה, שהיא בקו האמצעי, כמ\"ש<sup data-n=\"1401\">19</sup> זכרו תורת משה עבדי, דמשה מלגאו ויעקב מלבר<sup data-n=\"1402\">20</sup>, ששניהם הם בת\"ת, אלא שמשה מלגאו ויעקב מלבר, ולכן, גם כפי שהתורה ירדה למטה כו', ועד לטענות של שקר שזה אומר כך וזה אומר כך<sup data-n=\"1403\">21</sup>, הנה גם אז אין דברי תורה מקבלים טומאה<sup data-n=\"1404\">22</sup>, ויתירה מזה, שגם תלמידי חכמים שהם מקבלים מהתורה אין אש של גיהנם שולטת בהם<sup data-n=\"1405\">23</sup>, והיינו לפי שהתורה היא בקו האמצעי, שמגעת בהעצמי, והעצמי הוא בכל המדריגות בשוה. וזהו ג\"כ החילוק בין ג' האבות, שאברהם הוא בקו הימין, ועבודתו היא בעמוד הצדקה וגמ\"ח, כללות המצוות<sup data-n=\"1406\">24</sup>, ויצחק בקו השמאל, ועבודתו היא בעמוד העבודה, ויעקב בקו האמצעי, ועבודתו היא העמוד דתורה, הנה אברהם יצא ממנו כו' וכן יצחק יצא ממנו כו'<sup data-n=\"1407\">25</sup>, היינו, שמצד קו הימין וכן מצד קו השמאל יש ענין של יציאה לגמרי<sup data-n=\"1408\">26</sup>, ורק יעקב שהוא קו האמצעי היתה מטתו שלמה<sup data-n=\"1409\">27</sup>.\nג) <b>וזהו</b> גם מ\"ש<sup data-n=\"1410\">28</sup> כנשר יעיר קנו על גוזליו ירחף וגו', דנשר הוא בחי' תפארת, מדתו של יעקב, מדת הרחמים, שהיא בקו האמצעי, כידוע שד' הפנים שבמרכבה הנה פני ארי' אל הימין ופני שור אל השמאל<sup data-n=\"1411\">29</sup>, ופני אדם ופני נשר הם בקו האמצעי, דפני אדם הוא בבחי' דעת דמלכות, שהוא שרש לבחי' פני נשר שהוא ת\"ת דמלכות<sup data-n=\"1412\">30</sup>. וזהו כנשר יעיר קנו, שכל עלי' שבאין ערוך היא ע\"י פני נשר, קו האמצעי, וכנ\"ל שהעלי' דקו האמצעי היא בפנימיות הכתר. וזהו ג\"כ מה שבענין מ\"ת כתיב<sup data-n=\"1413\">31</sup> ואשא אתכם על כנפי נשרים ואביא אתכם אלי, והיינו לפי שהוצרכה להיות עלי' שבאין ערוך, שהרי בהיותם במצרים היו משוקעים במ\"ט שערי טומאה<sup data-n=\"1414\">32</sup>, ועד כדי כך, שהגאולה הוצרכה להיות כהרף עין<sup data-n=\"1415\">33</sup>, כיון שאילו היו נשארים במצרים עוד כהרף עין, היתה יכולה להיות ח\"וירידה גם למטה ממ\"ט שערי טומאה<sup data-n=\"1416\">34</sup>, ומירידה הלזו היתה העלי' באין ערוך, עד ואביא אתכם אלי, אלי ממש, שהוא העצמות, הנה עלי' כזו, שהיא באי\"ע ושלא בסדר והדרגה כלל, היא ע\"י כנפי נשרים דוקא, קו האמצעי. וזהו ג\"כ מ\"ש בלקו\"ת להאריז\"ל<sup data-n=\"1417\">35</sup> בביאור הכתוב שלשה המה נפלאו ממני גו' דרך הנשר בשמים גו', שהפלא הוא שהנשר שהוא עוף טמא נמצא במרכבה העליונה. ולכאורה אינו מובן<sup data-n=\"1418\">36</sup>, הרי גם הארי' הוא חי' טמאה, ומהו הפלא בענין הנשר דוקא. אך הענין הוא, דפני ארי' הוא בקו הימין, שמגיע רק בחיצוניות הכתר, ולכן אין זה פלא כ\"כ, ועיקר הפלא הוא על הנשר, כיון שמגיע בפנימיות הכתר, בחי' עתיק, וכנ\"ל שהעלי' שע\"י הנשר היא עלי' שבאין ערוך לגמרי.\nד) <b>וזהו</b> ג\"כ מה שאמרו רז\"ל<sup data-n=\"1419\">37</sup> אותן אלף שנה שעתיד הקב\"ה לחדש בהן עולמו, צדיקים מה הן עושין, הקב\"ה עושה להם כנפים כנשרים ושטין על פני המים, והיינו, שגם העליות דלעתיד יהיו ע\"י כנפי נשרים דוקא, לפי שבהם ועל ידם העלי' היא שלא בהדרגה.\n<b>ובהקדים</b> ביאור מארז\"ל הנ\"ל אודות אותן אלף שנה שעתיד הקב\"ה לחדש בהם עולמו, שרש\"י פירש שאז יהי' עולם זה חרב. ובמשנה סוף תמיד ליום שכולו שבת ומנוחה כו', כתב הרע\"ב, האי תנא ס\"ל כמ\"ד וחד חרוב<sup data-n=\"1420\">38</sup>. וצריך להבין, מהו הענין שמצד יום שכולו שבת נעשה חד חרוב, ואם מצד יום שכולו שבת צריך להיות חרוב, הי' צריך להיות מעין זה בכל שבת. אך הענין הוא, דהנה, בשבת כתיב<sup data-n=\"1421\">39</sup> ויכולו השמים והארץ וכל צבאם גו', ויכולו מלשון כליון<sup data-n=\"1422\">40</sup>, שבשבת הוא עליית העולמות כידוע. ומקשה רבינו בלקו\"ת ד\"ה שובה ישראל<sup data-n=\"1423\">41</sup>, דכיון שבשבת נעשה עליית החיות של העולמות, מניין יש להם חיות. ומתרץ, שהעלי' היא בבחי' החיצוניות, וקבלת חיותם היא מבחי' הפנימיות, והיינו שהעלי' היא בבחי' הדיבור, ואז מקבלים חיות מבחי' המחשבה. והנה, עד\"ז איתא ג\"כ לענין ר\"ה, דכתיב<sup data-n=\"1424\">42</sup> זה היום תחלת מעשיך זכרוןליום ראשון, והיינו שע\"י התקיעות והתפלות נעשה תחלת מעשיך, לפי שמקודם לזה החיות הוא בסילוק, שזהו מש\"נ<sup data-n=\"1425\">43</sup> מרשית השנה, מרשית חסר א', לפי שהחיות הוא בסילוק, ומקשה רבינו<sup data-n=\"1426\">44</sup>, דכיון שהחיות הוא בסילוק, מניין מקבלים העולמות חיותם. ומתרץ, שהסילוק הוא רק בבחי' הפנימיות, וקבלת החיות היא מבחי' החיצוניות, ועד\"מ אדם שעסוק באיזה ענין שכלי ומ\"מ עושה איזה מעשה מצד ההרגל או כמתעסק. והנה, הגם שיש הפרש בין ר\"ה לשבת, שבר\"ה העלי' היא בבחי' הפנימיות, ובשבת העלי' היא בבחי' החיצוניות, מ\"מ, בהכרח לומר שגם בשבת יש עלי' בבחי' הפנימיות. דהנה, מבואר בלקו\"ת ד\"ה למנצח על השמינית<sup data-n=\"1427\">45</sup> בענין השאלה ששאל מין א' מר\"ע, אם הקב\"ה מחבב<sup data-n=\"1428\">46</sup> את השבת, איך מוריד גשמים ומצמיח עשבים בשבת, והשיב לו משל מעירוב והוצאה שברשות א' אין צריך עירוב כו', והרי אצלו ית' הכל הוא רשות היחיד דיחידו של עולם<sup data-n=\"1429\">47</sup>. ומבואר בלקו\"ת שם, שהמשכת החיות בשבת מבחי' ומדריגה שאין בה חילוקי רשויות היא מבחי' חיצוניות א\"ק, ואילו העלי' והשביתה היא בבחי' פנימיות א\"ק, והיינו, לפי שבבחי' חיצוניות א\"ק הכל בהשוואה אחת, כחשיכה כאורה<sup data-n=\"1430\">48</sup>, ועל זה אין צריך כלי, משא\"כ להמשכת פנימיות א\"ק צריך להיות כלי, והו\"ע המילה שהוא הסרת הערלה, שהיא כלי להמשכת פנימיות א\"ק, ולכן בפנימיות א\"ק יש עלי' בשבת, אבל בחיצוניות א\"ק אין חילוק בין שבת לימי החול. ונמצא, שגם בשבת העלי' היא בבחי' הפנימיות. ואין זה סותר למשנת\"ל מד\"ה שובה ישראל שהעלי' דשבת היא בבחי' הדיבור ולא בבחי' המחשבה, לפי שגם בדיבור עצמו יש חיצוניות ופנימיות. דהנה, התהוות העולם הוא מבחי' הדיבור, ובדיבור ישנו חומר האותיות שהוא חיצוניות הדיבור, וישנה גם צורת האותיות, כמבואר באגה\"ק<sup data-n=\"1431\">49</sup> שצורת האותיות היא בחי' האותיות שבנפש שהם השרש של הדיבור, וראי' על זה, שהרי החרש יש לו כל ה' המוצאות, ומ\"מ אינו יכול לדבר, לפי שאין בו גילוי האותיות שבנפש שהם שרש הדיבור. וכן גם ענין ההרהור, שהיא דרגא היותר אחרונה שבמחשבה, הרי זה פנימיות הדיבור, שהרי ההרהור הוא הנותןסדר וחיות בהדיבור. והעלי' דשבת היא בבחי' פנימיות הדיבור, והיינו, שכללות ענין הדיבור הוא חיצוניות לגבי המחשבה, אבל בהדיבור עצמו העלי' הוא בפנימיות הדיבור, ואילו חיצוניות הדיבור אינו מסתלק גם בשבת, והיינו שחיצוניות הדיבור דע\"מ הם המהוים את הנבראים תמיד, הן בימות החול והן ביום השבת ובר\"ה. ומה שמקשה בד\"ה שובה הנ\"ל מניין נמשך חיות הנבראים בשבת, הכוונה היא על חיות האותיות, דמאחר שיש עלי' בפנימיות הדיבור, א\"כ מניין נמשך חיות האותיות. ועל זה מתרץ שחיות האותיות היא מבחי' המחשבה, אבל מה שנמשך מהמחשבה הוא מבחי' חיצוניות המחשבה, וכנ\"ל שרק בבחי' חיצוניות א\"ק אין חילוק רשויות כו'. ובזה יובן ג\"כ המבואר בשער היחוד והאמונה<sup data-n=\"1432\">50</sup> בענין לעולם הוי' דברך נצב בשמים<sup data-n=\"1433\">51</sup>, שדבר הוי' נצב תמיד בהנבראים, ואם יסתלק כרגע יהיו אין ואפס כמו קודם הבריאה, והרי ישנו ג\"כ ענין ההתחדשות (חידוש הישנות), כמ\"ש<sup data-n=\"1434\">52</sup> המחדש בטובו בכל יום תמיד מעשה בראשית, שאינו כמו הענין דלעולם גו' נצב, שהוא בלי שינוי כלל. אך הענין הוא, שבחיצוניות האותיות אין שינוי כלל, ותמיד הם נצבים בהנבראים להוותם מאין ליש, וענין המחדש הוא בענין חיות האותיות. ובזה יובן ג\"כ איך נמשך חיות העולמות בר\"ה שחל להיות בשבת<sup data-n=\"1435\">53</sup>, מאחר שהעלי' היא הן בבחי' הפנימיות והן בבחי' החיצוניות, כי, כל ענין העלי' הוא בענין החיות, אבל חיצוניות האותיות הם נצבים תמיד בלי שינויים, ומזה הוא חיות העולמות.\n<b>ועפ\"ז</b> יובן הטעם שביום שכולו שבת יהי' חד חרוב, דהנה, עכשיו העלי' דשבת היא בפנימיות א\"ק, ואין זה נוגע לבחי' חיצוניות א\"ק, אבל לעתיד לבוא, כאשר יקויים היעוד ונגלה כבוד הוי' גו'<sup data-n=\"1436\">54</sup>, אזי גם בחיצוניות יורגש הפנימיות, וכיון שגשמיות העולם אינה כלי לבחי' הפנימיות, לכן יהי' חד חרוב. וע\"ד ענין המן שלא ירד בשבת, אע\"פ שבשבת כתיב<sup data-n=\"1437\">55</sup> ויברך אלקים את יום השביעי, שברכו במן<sup data-n=\"1438\">56</sup>, והיינו<sup data-n=\"1439\">57</sup> לפי שהמן הוא בחי' שיורא דטלא דבדולחא<sup data-n=\"1440\">58</sup> שהוא למעלה מהעולמות, ולכן, אע\"פ שלמעלה היתה עיקר המשכתו בשבת דוקא, שהו\"ע העלי' בבחי'הפנימיות, הנה למטה לא ירד בשבת, מפני שכמו שהוא בבחי' הפנימיות אי אפשר לירד למטה בגשמיות, ורק אח\"כ בימות החול שיורד האור בבחי' השתלשלות, אזי נמשך וירד בעולם. ומזה מובן במכ\"ש בנוגע להגילוי דלעתיד, שהרי אם המן שהוא שיורא דטלא בלבד, אינו יכול להיות נמשך בעולם, הרי מכ\"ש לעתיד שאז יהי' גילוי בחי' הטל עצמו, שזהו טל שעתיד להחיות בו את המתים<sup data-n=\"1441\">59</sup>, היינו, שגם המת עצמו יהי' נעשה חי, שזהו\"ע של חיות באופן נעלה יותר מאשר החיות דעכשיו<sup data-n=\"1442\">60</sup>, הרי בודאי שבחי' זו אינה יכולה להיות נמשך בגשמיות העולם, ולכן יהי' חד חרוב.\n<b>וזהו</b> שאמרו רז\"ל אותן אלף שנה שעתיד הקב\"ה לחדש בהן עולמו, צדיקים (היינו כל ישראל, כמ\"ש<sup data-n=\"1443\">61</sup> ועמך כולם צדיקים) מה הן עושין, הקב\"ה עושה להם כנפים כנשרים ושטין על פני המים, דהנה, מים קאי על התורה, אין מים אלא תורה<sup data-n=\"1444\">62</sup>, שהו\"ע מים העליונים שעל הרקיע<sup data-n=\"1445\">63</sup>, והם יהיו שטים על פני המים, היינו, שיתעלו למעלה כ\"כ עד שיהיו שטים על פני המים, באופן של שיוט בלבד, כמו עד\"מ חכם גדול כשמעיין באיזה שכל קטן שאין צריך בו טורח ויגיעה כלל, אלא שט בו בנקל בלי שום טורח. ועלי' זו תהי' ע\"י כנפי נשרים דוקא, קו האמצעי, שעי\"ז היא העלי' שבאין ערוך, כנ\"ל.\nה) <b>אמנם</b> בענין העלי' שבקו האמצעי יש כמה מדריגות, שהרי יש בחי' פני נשר כפי שהוא במרכבה דבריאה, ויש כפי שהוא באצי', ת\"ת ודעת דאצילות, ולמעלה יותר כו'. וזהו כנשר יעיר קנו, כנשר בכ\"ף הדמיון, דכשם שישנה העלי' שע\"י הנשר, בחי' ת\"ת דאצילות, יש גם עלי' גדולה מזו, שזהו מ\"ש<sup data-n=\"1446\">64</sup> הוי' בדד ינחנו. דהנה, משנת\"ל שהעלי' דקו האמצעי היא בבחי' פנימיות הכתר, בחי' עתיק, הרי עם היות שבחי' עתיק הו\"ע העתקת העצמות, מ\"מ, אין זה כמו העצמות ממש, אלא כפי שנעתק כו'. וע\"ד המבואר במ\"א<sup data-n=\"1447\">65</sup> בענין פנימיות אבא פנימיות עתיק, שמ\"מ אין זה דומה לבחי' פנימיות עתיק כמו שהוא במקומו. וכמו\"כ יובן בענין עתיק שהוא העתקת העצמות, שזהו כפי שנעשה כבר בבחי' העתקה כו', ואין זה כמו העצמות ממש. ולמעלה מזה הו\"ע הוי' בדדינחנו, דהנה, בדד הוא בד ד', בד פירושו יחידי<sup data-n=\"1448\">66</sup>, והיינו כמו שהוא ית' יחיד ומיוחד כו'. והד' השני דבדד רומז לבחי' מלכות דאצילות. וענין בדד היינו עליית המלכות דאצילות במלכות דא\"ס, שעי\"ז נעשית גם העלי' דמלכות דא\"ס בבחי' פנימיות ועצמיות א\"ס, שזהו\"ע והאל הקדוש נקדש בצדקה<sup data-n=\"1449\">67</sup>, דלכאורה, מאחר שהוא בחי' קדוש, מהו ענין נקדש כו', אך הענין הוא, שע\"י הצדקה שזהו בחי' מלכות דאצילות, נקדש האל הקדוש, בחי' מלכות דא\"ס<sup data-n=\"1450\">68</sup>.\n<b>והענין</b> בזה, שהעלי' דנשר היא בכללות בקו התורה, משא\"כ ענין הוי' בדד ינחנו הו\"ע התשובה שלמעלה מהתורה, שזהו\"ע בדד, כמו בד בבד, שעל זה רומזים בגדי בד דכה\"ג ביוהכ\"פ שבהם דוקא הי' נכנס לקדה\"ק. וזהו אומרו כנשר בכ\"ף הדמיון, לפי שעלי' זו היא למעלה מבחי' העלי' דתורה שע\"י הנשר. וזהו גם מ\"ש&lt;28&gt; ישאהו על אברתו, דאברתו קאי על רמ\"ח פקודין שהם רמ\"ח אברין דמלכא<sup data-n=\"1451\">69</sup>, ופי' ישאהו על אברתו הוא למעלה מרמ\"ח פקודין, והיינו, שגם כאשר פגם ברמ\"ח פיקודין, שזהו מ\"ש לפנ\"ז<sup data-n=\"1452\">70</sup> ימצאהו בארץ מדבר, מדבר הוא ארץ אשר לא ישב אדם שם<sup data-n=\"1453\">71</sup>, שמורה על העדר קיום מ\"ע וגם הפגם בל\"ת, והו\"ע ארץ לא זרועה<sup data-n=\"1454\">72</sup>, שנזרע בו הענין דלא (ענינים שהם לא כדבעי), הנה מ\"מ ישאהו על אברתו, שהו\"ע העלי' לבחי' שלמעלה מאור התומ\"צ. וזהו גם כנשר וגו', שגם כאשר נשר ונפל כו' בבחי' הרפ\"ח ניצוצין כו', רפ\"ח מ\"ת<sup data-n=\"1455\">73</sup>, דמאן דנפיל מדרגי' איקרי מית<sup data-n=\"1456\">74</sup>, מ\"מ, ישאהו על אברתו. וזהו ג\"כ ענין תחיית המתים, ע\"י הטל שעתיד להחיות בו את המתים, טל אורות טליך<sup data-n=\"1457\">75</sup>, בחי' אור דתורה שלמעלה מהתורה עצמה<sup data-n=\"1458\">76</sup>, שמצד בחי' זו הנה גם הטמא והמת יהי' טהור וחי, שזהו אופן נעלה יותר בחיות, דלכן גם המת יהי' חי. והמשכת בחינה זו הוא ע\"י כנפי נשרים,קו האמצעי דוקא, דבכללות הו\"ע יגמה\"ר שעל ידם נעשה גם המת חי, וכמ\"ש<sup data-n=\"1459\">77</sup> מחי' מתים ברחמים רבים. וזהו ג\"כ מ\"ש&lt;70&gt; יצרנהו כאישון עינו, דהנה, אישון בת עין הוא השחור שבעין<sup data-n=\"1460\">78</sup> שנקרא נהורא אוכמא, והלובן שבעין הוא נהורא חיוורא, והרי עיקר הראי' הוא דוקא בהשחור שבעין, וכמאמר<sup data-n=\"1461\">79</sup> אין אדם רואה מתוך הלבן שבעין אלא מתוך השחור שבו. והוא ע\"ד יתרון<sup data-n=\"1462\">80</sup> האור מתוך החושך, דהיינו כאשר השחרות מזדכך ומתהפך לטבע הבהירות, אזי הוא למעלה מבחי' בהירות הלובן, ואז ישרה בו הראי'. וזהו גם מה שמסיים בכתוב ואין עמו א-ל נכר, שגם מי שמצד מצבו יש לו שייכות לענין אל נכר כו', מ\"מ הנה מצד יגמה\"ר נעשים לו זדונות כזכיות.\nו) <b>וזהו</b> כי כארץ תוציא צמחה וכגנה זרועי' תצמיח, שהו\"ע ג' הבחי' שבקיום התומ\"צ כנ\"ל, הנה כן אד' הוי' יצמיח גו', היינו, שגם מי שחטא כו' תהי' אצלו הצמיחה וגילוי האור מלמעלה ע\"י בחי' אד' הוי' שמאיר בר\"ה ויוהכ\"פ, דשם אד' הוא בר\"ה, ושם הוי' בניקוד אלקים הוא ביוהכ\"פ<sup data-n=\"1463\">81</sup>, והרי ענין שם הוי' בניקוד אלקים הוא דוגמת הענין דבדד, שהוא בחי' מלכות דא\"ס<sup data-n=\"1464\">82</sup>, וכשם שע\"י עליית מלכות דאצילות מתעלית גם מלכות דא\"ס בבחי' פנימיות ועצמיות א\"ס, כנ\"ל בפירוש והאל הקדוש נקדש בצדקה, כמו\"כ הוא גם בענין הוי' בניקוד אלקים, שכאשר שם אלקים עולה בשם הוי', אזי גם שם הוי' עולה למעלה יותר, ומצד בחינה זו הרי גם מי שאין אצלו הזריעה דתומ\"צ, הנה אד' הוי' יצמיח צדקה ותהלה, בדוגמת כארץ תוציא צמחה גו', ועוד למעלה יותר. והענין בזה, כידוע שי\"ג מדה\"ר וי\"ג מדות שהתורה נדרשת בהם שייכים זה לזה, וכמאמר המגיד<sup data-n=\"1465\">83</sup> ששם א-ל שהוא התחלת יגמה\"ר<sup data-n=\"1466\">84</sup>, א-ל רחום וחנון<sup data-n=\"1467\">85</sup>, מי א-ל כמוך<sup data-n=\"1468\">86</sup>, הוא כנגד מדת קל וחומר שהיא התחלת י\"ג המדות שהתורה נדרשת בהם. ולכן, הנה מצד יגמה\"ר נעשה המשכת אור התורה, שזהו\"ע כן אד' הוי' יצמיח צדקה ותהלה, ואדרבה, שאור התורה שנמשך ע\"י התשובה הוא למעלה יותר. והמשכה זו היא נגד כל הגוים,דקאי הן על בחי' הגוי שבעצמו כו' והן על הגוי שבזולת כו', שעי\"ז שיצמיח צדקה ותהלה נדחה גם החושך של הגוים. וכל זה הוא מצד גילוי בחי' בדד שנמשך ביוהכ\"פ, וגמר ההמשכה היא בשמע\"צ, שענינו הוא כמ\"ש<sup data-n=\"1469\">87</sup> יהיו לך לבדך ואין לזרים אתך. ומבחי' זו נמשך רב טוב לבית ישראל<sup data-n=\"1470\">88</sup>, וגם אלו שיש בהם זדונות, שנעשים כזכיות כו', ונמשך כתיבה וחתימה טובה לשנה טובה ומתוקה, בבני חיי ומזוני רויחא, בטוב הנראה והנגלה.\n**********<b>בס\"ד. שיחת ש\"פ נצבים-וילך, כ\"ג אלול, ה'תשי\"ט</b>.\nבלתי מוגה\n<b>א</b>. ידוע מה שסיפר כ\"ק מו\"ח אדמו\"ר<sup data-n=\"1471\">1</sup> בשם רבינו הזקן אודות התורה ששמע במעזריטש בשם הבעש\"ט, בביאור הטעם שאין מברכים חודש תשרי בשבת שלפני ראש השנה, כמו בשאר החדשים:\nהחודש השביעי, שהוא החודש הראשון לחדשי השנה – הקב\"ה בעצמו מברכו בשבת מברכים שהוא השבת האחרון דחודש אלול, ובכח זה ישראל מברכים את החדשים י\"א פעמים בשנה.\nוברכתו של הקב\"ה בשבת שלפני חודש תשרי היא – \"אתם נצבים היום\"<sup data-n=\"1472\">2</sup>, שפירושו קיימים ועומדים, והיינו שזוכים בדין.\nוישנו גם הפירוש שאמר כ\"ק מו\"ח אדמו\"ר בשנת ת\"ש<sup data-n=\"1473\">3</sup>, ש\"אתם נצבים\" רומז על הזמן של ביאת המשיח,\n– שהרי הפירוש הפשוט הוא שענין זה נאמר קודם הכניסה לארץ ישראל בביאה ראשונה שהי' אחרי' גלות, ובזה נכלל גם הפירוש הפנימי דקאי על הכניסה לארץ באופן של גאולה שלימה שאין אחרי' גלות, ע\"י משיח צדקנו –\nכיון שאז יהי' עולם חדש, \"השמים החדשים והארץ החדשה\"<sup data-n=\"1474\">4</sup>, שהרי העולם יחרב, כמ\"ש<sup data-n=\"1475\">5</sup> \"כי שמים כעשן נמלחו והארץ וגו'\", וכיון שבנ\"י יהיו אז מודאגים (\"פאַרצווייפלט\") מה יהי' עמהם, אומר להם הקב\"ה \"אתם נצבים\".\nוכל ענינים אלו – החל מהכניסה לארץ בפעם הראשונה ועד להכניסה לארץ ע\"י משיח צדקנו – נכללים בפסוק \"אתם נצבים היום\", שזוהי ברכתו של הקב\"ה בשבת מברכים חודש השביעי, המשובע בכל<sup data-n=\"1476\">6</sup>, שבכחה מברכים בנ\"י את כל שאר חדשי השנה.\n<b>ב</b>. וע\"פ הידוע שכל הענינים מרומזים גם בגליא שבתורה, הנה גםפתגם הבעש\"ט שהכח של בנ\"י לברך את החדשים הוא מברכת החודש של הקב\"ה – מקורו במדרש<sup data-n=\"1477\">7</sup>:\nעל הפסוק<sup data-n=\"1478\">8</sup> \"החודש הזה לכם וגו'\", איתא במדרש<sup data-n=\"1479\">9</sup>: \"עד שלא יצאו ממצרים הי' הקב\"ה יושב ומחשב חשבונות ומעבר עבורים מקדש שנים ומחדש חדשים, כיון שיצאו ממצרים מסרן להם, שנאמר החודש הזה לכם ראש חדשים, מכאן ואילך מסורים לכם\".\n[ולהעיר, שבענין זה יש מדרשות חלוקות:\nבמדרש הנ\"ל משמע שקודם יצי\"מ (שאז \"מסרן להם\") לא הי' הדבר ידוע אלא להקב\"ה בלבד.\nאבל במק\"א<sup data-n=\"1480\">10</sup> מצינו שהקב\"ה \"מסרן לאדה\"ר .. (ו)אדם מסר לחנוך וכו'\", וכך נמסר סוד העיבור מדור לדור, אלא שאח\"כ \"נתמנעו העיבורין מישראל .. בשעבוד מצרים\", שאז נשכח הדבר לגמרי, וחזר להיות אצל הקב\"ה לבדו, ובתחילת זמן הגאולה אמר הקב\"ה למשה ואהרן \"החודש הזה לכם\", \"עד עכשיו אצלי הי' סוד העיבור, מכאן ואילך שלכם הוא\"].\nומשמעות דיוק הלשון \"<b>מסרן</b> להם\", \"<b>מסורים</b> לכם\" (ולא רק שמודיע להם מה שלא ידעו עד עתה) הוא – שהקב\"ה מוסר להם את <b>הכח</b> שלו לקדש החדשים.\nוזהו המקור בנגלה על פתגם הבעש\"ט שהכח של בנ\"י לברך את חדשי השנה הוא – מברכתו של הקב\"ה.\n<b>ג</b>. וביאור הטעם שיש צורך על זה בנתינת-כח מיוחדת:\nישראל נמשלו ללבנה<sup data-n=\"1481\">11</sup>, כי, הלבנה יש בה שינויים, לפעמים היא בגדלות, ולפעמים היא בקטנות ועד להעלם לגמרי, וכמו\"כ משתנה מצבם של בנ\"י מזמן לזמן, שלפעמים הם במצב של גלות, ולפעמים הם במצב של גאולה.\nובכדי שיוכל להיות מולד הלבנה וקידוש החודש, היינו, שממצב של תכלית ההעלם יתחיל ענין של גילוי – הרי מי שנמצא בעצמו במצב של גלות וחושך, אין בכחו לצאת ממצב זה למצב של תחילת הגילוי, ולכן יש צורך בנתינת-כח מלמעלה.<b>ד</b>. עפ\"ז יובן גם מאמר המדרש הנ\"ל (ס\"ב) ש\"נתמנעו העיבורין מישראל .. בשעבוד מצרים\":\nגם להדעה שסוד העיבור הי' ידוע עוד קודם שנאמרה מצות קידוש החודש, \"החודש הזה לכם\" – הרי הכל מודים שבשעת גלות מצרים נשתכח הדבר.\nוטעם הדבר – כי, ענין קידוש החודש הוא התחלת הגילוי והיציאה מן החושך, ואילו גלות מצרים שהיא תכלית החושך והגלות, היא ההיפך לגמרי מענין קידוש החודש.\nורק בהתחלת זמן הגאולה והיציאה ממצרים – שענינה הוא הכנה למתן-תורה, כידוע<sup data-n=\"1482\">12</sup>, והרי תורה ענינה גאולה, כמארז\"ל<sup data-n=\"1483\">13</sup> \"אין לך בן חורין אלא מי שעוסק בתלמוד תורה\" – אזי התחיל הענין דקידוש החודש.\nאלא, שבזה גופא יש ב' דעות: דעה הא', שלפנ\"ז לא הי' מעולם ענין קידוש החודש, כיון שהכח לצאת מחושך לאור הוא רק ע\"י התורה; ודעה הב', שגם קודם מ\"ת הי' יכול להיות ענין זה, אבל, לא בשעת גלות מצרים, שאז הכל מודים ש\"נתמנעו העיבורין מישראל\".\n<b>ה</b>. עפ\"ז יש לבאר הטעם שגם לאחרי שניתנה מצות קידוש החודש שמאז היו מקדשים את החודש ע\"פ הראי', הנה כשהתחילה הגלות נפסק קידוש החודש ע\"פ הראי', אלא שאעפ\"כ אין זה בדומה לגלות מצרים, שאז נשתכח ענין קידוש החודש לגמרי, ואילו בשאר הגלויות נשאר עכ\"פ ענין החשבון:\nובהקדם המבואר במק\"א<sup data-n=\"1484\">14</sup> שכל שאר הגלויות אינן דומות לגלות מצרים, כיון שגלות מצרים היתה קודם מתן-תורה, ואילו שאר הגלויות הם לאחרי מ\"ת, וכיון שישנה כבר התורה שענינה גאולה (כנ\"ל), שוב לא יכול להיות חושך וגלות כמו שהי' בגלות מצרים.\nולכן:\nקידוש החודש ע\"פ <b>הראי'</b> – לא יכול להיות גם בשאר הגלויות, כי, מצד חשכת הגלות אי אפשר לראות את הגילוי דמולד הלבנה כו', והיינו, שבזמן הגלות <b>אי אפשר לראות בגלוי</b> שלא זו בלבד שההעלם אינוהעלם, אלא אדרבה, שדוקא תכלית הקטנות והעלם הלבנה פועל את הגילוי החדש;\nאבל קידוש החודש ע\"פ החשבון, שענינו <b>הבנה והשגה</b>, יכול להיות גם בזמן הגלות (בשאר הגלויות שלאחרי מ\"ת), היינו, שמצד התורה הנה גם בזמן הגלות יכולים להבין עכ\"פ שההעלם אינו העלם לאמיתתו, כידוע בענין \"גם חושך לא יחשיך גו'\"<sup data-n=\"1485\">15</sup>, ואדרבה, ההעלם מביא לתכלית הגילוי.\nוע\"י היגיעה והתבוננות שכלית (ענין החשבון) עכ\"פ – באים להזמן שבו יחזור להיות קידוש החודש ע\"פ הראי', והיינו, שיהי' נראה בגלוי גם לעיני בשר שההעלם והגילוי הם בשוה, \"ולילה כיום יאיר\"<sup data-n=\"1485\">15</sup>.\n***\n<b>ו</b>. דובר אודות הענין ד\"אתם נצבים גו' לעברך בברית גו'\", שיהיו כל ישראל ערבים זל\"ז, ע\"י התכללותם להיות לאחדים כאחד, שזהו מצד אור עליון<sup data-n=\"1486\">16</sup>, שהאיר בכניסתם לארץ בשביל להשלים את הכוונה דדירה בתחתונים, ולכן נפעל שלימות ענין הערבות בכניסתם לארץ דוקא<sup data-n=\"1487\">17</sup> – הוגה ע\"י כ\"ק אדמו\"ר שליט\"א (באידית)<sup data-n=\"1488\">18</sup>, ונדפס בלקו\"ש ח\"ד ע' 1140 ואילך.\n***\n<b>ז</b>. צוה לנגן ואמר מאמר ד\"ה כי כארץ תוציא צמחה וגו'.\n***\n<b>ח</b>. חודש אלול בכלל הוא זמן התשובה.\nבתשובה בכלל ידוע שישנם ב' מדריגות: תשובה תתאה ותשובה עילאה<sup data-n=\"1489\">19</sup>.\nוהנה, ע\"פ הסדר הרגיל שצריך לילך מלמטה למעלה – יש להתחיל עם תשובה תתאה, ומזה באים אח\"כ לתשובה עילאה. אמנם,ידוע פתגם אדמו\"ר מהר\"ש שצריכים לילך \"לכתחילה אַריבער\"<sup data-n=\"1490\">20</sup>, ועפ\"ז יש להתחיל מיד עם תשובה עילאה.\nהחילוק בין תשובה תתאה לתשובה עילאה <b>בפועל</b> – הוא:\nתשובה תתאה היא מתוך מרירות. והיינו, שמתבונן במעמדו ומצבו שהוא מרוחק מאלקות, ו\"רע ומר עזבך את הוי'\"<sup data-n=\"1491\">21</sup>, ומצד זה הרי הוא מתמרמר על ריחוקו מאלקות ושב בתשובה.\nואילו תשובה עילאה היא בשמחה<sup data-n=\"1492\">22</sup>. והיינו, שמתבונן בגדולת הוי', ובגודל מעלת נשמתו שהיא \"חלק אלקה ממעל ממש\"<sup data-n=\"1493\">23</sup>, ותמיד, גם בשעת החטא, היא באמנה אתו ית'<sup data-n=\"1494\">24</sup>, וכאשר מתבונן במעמדו ומצבו, באיזה דרגא הוא נמצא, ולאיזו דרגא הי' יכול להגיע, אזי מתעורר ברחמנות על עצמו, היתכן שהוא מונח בעניניו כו'. והמשל לזה, ממי שיש ברשותו אלף אלפי דינרי זהב, ואינו משתמש בהם, אלא מחזר על הפתחים לקבץ פרוטות של נחושת – הרי מובן עד כמה גדולה הרחמנות עליו. והתבוננות זו פועלת עליו להתמסר לרוחניות כו'.\nוהדרישה היא שסדר העבודה יהי' מתוך תנועה של תשובה עילאה – שההתבוננות תהי' (לא במעמדו ומצבו, אלא) במעלת נשמתו כו', שעי\"ז יתעורר להתמסר לאלקות<sup data-n=\"1495\">25</sup>.\n**********",[["1383","1","ישעי' סא, יא. – הפטרת ש\"פ נצבים וילך."],["1384","2","פרשתנו (נצבים) נ, סע\"ג ואילך."],["1385","3","הושע י, יב."],["1386","4","מלאכי ג, יב."],["1387","5","נסמן ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211111\" data-slug=\"likkutei-sichot\" data-id=\"1300211111\">לקו\"ש חכ\"א ע' 111</a> הערה 21."],["1388","6","ישעי' כט, יג."],["1389","7","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא פי\"ח</a>. פכ\"ה. ספמ\"ג."],["1390","8","ראה ראשית חכמה שער התשובה פ\"ד (קטו, ב). ב\"ח לטור או\"ח סתקפ\"א. אוה\"ת שה\"ש (כרך ב) ע' תקמו ואילך. ועוד."],["1391","9","פרש\"י תשא לג, יא. עקב ט, יח."],["1392","10","יומא פו, ב."],["1393","11","תשא לד, ו."],["1394","12","ר\"ה יז, ב."],["1395","13","בכל הבא לקמן – ראה ד\"ה כנשר תרע\"ח (סה\"מ תרע\"ח ע' כד ואילך)."],["1396","14","<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670142\" data-slug=\"torat-chaim\" data-id=\"2300670142\">תו\"ח נח סה, ב</a>. ובכ\"מ."],["1397","15","תהלים עג, כח. וראה שיחת אחש\"פ שנה זו סכ\"ז (תו\"מ חכ\"ה 240 ואילך). אג\"ק חי\"ח ע' שעא."],["1398","16","סט\"ו."],["1399","17","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380686\" data-slug=\"likkutei-torah\" data-id=\"4001380686\">ראה זח\"ג רכ, ב</a>. רסב, א. ח\"ג קמג, ב. וראה לקו\"ת מסעי צ, ג."],["1400","18","יבמות נג, ב."],["1401","19","מלאכי ג, כב."],["1402","20","ראה תקו\"ז תי\"ג (כט, א)."],["1403","21","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא פ\"ה (ט, ב</a>). קונטרס עץ החיים פי\"א (ע' 38)."],["1404","22","ברכות כב, א."],["1405","23","חגיגה בסופה."],["1406","24","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז</a>."],["1407","25","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381168\" data-slug=\"likkutei-torah\" data-id=\"4001381168\">ראה פסחים נו, א</a>. ויק\"ר פל\"ו, ה. וראה לקו\"ת ואתחנן ה, א. שה\"ש ט, ד."],["1408","26","בזכרון אחדים, שאצל יצחק הענין דיצא ממנו הוא עוד יותר מאשר באברהם (ראה גם סה\"מ תרכ\"ו ע' עג)."],["1409","27","ויק\"ר שם. רש\"י ויחי מז, לא."],["1410","28","האזינו לב, יא."],["1411","29","יחזקאל א, י."],["1412","30","שער מאמרי רז\"ל להאריז\"ל – מאמר פסיעותיו של אברהם אבינו."],["1413","31","יתרו יט, ד."],["1414","32","ראה זהר חדש ר\"פ יתרו. ועוד."],["1415","33","פרש\"י בא יב, מא."],["1416","34","ראה סידור האריז\"ל סדר הגש\"פ פיסקא ויוציאנו."],["1417","35","עה\"פ משלי ל, יח-יט."],["1418","36","ראה גם אוה\"ת האזינו ע' א'תרפט. ד\"ה כנשר תער\"ב (המשך תער\"ב ח\"ב ע' עתר). ד\"ה הנ\"ל תשכ\"ט (סה\"מ תשכ\"ט ע' כב). תשמ\"ב (תו\"מ סה\"מ תשרי ע' קכג. קנד)."],["1419","37","סנהדרין צב, ריש ע\"ב."],["1420","38","ר\"ה לא, א. סנהדרין צז, א."],["1421","39","בראשית ב, א."],["1422","40","אוה\"ת בראשית מב, ב ואילך. (כרך ג) תקח, א ואילך."],["1423","41","דרושי ש\"ש סו, ג."],["1424","42","בתפלת מוסף דר\"ה (ר\"ה כז, א)."],["1425","43","עקב יא, יב."],["1426","44","מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתפח ואילך. הנחות הר\"פ ע' קפו. וראה גם ד\"ה כבוד מלכותך תשי\"ב (תו\"מ ח\"ד ע' 6 ואילך). <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091220\" data-slug=\"likkutei-sichot\" data-id=\"1300091220\">לקו\"ש ח\"ט ע' 220</a>."],["1427","45","תזריע כא, ג."],["1428","46","כ\"ה בתרע\"ח. אבל במדרש ולקו\"ת שם: מכבד."],["1429","47","ב\"ר פי\"א, ה."],["1430","48","תהלים קלט, יב."],["1431","49","סי' ה."],["1432","50","פ\"א."],["1433","51","תהלים קיט, פט."],["1434","52","בברכת ק\"ש."],["1435","53","ראה לקו\"ש ח\"ט שם."],["1436","54","ישעי' מ, ה."],["1437","55","בראשית ב, ג."],["1438","56","מכילתא יתרו כ, יא. וראה דרושים שבהערה הבאה."],["1439","57","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316520294\" data-slug=\"or-hatorah-hb\" data-id=\"8316520294\">אוה\"ת בשלח ע' תרלח</a>-ט. המשך תער\"ב ח\"ב ע' א'סא. א'פו. ועוד. וראה מאמרי אדה\"ז על פרשיות התורה ס\"ע רצה ואילך."],["1440","58","ראה זח\"ג קכח, ב."],["1441","59","ראה מקומות שצויינו בהערה 57."],["1442","60","ראה לקמן פ\"ה."],["1443","61","ישעי' ס, כא. סנהדרין ר\"פ חלק."],["1444","62","ב\"ק יז, א."],["1445","63","ראה פרש\"י בראשית א, ו."],["1446","64","האזינו שם, יב."],["1447","65","ראה ד\"ה ויצא וד\"ה וישלח תרס\"ו."],["1448","66","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380197\" data-slug=\"likkutei-torah\" data-id=\"4001380197\">ראה יומא עא, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380828\" data-slug=\"likkutei-torah\" data-id=\"4001380828\">זבחים יח, ב</a>. ראה לקו\"ת אחרי כח, סע\"ב ואילך. עטרת ראש כח, א ואילך. מאמרי אדהאמ\"צ דברים ח\"ד ע' א'רלב ואילך. ועוד."],["1449","67","תפלת העמידה דימים הנוראים."],["1450","68","ראה סידור (עם דא\"ח) רנ, ד."],["1451","69","ראה זח\"א קע, ב."],["1452","70","האזינו שם, יו\"ד."],["1453","71","ירמי' ב, ו."],["1454","72","ירמי' ב, ב."],["1455","73","ראה עץ חיים שער יח (שער רפ\"ח ניצוצין) פ\"א. ל\"ת, שער הפסוקים וסה\"ל להאריז\"ל עה\"פ בראשית ב, א. ועוד."],["1456","74","כ\"ה בלקו\"ת חוקת נו, סע\"ד ואילך. וראה זהר ח\"ג קלה, ב. עץ חיים שער ט (שער שבירת הכלים) פ\"ב. מבוא שערים שער ב ח\"ב פ\"ג."],["1457","75","ישעי' כו, יט. וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל\"ו</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111200\" data-slug=\"likkutei-sichot\" data-id=\"1300111200\">לקו\"ש חי\"א ע' 193</a> בהערה (ד\"ה טל תורה)."],["1458","76","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381017\" data-slug=\"likkutei-torah\" data-id=\"4001381017\">לקו\"ת האזינו עג, ג</a>. לקו\"ש שבהערה הקודמת. וראה המשך וככה תרל\"ז פס\"ח."],["1459","77","בתפלת העמידה."],["1460","78","פרש\"י עה\"פ."],["1461","79","ראה ויק\"ר פל\"א, ח."],["1462","80","ע\"פ קהלת ב, יג."],["1463","81","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380925\" data-slug=\"likkutei-torah\" data-id=\"4001380925\">לקו\"ת נצבים נא, ג</a>."],["1464","82","שם נג, ב."],["1465","83","אור תורה להה\"מ מו, ב. קז, ב. הובא באוה\"ת בהעלותך ע' תב. פ' ראה ע' תשפה. ועוד."],["1466","84","זח\"ג קלא, ב. עץ חיים שער יג (שער אריך אנפין) פי\"א. ועוד."],["1467","85","תשא לד, ו."],["1468","86","מיכה ז, יח."],["1469","87","משלי ה, יז. וראה רד\"ה ביום השמע\"צ עת\"ר תש\"י. ובכ\"מ."],["1470","88","ישעי' סג, ז. – הפטרת ש\"פ נצבים וילך."],["1471","1","ראה כתר שם טוב (הוצאת תשנ\"ט) בהוספות סמ\"א. וש\"נ (נעתק ב\"היום יום\" כה אלול). וראה גם שיחת יום א' פ' נצבים ה'ש\"ת ס\"ב (סה\"ש קיץ ה'ש\"ת ע' 175)."],["1472","2","ריש פרשתנו (נצבים)."],["1473","3","סה\"ש שם ע' 176."],["1474","4","ישעי' סו, כב."],["1475","5","שם נא, ו."],["1476","6","ויק\"ר פכ\"ט, ח."],["1477","7","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091187\" data-slug=\"likkutei-sichot\" data-id=\"1300091187\">לקו\"ש ח\"ט ע' 187</a>."],["1478","8","בא יב, ב."],["1479","9","פסיקתא דר\"כ פ\"ה. וראה גם תורה שלמה עה\"פ (אות לח)."],["1480","10","פרדר\"א פ\"ח."],["1481","11","ראה סוכה כט, א ובחדא\"ג מהרש\"א שם. ב\"ר פ\"ו, ג. אוה\"ת בראשית ד, סע\"ב ואילך."],["1482","12","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370462\" data-slug=\"torah-or\" data-id=\"3901370462\">תו\"א ויחי בהוספות קד, סע\"ד</a>. ובכ\"מ."],["1483","13","אבות פ\"ו מ\"ב."],["1484","14","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011096\" data-slug=\"likkutei-sichot\" data-id=\"1300011096\">לקו\"ש ח\"א ע' 96</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071294\" data-slug=\"likkutei-sichot\" data-id=\"1300071294\">תו\"מ ח\"ז ע' 282</a>. ועוד."],["1485","15","תהלים קלט, יב."],["1486","16","והו\"ע גילוי עצם הנשמה ששם הכל שוים, שכן, מצד כחות הגלויים יש חילוקים בין עליון לתחתון, ורק מצד ענינים עצמיים הכל שוים, ואדרבה, גילוי כחות העצמיים יכול לפעמים להאיר ברגל יותר מאשר בראש."],["1487","17","ואעפ\"כ הי' הענין \"אתם נצבים גו' לעברך בברית גו'\" במדבר דוקא, ע\"י משה – כי, הנתינת כח לענין התכללות דבנ\"י היא מצד ענין הביטול, וכח זה ניתן ע\"י משה, להיותו \"עניו מאד מכל האדם אשר על פני האדמה\" (בהעלותך יב, ג)."],["1488","18","בשילוב שיחת ש\"פ נצבים תשח\"י."],["1489","19","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310075\" data-slug=\"tanya\" data-id=\"3401310075\">תניא אגה\"ת פ\"ד</a>. ובכ\"מ."],["1490","20","ראה אג\"ק אדמו\"ר מוהריי\"צ ח\"א ע' תריז. ועוד."],["1491","21","ירמי' ב, יט."],["1492","22","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310082\" data-slug=\"tanya\" data-id=\"3401310082\">תניא אגה\"ת פי\"א</a>. ובכ\"מ."],["1493","23","<a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>."],["1494","24","שם ספכ\"ד."],["1495","25","חסר קצת (<b>המו\"ל</b>)."]]],[1400330015,"(תרגום חפשי)\nב\"ה, כ\"ה אלול, ה'תשי\"ט, שנת השבע\nברוקלין, נ.י.\nאל בני ובנות ישראל\nאשר בכל מקום ומקום\nה' עליהם יחיו\nשלום רב וברכה!\nימים אלה, סופה של השנה החולפת ובעמדנו בהתחלת השנה החדשה, הבאה עלינו ועל כל ישראל לטובה ולברכה, הם זמן לחשבון הנפש על השנה שחלפה, ובהתאם להסך-הכל של החשבון, יש לקבל את ההחלטות הנכונות לשנה החדשה.\nהחשבון יכול להיות אמיתי, רק אם גם ההערכה של הכוחות והאפשרויות היא אמיתית. ככל שגדולות יותר האפשרויות שישנן ולא נוצלו, כך גדול יותר הצער, העבירה של אי-ניצולן, וכך צריכה להיות בתוקף יותר ההחלטיות שמכאן ולהבא ינוצלו האפשרויות במלוא המדה.\nהזמן שלפני ראש השנה, ושל ראש השנה עצמו, אינו רק הזדמנות הדורשת חשבון הנפש בכללות, אלא היא גם מזכירה ודורשת הערכה פנימית עמוקה של הכוחות הנשגבים שיש לאדם – בתור אדם, בחיר הנבראים, ובתור יהודי שהבורא יתברך נתן לו תורת-חיים אלקית, שהרי ראש השנה הוא היום שבו נברא האדם.\n***\nכאשר נברא האדם, הורה לו הבורא מיד מה הם כוחותיו ומהו תפקידו בעולם:\n\"מלאו את הארץ וכבשוה ורדו בדגת הים ובעוף השמים ובכל חי' הרומשת על הארץ\".\nלאדם ניתנו כחות לכבוש את כל העולם ולשלוט בו, ביבשה, בים ובאויר, והוא נצטווה לבצע את הדבר, זהו התפקיד שלו.\nמה היא הדרך לשליטה בעולם, ומהי מטרתה ותוכנה? – מספרים חז\"ל ומלמדים לנו:\nכאשר ברא הקב\"ה את אדם הראשון – הנה הנשמה שלו, צלם אלקים, חדרה והאירה בו, וענין זה ועל ידו – שלט על כל הבריאה. כל הנבראים התכנסו כדי להכתיר את האדם בתור בוראם. אך אדם הראשון הוכיח להם את טעותם ואמר להם: \"בואו נשתחוה – לפני ה' עושנו\".\n***\nהשליטה על העולם שניתנה לאדם כתפקיד ושליחות, ענינה לרומם את הסביבה, העולם כולו, כולל החיות והבהמות, לשימושה של האנושות האמיתית, אנושות החדורה ומוארת בצלם אלקים, בנשמה, חלק אלוקה ממעל ממש – דבר המביא את כל הבריאה להכרה ש\"ה' עושנו\".\nמובן מאליו, שלפני שהאדם מתעסק בשליטה על העולם, מוכרח הוא תחלה לשלוט על עצמו, על הארציות והחייתיות שבטבעו. וענין זה נעשה ע\"י קיום הוראות התורה, תורת-חיים – מורה דרך בחיי היום-יום, כך שהגשמיות והחומריות נעשים חדורים ומוארים באור של – ה' אלקינו ה' אחד.\nהקב\"ה ברא אדם אחד, ולאדם אחד ויחיד זה מסר את התפקיד האמור והמשימה האמורה. כאן טמונה המשמעות העמוקה אך ברורה, שאדם אחד – כל אדם – מסוגל \"לשלוט על העולם\".\nאם אדם לא ממלא את תפקידו, הוא לא מנצל את כחותיו האלקיים הבלתי מוגבלים – אין זה רק הפסד אדיר וכשלון אישי, אלא הדבר נוגע לגורל העולם כולו.\n***\nבימי חשבון הנפש, כאשר מתבוננים, שכל אחד מאתנו – ע\"י מילוי הוראות <b>בורא העולם</b> בתורתו – יש לו אפשרות לכבוש עולמות, צריך כל אחד להעמיד לעצמו את השאלה, עד כמה פעל בשנה החולפת בכיוון זה, שזוהי השליחות האלקית ומטרת חייו, ועד כמה עדיין נשאר חייב, ולקבל את ההחלטות המתאימות לשנה החדשה.\nוה' הרואה ללבב, בראותו את התוקף של החלטות טובות אלה, יתן את ברכתו שיקיימו אותן במלוא המדה – בשמחה ובטוב לבב, בהרחבה בגשמיות וברוחניות.\nבברכת כתיבה וחתימה טובה לשנה טובה ומתוקה\n<b>מנחם שניאורסאהן</b><b>בס\"ד. שיחת ליל כ\"ט אלול, ה'תשי\"ט</b>.\nבלתי מוגה\n<b>א</b>. מהתחלת השנה מדברים אודות \"ופרצת\",\nואעפ\"כ – אינני יודע מהי הסיבה לכך, ולמאי נפק\"מ, אבל – בנוגע לפועל, הנה במשך כל הזמן לא נראית עדיין שום הזזה!\nמה עוד יכול הנני לעשות בזה?! – דברתי, בקשתי וכתבתי, פעם ופעמיים ועד עשרה פעמים, ובמשך השנים אולי גם עד מאה פעמים, ולפועל, לא נעשה מאומה, לא בענינים הפרטיים, ולא בענינים הכלליים.\nבענינים הפרטיים – היו מונחים ב\"קטנות\", דברים קטנים,\n– וכמשל כ\"ק מו\"ח אדמו\"ר<sup data-n=\"1496\">1</sup> אודות שנים שמבקשים \"פנינים\" (\"פּערל\"), האחד רוצה (תבשיל הנקרא) \"פּערל\" (גריסים) בתוך המרק... והשני רוצה מחרוזת פנינים שעונדים על הצוואר! –\nובפרט בענינים הכלליים שבהם לא הי' כלל \"ופרצת\", כי אם באופן של צמצום; יותר צמצום או פחות צמצום.\nובעמדנו ביום האחרון של שנת תשי\"ט – הנני להציע ההצעה דלקמן.\n<b>ב</b>. ובהקדמה:\nבאמת<sup data-n=\"1497\">2</sup> מצינו בפסוק<sup data-n=\"1498\">3</sup> שיום הכיפורים נקרא בשם ראש השנה. אמנם, בפסוק אפשר לפרש שמדובר אודות שנת היובל<sup data-n=\"1499\">4</sup>. אבל ע\"פ ביאור הצמח צדק<sup data-n=\"1500\">5</sup> הרי כן הוא בכל שנה<sup data-n=\"1501\">6</sup>.\nגם ע\"פ נגלה שייך יוהכ\"פ לר\"ה – כפי שמצינו בענין שילוח עבדים, ש\"מר\"ה עד יוה\"כ לא היו עבדים נפטרין לבתיהן ולא משתעבדיןלאדוניהם, אלא אוכלין ושותין .. כיון שהגיע יוה\"כ תקעו ב\"ד בשופר נפטרו עבדים לבתיהן\"<sup data-n=\"1502\">7</sup>.\nויש בזה ב' הסברות ע\"פ נגלה:\nא) ענין היובל נעשה ביוהכ\"פ ע\"י תקיעת שופר, והיינו, שביוהכ\"פ נתברר שבר\"ה הי' השחרור<sup data-n=\"1503\">8</sup>.\n– ע\"ד החילוק בין צדיקים גמורים ובינונים, ש\"בינונים תלויין ועומדין מר\"ה ועד יוה\"כ\"<sup data-n=\"1504\">9</sup>, וביוהכ\"פ זוכים בדין –\nב) הר\"ן בר\"ה<sup data-n=\"1505\">10</sup> מבאר ענין זה, שהשחרור הוא ע\"י תקיעת שופר דיוהכ\"פ שהוא ר\"ה לענין השחרור, ומה שמר\"ה אינם משתעבדים ואוכלים ושותים, הרי זה הוספה משנה שעברה והכנה להשחרור.\nהנפק\"מ בין שני ההסברים היא: לפי ההסבר הראשון, נמצא, שמר\"ה מתחילה השנה החדשה, אלא שזה תלוי בהבירור דיוהכ\"פ. ולפי ההסבר השני, נמצא, שעד יוהכ\"פ שייך לשנה שעברה.\nוענין זה הוא לא רק בשנת היובל, אלא כן הוא גם בכל שנה – שבפנימיות הנה יוהכ\"פ הוא ראש השנה, וכפי שמצינו שענין סליחת העונות דשנה שעברה נעשה ביוהכ\"פ.\n<b>ג</b>. בהתאם לכך הנני להציע, אשר, מהיום ועד יוהכ\"פ (ועד בכלל), יום המיוחד בשנה, שהוא למעלה ממדידה והגבלה – יעסקו בתורה ותפלה באופן של \"ופרצת\",\n– שהרי יש להתחיל בענין הפנימיות, שזהו הענין ד\"ופרצת\" ששייך לפנימיות, כי, חיצוניות היא היפך ענין \"ופרצת\", כיון שזהו ענין של הגבלה, והו\"ע שבעת ימי הבנין, שבעת המדות, כמ\"ש<sup data-n=\"1506\">11</sup> \"כי אמרתי עולם חסד יבנה\"; וע\"י ההתחלה בענין הפנימיות, תחדור הפנימיות ותבקע (\"דורכברעכן\") את החיצוניות, ועד ש\"פרזות תשב ירושלים\"<sup data-n=\"1507\">12</sup> –\nשבמשך כל כ\"ד שעות המעת-לעת יעסקו בתורה, תפלה ואמירת תהלים, עי\"ז שיסדרו (עד כמה ששייך ענין של \"סדר\" ב\"ופרצת\") משמרות, באופן שלא יזיק לבריאות הגוף, של שנים-שלשה בחוריםלכל-הפחות, שיעסקו בתורה, תפלה ואמירת תהלים, במשך כל שעות היום והלילה.\n<b>ד</b>. ועי\"ז יתן השי\"ת, אשר, כל ההמשכות וההשפעות שנמשכו בשנת תשי\"ט – שהיתה שנת השבע, שנה ועיבורה, שנה תמימה ושנה מלאה – ולא ניצלו אותם (ואדרבה, הי' ענין של הגבלה), הנה בכח התורה יכולים בנ\"י למלאות זאת, שיומשכו כל ההמשכות וההשפעות,\nוימשיכו הענין ד\"ופרצת\" על השנה החדשה, בגשמיות, למטה מעשרה טפחים, בבני חיי ומזוני רויחי, ובאופן ש\"אתה מחוייב לעשרו\"<sup data-n=\"1508\">13</sup>, וגם ברוחניות למטה מעשרה טפחים,\nותהי' שנת גאולה, עי\"ז ש\"יעלה הפורץ לפנינו\"<sup data-n=\"1509\">14</sup>.\nכתיבה וחתימה טובה לשנה טובה ומתוקה בגשמיות וברוחניות.\n**********",[["","","<b>העבירה של אי-ניצולן</b>: ראה גם כתובות סז, א.\nנדפסה באגרות-קודש כ\"ק אדמו\"ר שליט\"א חי\"ח אגרת ז'יד. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091451\" data-slug=\"likkutei-sichot\" data-id=\"1300091451\">לקו\"ש ח\"ט ע' 425</a> ואילך. במהדורא זו ניתוספו בשוה\"ג עוד איזה מ\"מ וציונים ע\"י המו\"ל.\n<b>כ\"ה אלול</b>: יום ראשון לבריאת העולם – ויק\"ר רפכ\"ט. פסיקתא דר\"כ פיסקא כג (בחודש השביעי). יל\"ש עה\"פ (פינחס כט, א) ובחודש השביעי (רמז תשפב). תוס' ד\"ה לתקופות – ר\"ה ח, א. וראה פרקי דר\"א רפ\"ח ובהגהות הרד\"ל שם. וראה גם ר\"ן (הובא בחדא\"ג מהרש\"א) לר\"ה טז, א.\n<b>שנת השבע</b>: פ' ראה טו, ט.\n<b>זמן לחשבון הנפש</b>: ראה סה\"מ תרצ\"ו ס\"ע 141 ואילך. תרח\"ץ ס\"ע סו. סה\"מ אידיש ע' 75. שם ע' 129. ובכ\"מ.\n<b>החשבון יכול להיות אמיתי וכו'</b>: ראה מכ' ערב ח\"י אלול ה'תשמ\"א (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241615\" data-slug=\"likkutei-sichot\" data-id=\"1300241615\">לקו\"ש חכ\"ד ע' 601</a> ואילך).<b>מספרים חז\"ל</b>: ראה תיקוני זוהר תיקון נו [צ, ב]. פרקי דר' אליעזר פי\"א.\n<b>ממעל ממש</b>: ראה תניא פרק ב. הגהות ה\"צמח צדק\" שם (בס' קיצורים והערות ע' עב).\n<b>בחיר הנבראים</b>: ראה גם בהנסמן במכ' כ\"ה אלול ה'תשמ\"ז הערות ד\"ה עם בריאת האדם וד\"ה הנברא השלם (לקו\"ש חל\"ד ע' 323).\n<b>ראש השנה הוא היום שבו נברא האדם</b>: ראה תוס' שם. רבינו בחיי עה\"פ בראשית א, יג (ד\"ה ויש לך לדעת). חדא\"ג מהרש\"א לר\"ה כז, א.\n<b>מלאו </b>. .<b> הארץ</b>: בראשית א, כח.\n<b>הנשמה שלו, צלם אלקים</b>: בראשית א, כז. וראה רמב\"ם הל' יסודי התורה פ\"ד ה\"ח-ט. וראה בהנעתק בספר הליקוטים – דא\"ח צ\"צ ערך צלם (ע' שב ואילך).\n<b>בואו </b>. .<b> עושנו</b>: תהלים צה, ו.<b>ה' אחד</b>: ראה סמ\"ק הובא בבית יוסף (טור אורח חיים סי' סא).\n<b>מסוגל</b>: ראה סנהדרין פ\"ד משנה ה. קדושין מ, ב.\n<b>תורת חיים </b>. .<b> מורה דרך</b>: ראה זח\"ג נג, ב. וראה רד\"ק לתהלים יט, ח. גו\"א ר\"פ בראשית בשם הרד\"ק.\n<b>ה' אלקינו ה' אחד</b>: ואתחנן ו, ד.\n<b>וה' הרואה ללבב</b>: שמואל-א' טז, ז."],["1496","1","ראה גם מכתב כ' מנ\"א שנה זו (אג\"ק חי\"ח ע' תקא)."],["1497","2","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091414\" data-slug=\"likkutei-sichot\" data-id=\"1300091414\">סעיף</a> זה – הוגה ע\"י כ\"ק אדמו\"ר שליט\"א (באידית), ונדפס בהוספות ללקו\"ש ח\"ט ע' 387. במהדורא זו ניתוספו עוד איזה ציוני מ\"מ, ופרט מהנחה בלתי מוגה."],["1498","3","יחזקאל מ, א. וראה תוד\"ה ואת – נדרים כג, ב. רא\"ש סוף יומא."],["1499","4","פרש\"י עה\"פ – מערכין יב, א."],["1500","5","שיום הולדתו בערב ראש השנה (מהנחה בלתי מוגה)."],["1501","6","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380951\" data-slug=\"likkutei-torah\" data-id=\"4001380951\">לקו\"ת דרושי ר\"ה נח, א</a> – בהגהה: \"יוהכ\"פ נק' ג\"כ ר\"ה בכתוב, והוא בחי' .. פנימיות .. ובראש השנה בסוד החיצונית\". וראה גם שם סד, א."],["1502","7","ר\"ה ח, ב."],["1503","8","עיין טורי אבן לר\"ה שם."],["1504","9","שם טז, ב."],["1505","10","עיין בחי' הר\"ן לר\"ה שם (ח, ב) ד\"ה מכאן."],["1506","11","תהלים פט, ג."],["1507","12","זכרי' ב, ח."],["1508","13","ע\"פ כתובות סז, ב."],["1509","14","ע\"פ מיכה ב, יג."]]],[1400330016,"בלתי מוגה\n(לאחרי התרת נדרים, אמר כ\"ק אדמו\"ר שליט\"א לעדה שלימה דהמתירין:)\n\"יישר כח\". כתיבה וחתימה טובה לשנה טובה ומתוקה.\n*\n[(כ\"ק אדמו\"ר שליט\"א הורה להכריז בנוגע למסירת הפ\"נ הכללי, שיכנסו רק האברכים הנשואים, ולא תלמידי הישיבה. וכאשר נכנסו למסור הפ\"נ כללי, אמר:)\nטעם הבקשה להכריז שהתלמידים לא יכנסו, הוא – לא בגלל שהתלמידים הם למטה במדריגה, אלא כיון שענינם צריך להיות העסק בתורה, וע\"י התורה נמשכים כל הענינים, ולכן אין להם להתעסק בענינים אחרים, אלא להיות מונחים בתורה.\nלאחרי קריאת הפ\"נ הכללי – אמר כ\"ק אדמו\"ר שליט\"א:]\nיתן השי\"ת כתיבה וחתימה טובה לשנה טובה ומתוקה.\nוכיון שבשנה זו חל ראש השנה בשבת, ובנוגע לשבת אמרו<sup data-n=\"1510\">1</sup> שיש הכל מן המוכן, אלא צריך גם להוסיף, שזהו\"ע \"לעשות את השבת\"<sup data-n=\"1511\">2</sup> – יתן השי\"ת שיומשכו כל ההמשכות מלמעלה למטה, והעבודה מלמטה למעלה תוסיף בזה אלף פעמים ככה.\n*\nישנו ראש השנה שלאחרי שמיטה – שעליו נאמר ש\"מר\"ה עד יוה\"כ לא היו עבדים נפטרין לבתיהן ולא משתעבדין לאדוניהם .. כיון שהגיע יוה\"כ תקעו ב\"ד בשופר נפטרו עבדים לבתיהן\"<sup data-n=\"1512\">3</sup>.\nיתן השי\"ת שבשנה זו יהיו עבדים נפטרים מהשעבוד לבתיהן – שיצאו מהגלות אל ארצנו הקדושה ע\"י משיח צדקנו.יתן השי\"ת כתיבה וחתימה טובה לשנה טובה ומתוקה, בבני חיי ומזוני רויחי, למטה מעשרה טפחים.\n*\nשנה זו היתה גם שנת השמיטה.\nוהנה, אף שלדעת אדמו\"ר הזקן<sup data-n=\"1513\">4</sup> \"זמן הפרוזבול הוא לכתחילה בסוף הששית לפני ר\"ה של שביעית\", ובודאי עשו כן, מ\"מ, הרי במשך השנה השביעית ניתוספו עוד חובות<sup data-n=\"1514\">5</sup>.\n(וסיים כ\"ק אדמו\"ר שליט\"א:) בודאי ישנו כאן בית-דין כשר – ואמר נוסח הפרוזבול (מתוך שו\"ע אדה\"ז<sup data-n=\"1515\">6</sup>): \"הריני מוסר כו'\".\n(ואח\"כ אמר:) השי\"ת ימחול כל חובות עמו ישראל, ויתן להם כל הצטרכותם בגשמיות וברוחניות, מידו המלאה הפתוחה הקדושה והרחבה.\nכתיבה וחתימה טובה לשנה טובה ומתוקה.\n**********",[["1510","1","ראה מכילתא ופרש\"י יתרו כ, ט. טושו\"ע (ואדה\"ז) או\"ח סש\"ו ס\"ח (סכ\"א)."],["1511","2","תשא לא, טז."],["1512","3","ר\"ה ח, ב."],["1513","4","שו\"ע חו\"מ הל' הלואה סל\"ו."],["1514","5","ראה נטעי גבריאל – פרוזבול (ברוקלין, תשמ\"ז) פי\"ב ס\"א. וש\"נ. וראה גם אוצר מנהגי חב\"ד ראש השנה ע' מא (ושם בהערה – מענה מד' תשרי שנה זו). וש\"נ."],["1515","6","שם סל\"ד-ה."]]],[1400330017,"<b>לשלוח לאנ\"ש שי' בכל מרחבי תבל</b>\n<b>לקראת ראש-השנה, ה'תש\"כ</b>\nלשנה טובה תכתבו ותחתמו.\n<b>מנחם שניאורסאהן</b>"],[1400330018,"<b>מפתח ענינים למאמרים</b>\n<b>מפתח ענינים לשיחות</b>"],[1400340002,"התוועדויות\n(יום ב' דראש השנה – ש\"פ ויקהל-פקודי, פ' החודש, מבה\"ח ניסן)"],[1400340003,"(הנחה בלתי מוגה)\n<b>שמע</b> ישראל הוי' אלקינו הוי' אחד<sup data-n=\"1\">1</sup>, ואיתא בגמרא<sup data-n=\"2\">2</sup> לענין פסוקי מלכיות דראש השנה, שמע ישראל ה' אלקינו ה' אחד, מלכות, דברי ר' יוסי, ר' יהודה אומר אינה מלכות, ואנן קיי\"ל לפסק הלכה כר' יוסי<sup data-n=\"3\">3</sup>, שהפסוק שמע ישראל הוא בכלל יו\"ד פסוקי מלכיות, וכמ\"ש בנוסח דמוסף ר\"ה בסיום ברכת מלכיות, ובתורתך כתוב לאמר שמע ישראל הוי' אלקינו הוי' אחד. ומבואר בהמשך וככה<sup data-n=\"4\">4</sup> הטעם הפנימי בפלוגתא זו, דהנה ידוע ששמע ישראל הוא בחי' יחודא עילאה<sup data-n=\"5\">5</sup>, והרי ענין המלכות הוא להיות מקור להתהוות עולמות בי\"ע, שעם היותם בבחי' יש מ\"מ יהי' בהם ביטול, וביטול זה הוא בחי' יחו\"ת, כי, יחו\"ע הוא באצילות<sup data-n=\"6\">6</sup>, שאיהו וחיוהי חד איהו וגרמוהי חד<sup data-n=\"7\">7</sup>, עולם האחדות, משא\"כ בבי\"ע הוא יחו\"ת<sup data-n=\"6\">6</sup>, ולכן סברת ר' יהודה היא ששמע ישראל אינה מלכות, לפי שענינו הוא יחו\"ע. אמנם דעת ר' יוסי, וכן הוא פסק ההלכה, ששמע ישראל הוא מלכות, ומבואר שם ג' טעמים לדבר. טעם א', לפי שהמלכות כמו שהיא באצילות עכ\"פ ה\"ה בכלל כל הע\"ס שהם בחי' יחו\"ע. דהנה, בבחי' המלכות יש ב' ענינים, הא', כמו שהמלכות נעשית כתר לבריאה<sup data-n=\"8\">8</sup>, והב', כמו שהמלכות היא באצילות, ועיקר המלכות היא כמו שהיא באצילות, וכמו שהיא באצילות הרי גם המלכות היא בבחי' יחו\"ע, וכמ\"ש<sup data-n=\"9\">9</sup> אנכי שלומי אמוני ישראל, ולכן הנה גם פסוק שמע ישראל שהוא בחי' יחו\"ע נמנה בכלל פסוקי מלכיות. וממשיך שם, ויש להוסיף עוד בטעם דר' יוסי [והיינו לפי שהטעם הנ\"ל אינו מספיק עדיין, שהרי הכוונה בענין המלכות כאן אינה כמו שהיא באצילות, אלא כמו שנמשכה בבי\"ע, וכמ\"ש<sup data-n=\"10\">10</sup> מלוךעל העולם כולו כו' וידע כל פעול כי אתה פעלתו ויבין כל יצור כי אתה יצרתו, ויאמר כל אשר נשמה באפו כו', שחשיב כאן כל פרטי הנבראים כו' והנעשים שבעוה\"ז, ולכן מבאר עוד טעם בשיטת ר' יוסי], דלו יהא שבחי' המלכות מהוה היש דבי\"ע שביטולו הוא רק בבחי' ביטול היש (יחו\"ת), עכ\"ז ע\"י ביטול היש באים לבחי' ביטול דיחו\"ע, איך שקמי' כלא חשיב. וגם כל ענין האצילות ששם בחי' יחו\"ע הוא בשביל שבחי' המלכות דאצילות תהווה בי\"ע (וכידוע שהכוונה בהאצלת עולם האצילות היא כדי שיהי' ממוצע לעולמות בי\"ע<sup data-n=\"11\">11</sup>), שזהו עיקר המכוון. ויש לומר בביאור הדברים, שלא מספיק מה שכל ענין האצילות הוא בשביל התהוות היש כו', שהרי הכוונה אינה שישאר בבחי' יש כו'<sup data-n=\"12\">12</sup>, אלא כמ\"ש לפנ\"ז שע\"י ביטול היש באים לבחי' ביטול דיחו\"ע, והיינו שהכוונה היא שגם בעולמות בי\"ע יומשך בחי' יחו\"ע. וכידוע מ\"ש בזהר<sup data-n=\"13\">13</sup>, ומבואר בהמשך יו\"ט של ר\"ה תרס\"ו<sup data-n=\"14\">14</sup>, שכוונת הבריאה היא בגין דישתמודעון בי', והיינו, שגם בבי\"ע תהי' הידיעה וההשגה דיחו\"ע. וזהו שגם פסוק שמע ישראל נמנה בפסוקי מלכיות, לפי שהכוונה בבחי' המלכות היא שגם בבי\"ע יהי' היחוד דיחו\"ע כמו באצילות, וזהו\"ע שמע ישראל, שמע לשון הבנה והשגה<sup data-n=\"15\">15</sup>, שהו\"ע ההתבוננות בענין הוי' אלקינו, יחוד או\"א, ועי\"ז יהי' הוי' אחד, יחוד זו\"ן<sup data-n=\"16\">16</sup>.\nב) <b>אמנם</b> צריך להבין<sup data-n=\"17\">17</sup>, איך שייך שבבי\"ע יהי' ענין דישתמודעון בי', דהנה ידוע שכללות העולמות, ובפרט עולמות בי\"ע, התהוותם היא מספירת המלכות (שלכן נקראת בשם שכינה<sup data-n=\"18\">18</sup>, לפי ששוכנת ומתלבשת בתחתונים<sup data-n=\"19\">19</sup>), שהיא בחי' התפשטות הארה בלבד, ולא בחי' עצמיות, ובמלכות גופא הנה ההתהוות היא מהארת המלכות בלבד, וכמ\"ש<sup data-n=\"20\">20</sup> כי נשגב שמו לבדו הודו על ארץ ושמים, והיינו, שהשגתהנבראים יכולה להיות רק בבחי' הארת המלכות בלבד, ועד שגם השגת הנשמות בג\"ע היא רק בבחי' זיו השכינה בלבד, אבל מהמדריגות העצמיות דאצילות [ואין הכוונה כאן על העצם, כי אם על ענין עצמי, כמו מוחין ומדות] אין הנבראים יכולים לקבל. ועוד זאת, שלהיותם עצמיים אין בהם ענין הירידה וההמשכה, אלא אדרבה, יש בהם טבע העלי' והדביקות במקורן. וכמו בהמדות, שאף שהם בשביל העולמות, שהרי המדות הם בחי' גילוי להזולת, שהרי אי אפשר למדות בלא זולת, הנה ענין הירידה והגילוי במדות הוא מצד בחי' המלכות שבמדות, אבל מצד המדות עצמם, הרי הם בתנועה של עלי' למעלה, ומכ\"ש שכן הוא בבחי' המוחין, ולכן אי אפשר שהנבראים ישיגו בחינות אלו. ורק המלכות שהיא הארה בלבד, הרי היא נמשכת למטה להוות את הנבראים, ולכן אפשר שתהי' השגה בבחינה זו, דהא בהא תליא, דמאחר שהיא נמשכת למטה, לכן אפשר שהנבראים יקבלו אותה. ועפ\"ז אינו מובן, איך אפשר שבבי\"ע יהי' ישתמודעון בי', והרי הפירוש דישתמודעון בי' הוא בהקב\"ה עצמו (אין דעם אויבערשטן אַליין) שלמעלה מהספירות, ולא בספירה אחת בלבד. וכדמוכח גם מזה שענין בגין דישתמודעון הוא באצילות, וכמבואר בהמשך יו\"ט של ר\"ה הנ\"ל<sup data-n=\"21\">21</sup> שבאצילות יש ידיעת והשגת אלקות, דאיהו וחיוהי וגרמוהי חד, משא\"כ בבי\"ע, ולכן הנה הכוונה דבגין דישתמודעון היא בענין האצלת האצילות דוקא, אבל לא בהתהוות הבי\"ע, וגם לא בענין הממוצע דאצילות שהוא בשביל בי\"ע.\nג) <b>אך</b> הענין הוא, דהנה כתיב<sup data-n=\"22\">22</sup> הוי' מלך גאות לבש, דבכדי שיהי' הוי' מלך, הרי זה ע\"י ההתלבשות בלבוש גאות. דהנה בבחי' המלכות שהו\"ע ההתנשאות יש ב' ענינים, התנשאות על הזולת, והתנשאות עצמי שמנושא מצד עצמו. ועיקר ענין המלכות הוא ההתנשאות שמצד עצמו. דהנה, ענין ההתנשאות דמלכות הוא מצד עצם הנפש (והיינו, שגם בכחות הכלולים בנפש וגם כמו שהנפש נושא כחות הנה המלכות היא בעומק יותר משאר הכחות, בעצמות הנפש ממש<sup data-n=\"23\">23</sup>), דכיון שעצם הנפש היא בהבדלה מוחלטת מכל הכחות, לכן יש בה כח ההבדלה שהו\"ע ההתנשאות, ומזה מובן שעיקר ענין המלכות הוא ההתנשאות שמצד עצמו. וכמו\"כ הוא גם למעלה, שעיקר ההתנשאות היא ההתנשאות שמצד עצמו,שהתנשאות זו היא באין ערוך לעולמות, שאין העולמות בערך כלל אפילו להתנשאות עליהם. ובכדי שתהי' התנשאות על העולמות הרי זה ע\"י גאות לבש. והנה, בענין לבוש זה יש ב' ענינים. ענין הא' הוא בחי' הצמצום הראשון, שפנימיות האור נסתלק לגמרי ונשארה הארה שבערך העולמות<sup data-n=\"24\">24</sup>, היינו שבערך להתנשאות על עולמות. וענין הב' הוא בחי' מחשבה הקדומה דאנא אמלוך<sup data-n=\"25\">25</sup> שישנה גם קודם הצמצום, שזהו לבוש המעלים, כמו המחשבה שמעלים על השכל, ובפרטיות הו\"ע אותיות המחשבה דבינה שמלבישים ומעלימים על הנקודה דחכמה, וע\"י הלבוש של המחשבה דאנא אמלוך שמלבשת את ההתנשאות עצמי, אפשר להיות אח\"כ ענין הצמצום שעל ידו תומשך הארה שבערך להתנשאות על עולמות.\n<b>והנה</b> גם ההמשכה שע\"י הצמצום היא באופן שתחילת ההמשכה היא בבחינה כללית ואח\"כ באה בבחי' פרטים, ומזה מובן שהפרטים ישנם בהעלם בהכלל, ובהפרטים ישנו הכלל בהעלם. ויובן זה עד\"מ מאדם הבונה בית, שבתחילה יש לו רצון כללי על הבית, ואילו הפרטים אינם ניכרים כלל, והיינו, דהגם שבכדי שהבנין יהי' לפי אופן הכוונה והתענוג שלו הרי זה דוקא כשיהי' מפורט באופן המתאים לכוונתו, מ\"מ הנה ברצון הכללי לא ניכר פרטים כלל, ורק אח\"כ מתגלה רצון פרטי בנוגע לפרטי החדרים כו', עד שכאשר יצוה לאומן לבנות הבית בפועל אזי יבוא כל פרט בפני עצמו, וגם בסדר דקדימה ואיחור, משא\"כ ברצון הכללי לא ניכר פרטים כלל, ומכ\"ש שאין בו סדר דקדימה ואיחור. אמנם באמת בהכרח לומר שגם ברצון הכללי ישנם כל הפרטים בהעלם, שלכן נמשכים אח\"כ בגילוי, וכמו\"כ מובן שבפרטים ישנו בהעלם בחי' הכלל. ועד\"ז יובן למעלה, שתחילת ההמשכה שאחרי הצמצום היא בבחי' כלל, והו\"ע המחשבה הקדומה דא\"ק, שצופה ומביט עד סוף כל הדורות<sup data-n=\"26\">26</sup>, וכולם נסקרים בסקירה אחת<sup data-n=\"27\">27</sup>, והרב המגיד קראו אור כללי<sup data-n=\"28\">28</sup>, והיינו, שלא ניכרים בו פרטים כלל, ורק אח\"כ כשבחי' מלכות דא\"ק נעשית כתר לאצילות, אזי מתגלים הפרטים. ובפרטיות יותר הנה גם באצילות הוא בבחי' כלל עדיין, ורק כאשר מלכות דאצילות נעשית כתר לבריאה,ומלכות דבריאה כתר ליצירה, ומלכות דיצירה כתר לעשי', ומלכות דעשי' כתר לפרטי הנבראים והנעשים שבעוה\"ז, הנה בבחינות אלו מתגלים הפרטים. ומובן ממשל הנ\"ל שגם בבחי' מחשבה הקדומה דא\"ק ישנם הפרטים בהעלם, וכמו\"כ לאידך גיסא, שגם לאחרי שנמשכו הפרטים יש בהם בהעלם בחי' הכלל.\n<b>ועפ\"ז</b> יובן ענין בגין דישתמודעון בי', והיינו, לפי שמבחי' הפרטים אפשר להשיג את בחי' הכלל, ויתירה מזה, שאפשר להשיג גם את בחי' הכלל עצמו שלמעלה יותר מהפרטים, והיינו, שלא זו בלבד שע\"י התגלות הפרטים אפשר להשיג את הפרטים כמו שהם בהכלל, אלא עוד זאת, שאפשר להשיג גם את הכלל עצמו כמו שהוא למעלה מהפרטים, ולא רק כמו שהוא בעילוי לגבי הפרטים שחוץ ממנו, אלא גם כמו שהוא בעילוי לגבי הפרטים כפי שנמצאים בהכלל. וע\"י ההשגה בבחי' הכלל, אפשר להיות ידיעה גם בבחי' ההתנשאות העצמי, כמו שהוא קודם הצמצום, וגם כמו שהוא קודם המחשבה הקדומה דאנא אמלוך. והיינו לפי שהמחשבה הכללית יש בה בהעלם בחי' ההתנשאות העצמי, והו\"ע מלכות דא\"ס שאחרי הצמצום, שיש בה בהעלם בחי' מלכות דא\"ס שקודם הצמצום, דהיינו ההתנשאות העצמי, שלכן היא בבחינה כללית, לפי שיש בה בהעלם ההתנשאות העצמי, אלא שהוא בהעלם והסתר ביותר. ולכן שייך בהנבראים דבי\"ע הענין דישתמודעון בי', לפי שע\"י הפרטים אפשר להשיג בחי' הכלל, ועי\"ז גם בחי' התנשאות עצמי.\nד) <b>אמנם</b> באמת אי אפשר לומר כן, שהרי מה שאפשר להיות מושג בנבראים הוא רק מה ששייך לעולמות, אם בחי' אור פנימי, או גם אור הסובב, בבחי' ידיעת השלילה, אבל בבחי' התנשאות עצמי לא שייך השגה כלל, שהרי כל השגה היא עי\"ז שתופסים את הקצוות, והעצמי אין בו קצוות כלל, וא\"כ לא שייך בו השגה, שהרי הוא באין ערוך כלל לעולמות, עד שהוא באין ערוך גם להיות מתנשא עליהם (כנ\"ל), ומכ\"ש שהוא באין ערוך שישיגו אותו. אך הענין הוא, דהנה, לית מחשבה תפיסא בי' כלל (כדאיתא בזהר<sup data-n=\"29\">29</sup>), כי אם כאשר תפיסא ומתלבשת בתורה ומצותי' אזי היא תפיסא כו' (כמבואר בתניא<sup data-n=\"30\">30</sup>). והיינו, שבחינה זו שעלי' אמרו לית מחשבה תפיסא בי' כלל, אפילו מחשבה הקדומה דא\"ק (שעד בחי' מחשבה זו אפשר להיות השגת הנבראים, וגם מחשבה זו לא תפיסאבי' כלל), הנה בבחינה זו עצמה אפשר לתפוס על ידי תורה ומצוותי'. וזהו בגין דישתמודעון בי', שע\"י תומ\"צ הנה גם בהנבראים דבי\"ע אפשר להיות הידיעה בהעצמות.\nה) <b>וביאור</b> הענין, הנה ידוע שבכללות ההשתלשלות יש ג' בחינות, איהו וחיוהי וגרמוהי (כמבואר בתניא ובמאמרים<sup data-n=\"31\">31</sup>). ופירוש הפנימי בג' בחינות אלו, דאיהו היינו בחי' העצם שלמעלה מענין האורות, חיוהי היינו בחי' האורות שלמעלה מענין הכלים לגמרי ולמעלה מענין ההתלבשות בכלים (ובכללות הוא בחי' האורות דכתר, שאין בהם ענין הכלים), וגרמוהי היינו בחי' האורות המתלבשים בכלים ובחי' הכלים. וג' מדריגות אלו ישנם גם קודם הצמצום, שזהו שאמרו<sup data-n=\"32\">32</sup> עד שלא נברא העולם (וכמו כן עד שלא נאצל<sup data-n=\"33\">33</sup>) הי' הוא ושמו בלבד, דבחי' שמו הוא דוגמת בחי' חיוהי וגרמוהי שלאחרי הצמצום, ובחי' הוא היינו העצם, ולאחרי הצמצום נקרא איהו. ובפרטיות יותר, הנה כללות הע\"ס בבחי' האורות והכלים (גרמוהי) התחלתם היא בבחי' החכמה, שהיא ראשית ההשתלשלות<sup data-n=\"34\">34</sup>, דאף שהחכמה היא בחי' נקודה, מ\"מ, הרי היא באה בגילוי, וזהו ענין אאלפך חכמה<sup data-n=\"35\">35</sup>, שהחכמה נקראת בשם אלף, הרי אל\"ף היא אות, בחי' גילוי, וציור אות אל\"ף הוא נקודה קו נקודה<sup data-n=\"36\">36</sup>, והיינו, דאף שההתחלה היא באופן של נקודה, מ\"מ, הרי היא נמשכת אח\"כ בקו, ועי\"ז באה אח\"כ לבחי' נקודת המקבל. וזהו ענין אאלפך חכמה בבחי' חכמה הגלוי'. וכמו\"כ יש גם ענין אאלפך חכמה בבחי' חכמה שבכתר, זהו אאלפך לשון עתיד, כידוע<sup data-n=\"37\">37</sup> בשם אהי' שהאל\"ף מורה על העתיד, אנא זמין לאתגלאה<sup data-n=\"37\">37</sup>, דהגם שעכשיו היא בבחי' סתימות עדיין, מ\"מ יודעים כבר שעתיד לאתגלאה. וכן הוא גם בענין אאלפך בינה<sup data-n=\"35\">35</sup>, שקאי על הבינה שבכתר, היינו, שגם בבחי' כתר יש שרש ומקור לבינה דעתיד לאתגלאה, שהרי שרש הבינה אינו מהחכמה, אלא יש לה שרש מיוחד בכתר כידוע<sup data-n=\"38\">38</sup>, וזהו ענין אאלפך בינה. אך יש עוד בחינה באל\"ף, אותיותפלא<sup data-n=\"39\">39</sup>, והוא בחי' פנימיות הכתר, בחי' עתיק, שלמעלה מענין התכללות הספירות. ובעומק יותר הנה גם בפנימיות הכתר עצמו יש חילוק בין ז\"ת דעתיק לג\"ר דעתיק, דז\"ת דעתיק מתלבשים באריך, וג\"ר דעתיק הם למעלה מהתלבשות, דרישא לא אתתקן<sup data-n=\"40\">40</sup>. וזהו בחי' איהו.\nו) <b>והנה</b> בכדי להמשיך מבחי' פלא, בחי' איהו, הרי זה ע\"י עשיית הכלים דוקא. דהנה ידוע ששרש הכלים הוא למעלה מהאור, ולכן המשכת האור היא ע\"י הכלי דוקא<sup data-n=\"41\">41</sup>. אמנם, ע\"י עשיית כלים חדשים, דהיינו שגם מה שאינו כלי בעצם נעשה בבחי' כלי, ממשיכים מבחי' איהו שלמעלה מבחי' האור. והיינו, שהעבודה שמצד האורות שהיא בדרך אור ישר מגעת רק בבחי' חיוהי, בחי' הגילויים, ובכדי להגיע להעצם הרי זה ע\"י העבודה שמצד הכלים דוקא, ובפרט ע\"י עשיית כלים חדשים, שמצד ההתחדשות שבדבר בדרך אור חוזר, הרי הוא מגיע בהעצם. ועד\"מ בענין השפעת השכל, כמארז\"ל<sup data-n=\"42\">42</sup> הרבה קבלתי מרבותי הרבה קבלתי מחברי ומתלמידי יותר מכולם, והיינו, שיש אופן השפעה מהרב להתלמיד כמו שהיא מצד עצמה, שהרי יותר משהעגל רוצה לינק הפרה רוצה להניק<sup data-n=\"43\">43</sup>, שענין זה אמרו לר\"ע בנוגע להשפעת השכל, וזוהי השפעה בדרך אור ישר (ועד\"ז הרבה קבלתי מחברי, שהוא למטה מהקבלה מרב, והוא ג\"כ בדרך אור ישר), והשפעה זו היא השפעה מצומצמת. אך ישנו הענין דמתלמידי יותר מכולם, שזהו בבחי' אור חוזר מלמטה למעלה, שמגיע בעומק יותר, ובפרט כאשר התלמיד מקשה קושיות על השכל, שעי\"ז מעורר אצל הרב שיתייגע בעומק יותר, ועד שמגיע בכח השכל היולי העצמי שלמעלה גם מכח המשכיל, ומשם נמשך הגילוי גם להתלמיד.\n<b>וכמו\"כ</b> יובן גם בעבודת האדם, שהעבודה שמצד נפש האלקית היא בדרך אור ישר, ומגעת בבחי' הגילויים. אך העבודה שמצד נפש הבהמית, והיינו, כאשר נפש האלקית מתבוננת בענין אלקי באופן שגם נפש הבהמית יכולה להשיג, ועד שגם נה\"ב מסכמת שצריך להיותואהבת את הוי' אלקיך בכל לבבך<sup data-n=\"44\">44</sup> בשני יצריך<sup data-n=\"45\">45</sup>, הרי זו עבודה שבדרך אור חוזר שמגעת בהעצם. ובעומק יותר, הנה גם ענין זה אינו אמיתית הענין דאור חוזר עדיין, לפי שזהו באופן שמפריד את הטוב דנה\"ב מהרע ומעלה את הטוב כו', אמנם אמיתית הענין דאור חוזר הוא באופן שפועל הכפי' בתוקף הרע דנה\"ב, שעי\"ז נשבר ומתברר ההעלם וההסתר גופא, והיינו, שעצם התוקף דנה\"ב מתהפך ונעשה בבחי' כלי לאלקות, ובאופן דרב תבואות בכח שור<sup data-n=\"46\">46</sup>, ועי\"ז מגיע לבחי' בכל מאדך, שאינו מגיע לזה ע\"י העבודה שמצד נפש האלקית<sup data-n=\"47\">47</sup>, וזהו אמיתית הענין דאור חוזר שעי\"ז מגיע בהעצם. ובכללות הרי זה החילוק בין עבודת הצדיקים לעבודת בעלי תשובה, ובזמני השנה הוא החילוק בין עבודת ניסן לעבודת אלול ותשרי<sup data-n=\"48\">48</sup>, דעבודת הצדיקים היא תמידים כסדרם שזהו בדרך אור ישר, אך עבודת התשובה היא מלמטה למעלה, אני לדודי ודודי לי<sup data-n=\"49\">49</sup>, והעילוי שבזה שדוקא ע\"י הקבלת עול והכפי' בדרך אור חוזר מגיעים בהעצם.\nז) <b>וזהו</b> שהפסוק שמע ישראל נמנה בפסוקי מלכיות, כי, תכלית כוונת הבריאה היא שגם בעולם שלמטה שנתהווה מבחי' המלכות יהי' הענין דישתמודעון בי', הידיעה בהעצם, ע\"י העבודה דתורה ומצוות, ובפרט ע\"י עבודת הבירורים, שזהו ענין שמע ישראל, דנוסף על הפירוש שנת\"ל ששמע הוא מלשון הבנה והשגה, יש גם פירוש ששמע הוא מלשון אסיפה וקיבוץ<sup data-n=\"50\">50</sup>, כמו וישמע שאול<sup data-n=\"51\">51</sup>, שצריך לקבץ ולאסוף ולברר את כל הניצוצות שנפלו למטה, שזהו\"ע שמע, שם ע'<sup data-n=\"52\">52</sup>, שם בגימטריא רפ\"ח וב\"ן<sup data-n=\"53\">53</sup>, והיינו, בירור הרפ\"ח ניצוצות ע\"י שם ב\"ן, והעלאתם לבחי' ע' עד לבחי' ע' רבתי. וזהו גם מה שמסיים הוי' אחד, דלכאורה, כיון שמדבר כאן בענין היחוד, ובפרט ע\"פ משנת\"ל שהו\"ע יחו\"ע, הול\"ל הוי' יחיד, שמורה יותר על האחדות מכמו תיבת אחד<sup data-n=\"54\">54</sup>, ולמה נאמר אחד. אך הענין הוא, שעיקר הכוונה היא באסיפת וקיבוץ הניצוצות שנפלולמטה, דמאן דנפיל איקרי מית<sup data-n=\"55\">55</sup>, והעלאתם למעלה לבחי' הא', א\"ס, אלופו של עולם, וזהו\"ע אחד דוקא, כמארז\"ל<sup data-n=\"56\">56</sup> כד אמליכתי' כו'. וזהו גם ענין העבודה דר\"ה, כמארז\"ל<sup data-n=\"57\">57</sup> שתמליכוני עליכם&lt;12&gt;. ודוקא ע\"י עבודה זו תופסים בהעצם, כיון שעי\"ז נשלמת הכוונה שנתאוה הקב\"ה להיות לו יתברך דירה בתחתונים<sup data-n=\"58\">58</sup>.\n**********<b>בס\"ד. שיחת</b>*<b> יום ב' דראש-השנה, ה'תש\"כ</b>.\nבלתי מוגה\n<b>א</b>. כ\"ק אדמו\"ר שליט\"א נטל ידיו הק' לסעודה.\nאח\"כ צוה לנגן הניגון \"אבינו מלכנו\".\nאח\"כ צוה לנגן ניגון שלש תנועות (דהבעש\"ט, המגיד ואדמו\"ר הזקן), הניגון \"צאינה וראינה\" (לאדמו\"ר הזקן), וניגון מכל אחד מרבותינו נשיאינו.\nאח\"כ צוה לנגן ואמר מאמר ד\"ה שמע ישראל גו'.\n***\n<b>ב</b>. הקביעות דשנה זו היא באופן דיום טוב של ראש השנה שחל להיות בשבת.\nומבואר בדרושי חסידות<sup data-n=\"59\">1</sup> פנימיות הטעם למה לא היו תוקעים בשופר בר\"ה שחל בשבת – כי, כל הענינים שצריכים לפעול ע\"י השופר, נפעלים מאליהם מצד ענין השבת.\nובפרטיות יותר – ג' הסעודות דשבת הם ג' הענינים דמלכיות זכרונות ושופרות<sup data-n=\"60\">2</sup>, או ג' הענינים דתקיעה שברים ותרועה.\nוהיינו, שהמשכת המלכות מלמעלה שנעשית ע\"י תקיעת שופר – נעשית ע\"י ענין השבת, התפלות ואמירת הפסוקים.\n<b>ג</b>. אמנם, עפ\"ז צריך ביאור למה תוקעים בשופר ביום שני דר\"ה:\nידוע בענין ב' הימים דר\"ה, שגם בזמן הבית שהיו מקדשים ע\"פ הראי' היו עושים שני ימים ר\"ה, מצד ספיקא דיומא<sup data-n=\"61\">3</sup>. אך צריך להבין בנוגע לר\"ה שחל בשבת, שאז נעשית מעצמה ההמשכה מלמעלה מצד ענין השבת, ללא עבודת האדם – הרי למעלה לא שייך ענין של ספק, וא\"כ, מדוע צריכים לתקוע בשופר ביום שני דר\"ה?והביאור בזה – שתקיעת שופר ביום שני דר\"ה היא כדי לפעול את ההמשכה שמלמעלה ע\"י עבודה ועשי'<sup data-n=\"62\">4</sup>.\nוהענין בזה – שיש מעלה בהמשכה שע\"י עבודה ועשי' לגבי ההמשכה שמלמעלה. וע\"ד משנת\"ל בהמאמר<sup data-n=\"63\">5</sup>, שיש מעלה בקיום התומ\"צ באופן של <b>עשי' וכפי'</b> לגבי קיום התומ\"צ סתם, שדוקא ע\"י העשי' והכפי' \"לוקחים\" את העצם.\n[וזהו גם הביאור במארז\"ל<sup data-n=\"64\">6</sup> \"מה איכפת לי' להקב\"ה למי ששוחט מן הצואר כו', לא ניתנו המצוות אלא לצרף בהם את הבריות\", דלכאורה הרי זה בסתירה להמאמר<sup data-n=\"65\">7</sup> \"עבודה צורך גבוה\"? אך הענין הוא, שהתומ\"צ מצד עצמם מגיעים לבחי' גבוה, אבל בכל זה – מדודה ומוגבלה, ואילו ענין צירוף הבריות, שהו\"ע העשי' וכפי', מגיע עד למעלה מזה – בחי' שעלי' נאמר \"מה איכפת לי'\"<sup data-n=\"66\">8</sup>].\nוזוהי המעלה המיוחדת <b>ביום ב'</b> דר\"ה כאשר יו\"ט של ר\"ה חל בשבת (משא\"כ בשאר השנים) – שבו היא התחלת ההמשכה ע\"י עבודה ועשי'.\n<b>ד</b>. ובענין זה מתבטאת גם מעלת שנה זו לגבי שנה שעברה:\nשנה שעברה היתה שנת השמיטה, וממנה נכנסים לשנה השמינית, שבה ישנה מצות הקהל: \"הקהל את העם האנשים והנשים והטף\"<sup data-n=\"67\">9</sup>, כדי לשמוע פרשת המלך<sup data-n=\"68\">10</sup>.\nוהחילוק שביניהם:\nשנת השמיטה היא \"שבת להוי'\"<sup data-n=\"69\">11</sup>, ומפרש רש\"י (מספרא): \"כשם שנאמר בשבת בראשית\". והרי \"שבת מקדשא וקיימא\"<sup data-n=\"70\">12</sup>, שזהו\"ע של המשכה מלמעלה למטה, וכמו\"כ גם עניני העבודה דשנת השמיטה הם בדרך אור ישר.\nואילו בשנה זו – ישנה המעלה דאור חוזר, שהו\"ע העשי' והכפי', וזה מגיע בהעצם.<b>ה</b>. ומזה מובן גם בנוגע להמדובר בהענין ד\"ופרצת\":\nכללות הענין ד\"ופרצת\" הוא מצד ההמשכה מלמעלה שהיא בבחי' בלי גבול. אמנם, העבודה צריכה להיות בדרך אור חוזר, והיינו, שצריכים לפעול בהמטה, שהוא בהגבלה, שגם בו יהי' הענין ד\"ופרצת\", שלא יהיו הגבלות, ועד שלא תהי' נתינת מקום לגבול.\nוע\"ד המבואר בענין התשובה, שאינה רק על עבירות ממש, אלא גם על האפשרות לענין בלתי-רצוי מצד ריבוי ההשתלשלות ומצד כמה סיבות וענינים צדדיים, והיינו, שענין התשובה הוא שלא תהי' נתינת מקום לענין שלא כדבעי. וכמו\"כ בענין ד\"ופרצת\", שגם למטה צריכים לפעול שלא תהי' נתינת מקום לגבול.\nועד שיקויים היעוד<sup data-n=\"71\">13</sup> \"פרזות תשב ירושלים\": \"פרזות\" – בלי גבול, ו\"תשב\" – בהתיישבות, שזוהי תכלית הכוונה דעשיית דירה לו יתברך: לו – לעצמותו ית', אמיתית הבלי גבול, ולזו תהי' \"דירה\" – בהתיישבות, \"תשבו כעין תדורו\"<sup data-n=\"72\">14</sup>.\nוע\"י העבודה ד\"ופרצת\" פועלים ש\"יעלה הפורץ לפנינו\"<sup data-n=\"73\">15</sup>, שתהי' שנת גאולה.\n[כ\"ק אדמו\"ר שליט\"א צוה לנגן \"ופרצת\" עבור כל המוסדות שעל טהרת הקודש, ועבור מוסדות חב\"ד בפרט, וכמחז\"ל<sup data-n=\"74\">16</sup> – \"עירך קודמין\". ואח\"כ צוה לנגן \"ופרצת\" עבור כפר חב\"ד.\nלאחרי ברכת המזון, תפלת ערבית והבדלה, נתן כ\"ק אדמו\"ר שליט\"א לכל אחד מ\"כוס של ברכה\"].\n**********",[["1","1","ואתחנן ו, ד."],["2","2","ר\"ה לב, ב."],["3","3","טור או\"ח סתקצ\"א."],["4","4","תרל\"ז – סוף פרק פ."],["5","5","זהר ח\"א יח, ב. <a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא</a> שעהיוה\"א בתחילתו. פ\"ז. ובכ\"מ."],["6","6","ראה סהמ\"צ להצ\"צ שרש מצות התפלה פי\"ט. פכ\"ב-כג. ד\"ה כל המאריך באחד תרע\"ח (סה\"מ תרע\"ח ס\"ע שפג ואילך). ובכ\"מ."],["7","7","תיקוני זהר בהקדמה (ג, ב)."],["8","8","ראה עץ חיים שער ג (שער סדר אצילות למהרח\"ו) פ\"ב. שער ו (שער עקודים) פ\"ב. שער מב (שער דרושי אבי\"ע) פ\"א. ועוד."],["9","9","שמואל-ב כ, יט."],["10","10","בתפלת מוסף דר\"ה (בפסוקי מלכיות). וראה סידור האריז\"ל במקומו."],["11","11","ד\"ה עוטה אור כשלמה תער\"ב (המשך תער\"ב ח\"א ע' יב ואילך). ובכ\"מ."],["12","12","חסר קצת (<b>המו\"ל</b>)."],["13","13","ח\"ב מב, ב."],["14","14","ע' ד ואילך."],["15","15","ראה ספורנו עה\"פ. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370002\" data-slug=\"torah-or\" data-id=\"3901370002\">תו\"א בראשית א, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380391\" data-slug=\"likkutei-torah\" data-id=\"4001380391\">לקו\"ת נשא כ, ד</a>. מאמרי אדה\"ז תקס\"ג ח\"ב ע' תרעז. אוה\"ת עקב ע' תעט. ובכ\"מ."],["16","16","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381245\" data-slug=\"likkutei-torah\" data-id=\"4001381245\">ראה גם זח\"ג רסג, א</a>. סידור שער השמים (של\"ה) במקומו. לקו\"ת שה\"ש כט, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550420\" data-slug=\"torat-chaim\" data-id=\"2300550420\">תורת חיים פקודי תרסט, א</a> (בהוצאה החדשה – ח\"ב תנא, ד). וש\"נ."],["17","17","בהבא לקמן – ראה ד\"ה שמע ישראל דש\"פ ואתחנן תרע\"א (סה\"מ אעת\"ר ע' קסו ואילך). וראה גם ד\"ה הנ\"ל דיום ב' דר\"ה תשט\"ו (תו\"מ חי\"ג ע' 3 ואילך)."],["18","18","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310057\" data-slug=\"tanya\" data-id=\"3401310057\">תניא רפנ\"ב</a>. ובכ\"מ."],["19","19","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא</a> שם. וראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא פמ\"א (נז, ב</a>). שם אגה\"ק סל\"א (קנב, א)."],["20","20","תהלים קמח, יג. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380220\" data-slug=\"likkutei-torah\" data-id=\"4001380220\">לקו\"ת אמור לג, ג</a>. ובכ\"מ."],["21","21","ע' ו."],["22","22","תהלים צג, א."],["23","23","ראה גם סה\"מ תרל\"ה ח\"ב ע' שכא. המשך תער\"ב ח\"ג ע' א'ריד-רטז. סה\"מ תרפ\"ט ע' 15. וש\"נ. ד\"ה זה היום דיום ב' דר\"ה תשי\"ז (תו\"מ חי\"ח ע' 4 ואילך)."],["24","24","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380297\" data-slug=\"likkutei-torah\" data-id=\"4001380297\">ראה עץ חיים שער א</a> (דרוש עיגולים ויושר) ענף ב. אוצרות חיים ומבוא שערים בתחילתם. לקו\"ת הוספות לויקרא ד\"ה להבין מ\"ש באוצ\"ח (נא, ב ואילך)."],["25","25","ראה עטרת ראש שער ר\"ה פ\"ה. המשך יו\"ט של ר\"ה תרס\"ה ותש\"ג."],["26","26","תפלת מוסף דר\"ה (בפסוקי זכרונות)."],["27","27","ר\"ה יח, א."],["28","28","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380705\" data-slug=\"likkutei-torah\" data-id=\"4001380705\">לקו\"ת מסעי צה, ב</a>. סהמ\"צ להצ\"צ נח, ב. אוה\"ת ענינים ע' פד."],["29","29","תקו\"ז בהקדמה (יז, א)."],["30","30","ספ\"ד."],["31","31","ראה תניא אגה\"ק ס\"כ. המשך תער\"ב ח\"א פרק קנג."],["32","32","פרקי דר\"א פ\"ג."],["33","33","עבודת הקודש חלק א פרק ב. וראה ספר הערכים – חב\"ד ח\"ד ערך אור אין סוף (ה) ס\"א סק\"ג (ע' תמה ואילך). וש\"נ."],["34","34","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310013\" data-slug=\"tanya\" data-id=\"3401310013\">תניא</a> שעהיוה\"א פ\"ח (פה, ב). ובכ\"מ."],["35","35","איוב לג, לג. וראה שבת קד, א."],["36","36","ראה ספר הערכים – חב\"ד מערכת אותיות אות אל\"ף סעיף טז, ובהנסמן שם."],["37","37","ראה זח\"ג יא, סע\"א. סה, ב. וראה גם ד\"ה כל המאריך באחד הנ\"ל (סה\"מ תרע\"ח ע' שפז)."],["38","38","ראה אמרי בינה שער הק\"ש פנ\"ט. סה\"מ תרנ\"ט ע' עד ואילך. תרצ\"ז ע' 182. וש\"נ."],["39","39","ראה תקו\"ז ת\"ע (קלה, א). אמרי בינה שם פנ\"ז. פס\"ב ואילך. ד\"ה כל המאריך באחד הנ\"ל (סה\"מ תרע\"ח ע' שפו ואילך). סה\"מ תרפ\"ט ע' 65. וש\"נ."],["40","40","ראה עץ חיים שער יג (שער אריך אנפין) פ\"א-ב."],["41","41","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370434\" data-slug=\"torah-or\" data-id=\"3901370434\">תו\"א צז, א</a> ואילך. מאמרי אדה\"ז תקס\"ב ח\"א ע' ר ואילך. ח\"ב ע' תמ ואילך."],["42","42","תענית ז, א. מכות י, א."],["43","43","פסחים קיב, א."],["44","44","ואתחנן ו, ה."],["45","45","משנה ברכות רפ\"ט (נד, א). ספרי ופרש\"י עה\"פ."],["46","46","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381024\" data-slug=\"likkutei-torah\" data-id=\"4001381024\">משלי יד, ד</a>. וראה לקו\"ת האזינו עה, ב. ובכ\"מ."],["47","47","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370179\" data-slug=\"torah-or\" data-id=\"3901370179\">תו\"א מקץ לט, ג</a>-ד. סה\"מ תר\"ם ח\"ב ע' תצט."],["48","48","ראה סה\"מ תרל\"ו ח\"ב ע' שס. תרנ\"ב ס\"ע ג. וראה אוה\"ת בא ע' רס ואילך."],["49","49","שה\"ש ו, ג. וראה סה\"מ תרכ\"ז ע' רכב."],["50","50","מאמרי אדה\"ז ואוה\"ת שם."],["51","51","שמואל-א טו, ד."],["52","52","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370465\" data-slug=\"torah-or\" data-id=\"3901370465\">זהר ח\"ג רלו, ב</a> (ברע\"מ). תו\"א הוספות לויחי קה, ג. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380841\" data-slug=\"likkutei-torah\" data-id=\"4001380841\">לקו\"ת ואתחנן יב, ד</a> ואילך. פ' ראה לא, ב."],["53","53","ראה לקו\"ת ואתחנן ופ' ראה שם."],["54","54","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370248\" data-slug=\"torah-or\" data-id=\"3901370248\">תו\"א וארא נה, ב</a>. ובכ\"מ."],["55","55","כ\"ה בלקו\"ת חוקת נו, ד. ובכ\"מ. וראה זהר ח\"ג קלה, ב. הובא בעץ חיים שער שבירת הכלים פ\"ב."],["56","56","ברכות יג, ב."],["57","57","ר\"ה טז, א. לד, ב."],["58","58","ראה תנחומא בחוקותי ג. נשא טז. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו. תניא רפל\"ו. ובכ\"מ.*) ברשימת ההנחה – איזה תיקונים שתיקן כ\"ק אדמו\"ר שליט\"א (<b>המו\"ל</b>)."],["59","1","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380943\" data-slug=\"likkutei-torah\" data-id=\"4001380943\">לקו\"ת דרושי ר\"ה נו, א</a> ואילך. ובכ\"מ."],["60","2","ראה המשך תרס\"ו ע' תקמג ואילך. ועוד."],["61","3","ראה רמב\"ם הל' קידוה\"ח פ\"ה ה\"ז. וראה גם תו\"מ חט\"ו ע' 100 הערה 2. וש\"נ."],["62","4","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300141137\" data-slug=\"likkutei-sichot\" data-id=\"1300141137\">לקו\"ש חי\"ד ע' 125</a>."],["63","5","ספ\"ו (לעיל ע' 10)."],["64","6","ב\"ר רפמ\"ד. וש\"נ."],["65","7","ראה עבוה\"ק בהקדמה. שם ח\"ב (חלק העבודה) פ\"ג. הובא בשל\"ה שער הגדול (כט, ב ואילך)."],["66","8","ראה תו\"מ ח\"ד ע' 324 ואילך. וש\"נ."],["67","9","וילך לא, יב."],["68","10","ראה סוטה מא, א."],["69","11","בהר כה, ב."],["70","12","ביצה יז, א."],["71","13","זכרי' ב, ח."],["72","14","סוכה כח, ב."],["73","15","ע\"פ מיכה ב, יג. וראה ב\"ר פפ\"ה, יד ובפרש\"י שם. אגדת בראשית ספס\"ג."],["74","16","ב\"מ עא, א."]]],[1400340004,"<h3>בס\"ד. ברכת<sup data-n=\"75\">*</sup><b> כ\"ק אדמו\"ר שליט\"א</b></h3>\n<b>ערב יום הכיפורים ה'תש\"כ.</b>\nבלתי מוגה\n[לאחרי תפלת מנחה:]\nהשי\"ת יתן חתימה וגמר חתימה טובה לכ\"א בפרט, בתוך כלל ישראל,\nותהי' העבודה – כפי שציוו הרביים באופן ד\"אַריבער\"<sup data-n=\"76\">1</sup> – בבחינת תשובה עילאה שהיא בשמחה<sup data-n=\"77\">2</sup>, ולהמשיך את השמחה במילואה בכל הענינים על כל השנה.\nוהשי\"ת יקיים את המצוה שצוה \"הקהל את העם האנשים והנשים והטף גו' למען ישמעו ולמען ילמדו ויראו גו'\"<sup data-n=\"78\">3</sup> – ע\"י משיח צדקנו, בגאולה האמיתית והשלימה, בקרוב ממש, למטה מעשרה טפחים.\nשנה טובה ומתוקה, בבני חיי ומזוני רויחי. גמר חתימה טובה לכל אחד ואחד בתוך כלל ישראל.\n[לקבוצה נוספת:]\nהשי\"ת יתן חתימה וגמר חתימה טובה לכל אחד, בתוך כלל ישראל,\nותהי' העבודה – כפי שהי' רצון הרביים – באופן ד\"אַריבער\"<sup data-n=\"76\">1</sup>, לעבור מיד לעבודה דתשובה עילאה שהיא בשמחה<sup data-n=\"77\">2</sup>.\nובהיות ששנה זו היא מאתיים שנה להילולא-הסתלקות הבעש\"ט – יעזור השי\"ת שיפוצו מעינותיו חוצה, כך, שתורת הבעש\"ט תפרוץ את כל ההגדרות, ההעלמות וההסתרים, ויהי' \"ופרצת ימה וקדמה וצפונה ונגבה\"<sup data-n=\"79\">4</sup> בלימוד התורה, בשמחה וטוב לבב, מתוך הרחבה.\nוע\"פ מארז\"ל<sup data-n=\"80\">5</sup> \"מה שהוא אומר לישראל לעשות הוא (השם) עושה\" – יקיים השי\"ת הציווי ד\"הקהל את העם האנשים והנשים והטף\"<sup data-n=\"78\">3</sup>, ע\"י משיח צדקנו, בגאולה האמיתית והשלימה, למטה מעשרה טפחים.\nחתימה וגמר חתימה טובה לשנה טובה ומתוקה, בבני חיי ומזוני רויחי.\n**********",[["75","*","ברשימת ההנחה – איזה תיקונים שתיקן כ\"ק אדמו\"ר שליט\"א (<b>המו\"ל</b>)."],["76","1","ראה גם שיחת ש\"פ נצו\"י, כ\"ג אלול תשי\"ט בסופה (תו\"מ חכ\"ו ע' 235). וש\"נ."],["77","2","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310082\" data-slug=\"tanya\" data-id=\"3401310082\">תניא אגה\"ת פי\"א</a>. ובכ\"מ."],["78","3","וילך לא, יב."],["79","4","ויצא כח, יד."],["80","5","ראה שמו\"ר פ\"ל, ט."]]],[1400340005,"<h3>בס\"ד. ברכת<sup data-n=\"81\">*</sup><b> כ\"ק אדמו\"ר שליט\"א להתלמידים שיחיו</b></h3>\n<b>ערב יום הכיפורים לפני כל נדרי, ה'תש\"כ </b><b>– בחדרו הק'</b>.\nבלתי מוגה\n\"וידבר ה' אל משה לאמר. דבר אל אהרן ואל בניו לאמר כה תברכו את בני ישראל אמור להם. יברכך ה' וישמרך. יאר ה' פניו אליך ויחונך. ישא ה' פניו אליך וישם לך שלום. ושמו את שמי על בני ישראל ואני אברכם\"<sup data-n=\"82\">1</sup>.\nהשי\"ת יעזור שתהיו חסידים יראי-שמים ולומדים,\nויקויים בכם \"הם הכירוהו תחלה\"<sup data-n=\"83\">2</sup> – ע\"י אור הנגלה והחסידות, ולחדור (\"דורכנעמען\") את העולם ב\"נר מצוה ותורה אור\"<sup data-n=\"84\">3</sup>, אור הנגלה והחסידות,\nויהי' קאתי מר דא מלכא משיחא – ש\"יעלה הפורץ לפנינו\"<sup data-n=\"85\">4</sup>, ע\"י \"ופרצת ימה וקדמה וצפונה ונגבה\"<sup data-n=\"86\">5</sup>, עד ל\"נחלה בלי מצרים\"<sup data-n=\"87\">6</sup>.\nהשי\"ת יתן לכם חתימה וגמר חתימה טובה, בתוככי כלל ישראל.\n**********",[["81","*","ברשימת ההנחה – איזה תיקונים שתיקן כ\"ק אדמו\"ר שליט\"א (<b>המו\"ל</b>)."],["82","1","נשא ו, כב-כז."],["83","2","סוטה יא, ב."],["84","3","משלי ו, כג."],["85","4","ע\"פ מיכה ב, יג."],["86","5","ויצא כח, יד."],["87","6","שבת קיח, סע\"א."]]],[1400340006,"(הנחה בלתי מוגה)\n<b>העושה</b> סוכתו תחת האילן כאילו עשאה בתוך הבית<sup data-n=\"88\">1</sup>, וצריך להבין<sup data-n=\"89\">2</sup>, דאיתא במד\"ר פ' וירא<sup data-n=\"90\">3</sup>, שאמר הקב\"ה לאברהם אבינו, אתה אמרת והשענו תחת העץ<sup data-n=\"91\">4</sup>, חייך שאני פורע לבניך במדבר, ובישוב, ולעתיד לבא, במדבר שנאמר<sup data-n=\"92\">5</sup> פרש ענן למסך, בישוב שנאמר<sup data-n=\"93\">6</sup> בסוכות תשבו שבעת ימים, לעתיד לבוא שנאמר<sup data-n=\"94\">7</sup> וסוכה תהי' לצל יומם, ונמצא, שכל ענין הסוכה הוא מצד זה שאמר אברהם אבינו והשענו תחת העץ, תחת האילן, וא\"כ אינו מובן טעם הפסול דהעושה סוכתו תחת האילן.\n<b>ויובן</b> זה בהקדים ביאור ענין חודש תשרי, שכל הענינים שבו הם ענינים כלליים על כל השנה<sup data-n=\"95\">8</sup>, ובכללות יש בחודש זה ב' ענינים, הענינים עצמם, וההתגלות שלהם, שזהו מ\"ש<sup data-n=\"96\">9</sup> תקעו בחודש שופר בכסה ליום חגנו, והיינו, שענינים אלו שבראש השנה וביום הכיפורים הם בכסה, הרי הם באים בהתגלות ליום חגנו. והענין בזה, דהנה, כללות החודש הו\"ע השופר, בחודש שופר. וענין השופר הוא כמ\"ש הרמב\"ם<sup data-n=\"97\">10</sup> אע\"פ שתק\"ש בר\"ה גזירת הכתוב, רמז יש בו וכו', שהו\"ע התשובה דר\"ה, לאחרי הקדמת עבודת התשובה דחודש אלול ובפרט בימי הסליחות. ואח\"כ ניתוסף בזה בעשי\"ת שאז יש נתינת כח מלמעלה, כמ\"ש<sup data-n=\"98\">11</sup> דרשו הוי' בהמצאו קראוהו בהיותו קרוב, ועד לגמר הענין ביום הכיפורים, שנאמר בו סלחתי כדברך<sup data-n=\"99\">12</sup>, היינו, שפועלים הכפרה והריצוי על כל עניני הפגמיםוחטאים (כולל גם חטא מלשון חסרון<sup data-n=\"100\">13</sup>), ע\"י התגלות י\"ג מדות הרחמים, שבהם כתיב<sup data-n=\"101\">14</sup> ויעבור הוי' גו' נושא עון ועובר על פשע. אמנם, ביום הכיפורים הרי זה עדיין בכסה, וההתגלות היא בחג הסוכות, שזהו\"ע הסוכה שבה מתגלה ענן הקטורת דיום הכיפורים<sup data-n=\"102\">15</sup>, דכתיב בי'<sup data-n=\"103\">16</sup> כי בענן אראה, אראה סתם, וקאי על העצמות<sup data-n=\"104\">17</sup> דלא אתרמיז לא בשום אות ולא בשום קוץ<sup data-n=\"105\">18</sup>, שמצד בחינה זו נעשה ענין הכפרה, הנה התגלות ענין זה היא בחג הסוכות. וע\"פ האמור שבסוכות מתגלה ענין התשובה, יובן שלילת הענין דהעושה סוכתו תחת האילן, כדלקמן.\nב) <b>וביאור</b> הענין, דהנה ענין התשובה תחילתה היא תשובה תתאה, ואח\"כ מגיעים לתשובה עילאה עד שזדונות נעשים כזכיות<sup data-n=\"106\">19</sup>, שזהו מצד גילוי בחינה שלמעלה מהוי', שהרי איתא בזהר<sup data-n=\"107\">20</sup> שהמצוות תלויים ב(האותיות ד)שם הוי', וא\"כ, בכדי שתהי' הכפרה על הפגמים והחטאים, עד שלא רק שלא יזכירו לו דבר וחצי דבר<sup data-n=\"108\">21</sup>, אלא שיהי' גם מרוצה כמו קודם החטא, ועוד יותר מכמו קודם החטא, שזוהי מעלת בעלי תשובה על צדיקים, כמרז\"ל<sup data-n=\"109\">22</sup> במקום שבעלי תשובה עומדים אין צדיקים גמורים יכולים לעמוד שם, הנה זה דוקא ע\"י בחינה שלמעלה מהוי', והו\"ע התגלות התענוג. ובפרטיות יותר<sup data-n=\"110\">23</sup>, הנה בענין התגלות התענוג יש ב' בחינות, גילוי התענוג ברצון, וגילוי התענוג בחכמה. וההפרש ביניהם, שברצון מתגלה רק חיצוניות התענוג ובבחי' מקיף, ובחכמה מתגלה פנימיות התענוג ובפנימיות. וכמו\"כ יש בחכמה ב' מדריגות, חכמה סתימאה וחכמה הגלוי', שדוגמתם בנפש האדם הו\"ע כח המשכיל וחכמה הגלוי'. וענין חג הסוכות הוא גילוי בחי' חכמהסתימאה שבה מתגלה בחי' פנימיות התענוג, והוא שרש לי\"ג תקוני דיקנא שהם יגמה\"ר שמהם נמשכת הסליחה והכפרה על כל הפגמים והחטאים, עד שנעשה מרוצה עוד יותר מכמו קודם החטא.\n<b>אך</b> צריך להבין, דכיון שהמצוות תלויים בשם הוי', הרי הכפרה צריכה להיות מבחינה שלמעלה מהשתלשלות, ובפרט ע\"פ המבואר שהמצוות הם בחי' תרי\"ג ארחין דגלגלתא<sup data-n=\"111\">24</sup>, שמזה מובן שהכפרה צריכה להיות מבחינה נעלית יותר, וא\"כ, איך אפשר שתהי' הכפרה מבחי' חכמה סתימאה, שהיא שרש לחכמה הגלוי', ולמטה מהרצון, בחי' גלגלתא. אך הענין הוא, שבחכמה סתימאה יש ב' מדריגות, מקור לחכמה הגלוי', ומקור ליגמה\"ר, והם ב' מקיפים שבה, מקיף דאור ישר, ומקיף דאור חוזר.\nג) <b>וביאור</b> ענין מקיף דאו\"י ומקיף דאו\"ח<sup data-n=\"112\">25</sup>, יובן מענין השפעת השכל מרב לתלמיד, שיש בזה ג' בחינות. יש מה שהתלמיד מקבל בפנימיותו, ויש מה שנשאר עליו בבחי' מקיף והעלם, היינו שמקיף את הכלים שלו, לפי שהוא למעלה מהם, ויש גם בחי' מקיף שלא נמשך כלל מהמשפיע. וב' מקיפים אלו הם מקיף דאו\"י ומקיף דאו\"ח. מקיף דאו\"י הוא מה שמקיף את הכלים שלו לפי שהוא למעלה מהם, והיינו שהכלים שלו אינם יכולים לקבל את האור, ועוד זאת, שגם האור הפנימי לא בא עדיין בהתיישבות אצלו כפי הצורך, ומצד ב' סיבות אלו, קוטן הכלי והעדר ההתיישבות, נשאר אצלו עיקר האור בבחי' מקיף והעלם. אמנם, כאשר מתקן ב' סיבות אלו, שנעשה כלי ומייגע עצמו בהאור פנימי שיתיישב אצלו [ובאמת הנה הא בהא תליא, שע\"י היגיעה וההתיישבות גופא מתגדלים ומתרחבים הכלים], אזי נמשך ומתגלה גם האור שהי' בתחילה בבחי' מקיף. ומובן מזה, שגם בתחילה, טרם שנתגלה האור, הי' ההעלם רק מצד המקבלים ולא מצד עצמו, דכיון שכאשר יתתקנו הסיבות שבמקבל אזי יומשך האור בפנימיות, הרי מוכח שגם עכשיו ההעלם הוא רק מצד המקבל ולא מצד האור עצמו. ועוד זאת, שההעלם הוא רק לגבי', ומה שאצלו הוא בבחי' מקיף, הנה אצל אחר הוא בפנימיות. וזהו ג\"כ מ\"ש<sup data-n=\"113\">26</sup> עמוק עמוק מי ימצאנו, דבתחילה אומר עמוק עמוק, היינו שהוא מרגיש את העומק, ואח\"כ אומר מי ימצאנו, שאין לו שום מבוא כלל אליו, והיינו, שענין זה קאי על בחי' מקיף דאו\"י, שמרגיש את העומקשבו, אבל עכשיו אין לו שום מבוא ופתח כלל אליו, כי הוא למעלה מהכלים שלו. אמנם בחי' מקיף דאו\"ח היינו שהאור הוא סתום מצד עצמו. ואין הכוונה להמבואר בכ\"מ שהאור חוזר מן הכלים, היינו שנמשך בהכלים וחוזר מהם למעלה, דכיון שאור זה חוזר מהכלים הרי הוא שייך להכלים (אלא שחוזר מהם), ובכללות הרי זה הענין דאו\"י. וע\"ד מה שאמר שלמה לענין פרשת פרה אדומה, אמרתי אחכמה והיא רחוקה ממני<sup data-n=\"114\">27</sup>, דמ\"ש אמרתי אחכמה, היינו, שענין זה שייך להשגתו, אלא שהיא רחוקה ממנו, ומובן שאין זה אמיתית הענין דאו\"ח, דא\"כ, לא הי' אצלו ס\"ד כלל לומר אחכמה, ומזה שבתחילה אמר אחכמה, מובן, שזהו אור השייך להיות נמשך בכלים, אלא אעפ\"כ היא רחוקה ממני, שחוזר מהכלים שלו, שהו\"ע או\"ח כמו שהוא במקיף דאו\"י. אמנם ענין או\"ח המבואר כאן היינו שהוא חוזר בעצם למקורו, ולא מצד הכלים, והיינו, דכשם שטבע הגילוי וההארה הוא להיות נמשך למטה, כמו\"כ טבע אור זה הוא להתעלות ולהתכלל למעלה בעילוי אחר עילוי (אַלץ העכער און העכער טיפער און טיפער), והוא סתום מצד עצמו. וענין ב' בחינות מקיפים אלו כמו שהם בענין השכל, הנה ההעלם דשכל הוא בחי' כח המשכיל, והיינו, שכאשר נופל לאדם איזה השכלה, הרי הוא מרגיש שישנו מקום שמשם באה ההשכלה, דאף שאינו מרגיש את השכל שבכח המשכיל, ועד שאינו יודע כלל אם הוא שכל, מ\"מ, אין זה סתום בעצם, שהרי מרגיש את מציאותו. משא\"כ בבחי' כח השכל היולי העצמי, הרי אינו מרגיש את מציאותו כלל, ומכ\"ש שאינו יודע אם הוא ענין שכלי, והיינו, לפי שאינו בגדר המשכה, להיותו סתום בעצם, שלכן אינו מרגיש את מציאותו, רק שיודע מצד הכרח השכל, או מצד אמונת חכמים, שישנו ענין שהוא מקור לכח המשכיל שהוא מקור שכל הגלוי.\nד) <b>והדוגמא</b> מזה יובן למעלה, דבכללות הגילויים יש ג' בחינות, בחי' האור שבא בפנימיות בעולמות, ואור שבבחי' מקיף אבל הוא בגדר המשכה, והוא בחי' מקיף דאו\"י שהוא בגדר המשכה וגילוי, אלא שאין העולמות כלים לקבל את האור, ואור שבבחי' או\"ח, היינו שמצד עצם ענינו בטבעו (כפי ששייך ענין הטבע למעלה) הוא בעלי' והתכללות בעילוי אחר עילוי. וזהו ג\"כ מ\"ש<sup data-n=\"115\">28</sup> כשמן הטוב על הראש גו', ואיתא בזהר<sup data-n=\"116\">29</sup> דשמן הוא בחי' אפרסמון, ויש בו האותיות מ\"םוסמ\"ך, ששניהם הם בחי' מקיפים, ומ\"מ יש הפרש ביניהם, דמ\"ם סתומה יש בה מרובע, והיינו שמ\"מ יש לו אחיזה והתיישבות בהפנימי, משא\"כ סמ\"ך הוא בעיגול, היינו, שאין לו אחיזה והתיישבות כלל, שהם ב' המקיפים דאו\"י ואו\"ח<sup data-n=\"117\">30</sup>.\n<b>והענין</b> בזה, דהנה, כללות הגילוי שבעולמות הוא מבחי' שם הוי', שיש בו ד' אותיות, שענינם הוא צמצום והתפשטות המשכה והתפשטות<sup data-n=\"118\">31</sup>. אך בשם הוי' גופא יש כמה בחינות, יש בחי' שם הוי' שבסדר השתלשלות, ויש בחי' שם הוי' כמו שהוא בבחי' הוא ושמו בלבד (שהי' קודם שנברא העולם)<sup data-n=\"119\">32</sup>, ויש בחי' הוי' כמו שכלול בעצמותו, שאין בו אותיות כלל. וזהו\"ע ישת חושך סתרו<sup data-n=\"120\">33</sup>, שהקב\"ה מתעלם ומסתתר בענין החושך, שיש בזה ב' פירושים וענינים. יש פירוש שבחי' החושך קאי על כללות ענין הצמצומים עד לצמצום הראשון שהוא בדרך סילוק לגמרי, שהוא אמיתית ענין החושך. אמנם כיון שהצמצום הוא בשביל הגילוי, הרי אין זה עדיין חושך והעלם אמיתי, אלא רק העלם לגבי המקבל, שהרי באמיתית ענינו הוא גילוי, אלא שהוא בהעלם מהמקבלים, והוא בחי' מקיף דאו\"י, ולכן הנה גם אחרי הצמצום ישנו המשכת הקו שנוגע ודבוק בהעיגול הגדול שקודם הצמצום, לפי שהצמצום אינו הפסק אמיתי, להיותו בשביל הגילוי. אך יש עוד פירוש בענין ישת חושך סתרו, שהו\"ע החושך והצמצום מצד עצמו, שאינו בשביל הגילוי, אלא ענינו הוא להיות נכלל ולהתעלם במקורו, כנ\"ל בענין מקיף דאו\"ח. ובאמת הנה גם בהאור שקודם הצמצום גופא ישנם ב' בחינות אלו, וכידוע ומבואר בהמשך יו\"ט של ר\"ה תרס\"ו<sup data-n=\"121\">34</sup> שבהאור שקודם הצמצום ישנם השרשים לאור הממלא ולאור הסובב, ובכללות הו\"ע התפשטות האור ועצם האור, שהו\"ע מקיף דאו\"י ומקיף דאו\"ח. ובעומק יותר, הנה גם עצם האור הוא בחי' מקיף דאו\"י, שהרי הוא ג\"כ אור, אלא שהוא העצם דאור שנבדל מהתפשטות. ואמיתית ענין או\"ח הוא בחי' האור הכלול בעצמותו, בחי' היכולת. וכללות ענין ב' מקיפים אלו הםדוגמת ב' הבחינות דהתנשאות, התנשאות על עולמות, והתנשאות שמצד עצמו (כנ\"ל במאמר דר\"ה<sup data-n=\"122\">35</sup>).\n<b>וזהו</b> ג\"כ מ\"ש&lt;28&gt; כשמן הטוב על הראש יורד על הזקן זקן אהרן, דבחי' הזקן זקן אהרן הו\"ע י\"ג תיקוני דיקנא<sup data-n=\"123\">36</sup>, שהם יגמה\"ר הנמשכים ע\"י עבודת אהרן כה\"ג בענין הקטרת, וכמ\"ש כי בענן אראה, אראה סתם, והוא המשכת העצמות, בחי' פנימיות עתיק, שמבחי' זו נמשכת הכפרה לכל הפגמים והחטאים שבתומ\"צ ששרשם מבחי' גלגלתא, והסליחה הוא מבחי' פנימיות עתיק שלמעלה מבחי' גלגלתא כנ\"ל, וענין זה נמשך ע\"י בחי' שמן הטוב, בחי' חכמה סתימאה, שיש בה ב' המקיפים, מ\"ם וסמ\"ך, מקיף דאו\"י ומקיף דאו\"ח, שהם ב' הענינים שבחכמה סתימאה, שהיא מקור לחכמה הגלוי', שהוא בחי' מקיף דאו\"י, ומקור ליגמה\"ר, מקיף דאו\"ח, והו\"ע בחי' פנימיות אבא פנימיות עתיק<sup data-n=\"124\">37</sup>, והיינו, שבגלגלתא הוא רק חיצוניות עתיק ובבחי' מקיף, משא\"כ בחכמה סתימאה הוא בחי' פנימיות עתיק ובפנימיות, ומצד זה היא מקור ליגמה\"ר כנ\"ל.\nה) <b>ועפ\"ז</b> יובן גם ענין העושה סוכתו תחת האילן כו', דהנה, ענין האילן הוא בחי' מקיף דאו\"י, כמבואר בקבלה ובחסידות<sup data-n=\"125\">38</sup>, ולכן אין זה כפי שצריך להיות ענין הסוכה, לפי שסוכה היא התגלות יגמה\"ר שמצד התשובה דיום הכיפורים כנ\"ל, שזהו מצד בחי' מקיף דאו\"ח דוקא. וזהו העושה סוכתו תחת האילן כאילו עשאה בתוך הבית, דבית הו\"ע ההתיישבות, בחי' סדר ההשתלשלות, הנה גם בחי' אילן שהוא בחי' מקיף, מאחר שהוא בחי' מקיף דאו\"י, ראשית ההשתלשלות, לכן אין זה מספיק, אלא צריך להיות בחי' הסוכה מקיף דאו\"ח דוקא. והגם שבאברהם כתיב והשענו תחת העץ, הרי ענין זה הי' גבי מלאכים, וגם קודם מ\"ת, וההפרש בין מלאכים לנשמות הוא דוגמת ההפרש בין קודם מ\"ת ואחרי מ\"ת. דהנה, קודם מ\"ת היתה הגזירה שבני סוריא לא יעלו לרומי כו'<sup data-n=\"126\">39</sup>, והיינו שהי' הכל ע\"פ סדר השתלשלות, ומצד סדר השתלשלות אפשר להגיע רק עד בחי' מקיף דאו\"י, בחי' אילן, משא\"כ אחרי מ\"ת שנתחדש ענין חיבור רומי וסוריא<sup data-n=\"126\">39</sup>, שזהו הגילוי שלמעלה מסדרהשתלשלות, הנה עכשיו צריך להיות בחי' מקיף דאו\"ח דוקא, וענין זה נעשה ע\"י עבודת הנשמות, לפי שהם מפנימיות הכלים המיוחדים עם פנימיות האור עד עצם האור עד העצמות, בחי' ישת חושך סתרו, שדוקא עי\"ז אפשר להיות אמיתית ענין התשובה והכפרה, לפי שהוא למעלה מבחי' גלגלתא. והמשכה זו היא ביום הכיפורים, והתגלותה היא בחג הסוכות, ליום חגנו, אך הגילוי הוא בבחי' מקיף עדיין, ואח\"כ בשמיני עצרת נעשית ההמשכה בפנימיות, באופן שיהיו לך לבדך ואין לזרים אתך<sup data-n=\"127\">40</sup>.\n**********<b>בס\"ד. שיחת</b>*<b> יום ב' דחג הסוכות, ה'תש\"כ</b>.\nבלתי מוגה\nכ\"ק אדמו\"ר שליט\"א נטל ידיו הק' לסעודה.\n<b>א</b>. בין דרושי החסידות בנוגע לחג הסוכות, ישנו הדרוש בסידור<sup data-n=\"128\">1</sup> – מאמרי אדמו\"ר הזקן שכתבם אדמו\"ר האמצעי בסגנון שלו – שמבאר מאמר הזהר<sup data-n=\"129\">2</sup> בענין האושפיזין (אורחים) שבשבעת ימי הסוכות, היינו, שבכל יום ישנו האושפיזא העיקרי, ויחד עמו באים גם ששת האושפיזין, \"שאר צדיקייא\" (בלשון הזהר), וביום השני דסוכות האושפיזא העיקרי הוא: יצחק.\nואיתא בזהר, שהאושפיזין מברכים מענין פעולותיהם הם – בפסוקי תורה.\nובהקדמה – שכל ההמשכות של חודש תשרי, ובכללם גם חג הסוכות, הן המשכות כלליות על כל השנה, ובחג הסוכות, \"זמן שמחתנו\", נמשכת שמחה על כל השנה<sup data-n=\"130\">3</sup>.\nובענין זה ישנה פעולתם של האושפיזין – שהמשכת השמחה על כל השנה כולה תהי' בגילוי למטה מעשרה טפחים.\nופעולה זו נעשית ע\"י פסוקי התורה (כדלקמן ס\"ב) – ככל הענינים שנעשים ע\"י התורה, כידוע שהתהוות העולם היא ע\"י התורה, כמאמר הזהר<sup data-n=\"131\">4</sup> \"אסתכל באורייתא וברא עלמא\", וכן לאחרי התהוות הבריאה נעשית הנהגת העולמות ע\"י התורה, ועד שגם ההמשכות שע\"י הצדיקים – שממשיכים בעולם ענינים שלמעלה מהעולם – נעשים גם הם ע\"י התורה.\nוהענין בזה – שכל אחד מישראל, \"עמך כולם צדיקים\"<sup data-n=\"132\">5</sup>, יש לו חלק בתורה, כמרומז בשם \"ישראל\", ר\"ת <b>י</b>ש <b>ש</b>שים <b>ר</b>יבוא <b>א</b>ותיות <b>ל</b>תורה<sup data-n=\"133\">6</sup>, כנגד ששים ריבוא בנ\"י (שזהו המספר דכללות ישראל<sup data-n=\"134\">7</sup>), היינו, שכל אחד מישראל יש לו אות בתורה<sup data-n=\"135\">8</sup>. וכמו\"כ בתושבע\"פ יש לכל אחדמישראל חלקו בתורה, ועל זה מבקשים \"ותן <b>חלקנו</b> בתורתך\"<sup data-n=\"136\">9</sup>, \"חלקי הוי' אמרה נפשי\"<sup data-n=\"137\">10</sup>, שחלק זה צריך לחדש ולגלות כו'. וע\"י חלקו בתורה נמשכים כל עניניו, הרוחניים והגשמיים, בחלקו בעולם.\nוכיון שכל ההמשכות הם ע\"י התורה, הנה גם ההמשכות שע\"י האושפיזין – שהם רועים כלליים לכללות ישראל – הם ע\"י פסוקי התורה.\n<b>ב</b>. והנה, בנוגע להפסוק שבו מברך יצחק, יש שקו\"ט בזהר<sup data-n=\"138\">11</sup>, אבל מסקנת הזהר (כדברי ר\"ש) היא ש\"יצחק קאמר גבור<sup data-n=\"139\">12</sup> בארץ יהי' זרעו וגו'\", והיינו, שצריך להיות ענין של התגברות.\nוהענין בזה<sup data-n=\"140\">13</sup>:\nבנוגע לאברהם – כיון שירד מצרימה, \"ערות הארץ\"<sup data-n=\"141\">14</sup> כו', הרי בודאי צריך להיות ענין של התגברות, ואין חידוש בדבר;\nהחידוש הוא בנוגע ליצחק – שהרי יצחק הי' \"עולה תמימה\"<sup data-n=\"142\">15</sup>, ומעולם לא יצא מארץ קדושה, ועד שלא היתה לו שייכות ולא הי' יכול לסבול מציאות של רע, שלכן \"ותכהין עיניו מראות\"<sup data-n=\"143\">16</sup> את מעשיהם הרעים של נשי עשו, ואעפ\"כ, הנה גם יצחק – שהוא למעלה לגמרי מהעולם – פעל במדת הגבורה.\n<b>ג</b>. וההוראה מזה:\nישנם הטוענים שמצד הכשרונות והחושים שלהם ומצד מעמדם ומצבם הרי הם טוב לגמרי, ובמילא אין להם צורך ביגיעה.\nועל זה היא ההוראה מיום השני של סוכות – שאפילו מי שנמצא בדרגא וסדר הנהגה כמו יצחק, הנה גם הוא זקוק לגבורה ויגיעה, כי, כאשר אין הענין ד\"יגעת\", ובאופן <b>שהתורה</b> קוראת זאת בשם \"יגעת\", אזי אין הענין ד\"מצאת\"<sup data-n=\"144\">17</sup>.\nוענין זה נאמר לכל אחד, והיינו, שאפילו מי שמצד כשרונותיו כו'יכול לפעול גם <b>ללא יגיעה</b> כפי שפועל זולתו ע\"י יגיעה, הנה גם אצלו צריך להיות ענין של יגיעה, וזהו תכלית האדם בכלל, ובפרט \"אתם קרויין אדם\"<sup data-n=\"145\">18</sup>, כמ\"ש<sup data-n=\"146\">19</sup> \"אדם לעמל יולד\".\nובכללות ישנם בזה ג' מדריגות: \"עמל מלאכה\", \"עמל שיחה\", ו\"עמל תורה\"<sup data-n=\"147\">20</sup>. וכפי שנתבאר בארוכה במאמרי הקיץ<sup data-n=\"148\">21</sup>, שתחילה צריך להיות אצלו \"עמל מלאכה\", ולאחרי שפועל ענין זה, הרי זה נעשה אצלו אמצעי שעל ידו יכול לבוא לשליבה הב' – \"עמל שיחה\", ולאחרי שפועל גם שליבה הב', נעשית גם היא אמצעי שעל ידה מגיע ל\"עמל תורה\", שזוהי התכלית האמיתית.\nוזוהי ההוראה מיצחק – שאפילו מי שנמצא \"בארץ ישראל\", שדירתו והנהגתו הן \"ארץ אשר גו' עיני הוי' אלקיך בה מרשית השנה ועד אחרית שנה\"<sup data-n=\"149\">22</sup>, ועומד בהתקשרות תמידית עם אלקות, הנה גם הוא צריך להיות גבור, לעבוד עבודתו מתוך עמל ויגיעה, ודוקא עי\"ז הרי הוא ממלא תכלית בריאתו.\n<b>ד</b>. ועוד עיקר בפסוק זה – הדיוק \"גבור בארץ יהי' <b>זרעו</b>\", היינו, שעבודתו ניכרת ונבחנת ב\"זרעו\" דוקא:\nכאשר מתייגע בעבודתו ופועל בעצמו כו\"כ מעלות – אין זה מורה עדיין על מדת גבורתו ויגיעתו. ומה גם שיתכן שמעלות אלו אינן משלו, כיון שירש אותן מאביו או מזקנו;\nענין היגיעה והגבורה ניכר דוקא כאשר פועל על זרעו – זרעו כפשוטו, או \"בניך אלו התלמידים\"<sup data-n=\"150\">23</sup> – שגם הם ילכו בהדרך של \"גבור\", לא יתפעלו משום העלמות והסתרים, מניעות ועיכובים והגבלות.\nוכאשר הולכים בסדר זה, באופן ד\"ופרצת ימה וקדמה וצפונה ונגבה\"<sup data-n=\"151\">24</sup>, הרי זה פועל ש\"יעלה הפורץ לפניהם\"<sup data-n=\"152\">25</sup>, בקרוב ממש, בגאולה האמיתית והשלימה.\n***\n<b>ה</b>. ידוע שכל הענינים ישנם ומשתקפים בפנימיות התורה. ובנוגעלענין האושפיזין – ידוע פתגם כ\"ק מו\"ח אדמו\"ר<sup data-n=\"153\">26</sup> שישנם גם ה\"אושפיזין החסידיים\" (\"די חסידישע אושפיזין\"), נשיאי החסידות, במנותו את הבעש\"ט, המגיד, אדמו\"ר הזקן וכו', עד לאביו כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע. ואושפיזין אלו, אופי פעולות כל אחד מהם מתאימה לאושפיזין שבזהר.\nויש תורה מהמגיד – האושפיזא דיום ב' דסוכות – בנוגע לענין היו\"ט ומועד, וז\"ל<sup data-n=\"154\">27</sup>:\n\"אמרו רז\"ל<sup data-n=\"155\">28</sup> אין נושאים נשים במועד לפי שאין מערבין שמחה בשמחה . . כי הנה ידוע כי הגוף (וכן כללות עניני העולם) נקרא נוקבא (בחי' מקבל, כיון שצריכים לקבל מהאדם, שמברר ומעלה אותם), והזהירו שלא יהי' עסק האדם במוע\"ד ימי חייו . . שהם . . קצובים לו (והיינו, שמועד הוא מלשון זמן, שבעים-שמונים שנה, ועד מאה ועשרים שנה, שזהו הזמן שניתן לאדם למטה למלא את השליחות ד\"מלאו את הארץ וכבשוה\"<sup data-n=\"156\">29</sup>) . . לא יחזור בהם אחר תענוג הגוף למלאות תאוותו תאוות גשמיות, וזהו לשון נשיא\"ה שמנשא ומגדל את הגוף . . לפי שאין מערבין שמחה בשמחה, ר\"ל שמחה והוללות של תענוגי החומריים, בשמחת הרוחני שהיא עבודת הבורא יתברך . . ופשיטא בימי החג שהם נקראין מוע\"ד ממש (כיון שבהם אין עוסקים בעובדין דחול, ומתמסרים יותר למלא את שליחותו של הקב\"ה) . . אבל האמת הוא שכל ימי האדם הוא באזהרה זו כו'\".\nוצריך להבין:\nא) מהו הטעם שהענין ד\"נושאים נשים\" (שמנשא ומגדל את הגוף) נקרא בשם שמחה? בשלמא \"שמחת הרוחני שהיא עבודת הבורא יתברך\", הרי היא לא רק שמחה סתם, אלא שמחה שאין למעלה ממנה (כמבואר בכ\"מ<sup data-n=\"157\">30</sup>); אבל ההתעסקות בעניני הגוף והעולם – מהו הטעם שנקראת בשם שמחה?\nב) וביותר אינו מובן: איך אפשר שיתערבו חומריות ורוחניות, הפכים מן הקצה אל הקצה? ובמכ\"ש וק\"ו משמן שאינו מתערב בשאר המשקין אלא צף מלמעלה<sup data-n=\"158\">31</sup>, והיינו, שגם כאשר מדובר אודות שני עניניםשהם נבראים, ובנבראים גופא הם מסוג הדומם, ושניהם משקין, הנה כיון ששמן הוא למעלה משאר המשקין, לכן אינו מתערב עמהם, ועאכו\"כ בנוגע לעניני הגוף והעולם ועבודת הבורא יתברך (מילוי שליחותו של הקב\"ה), חומריות ורוחניות, שהם באין ערוך לגמרי, הפכים מן הקצה אל הקצה, הרי בודאי לא שייך שיתערבו יחד. וא\"כ מהו הצורך לשלול ש\"אין מערבין שמחה בשמחה\"?\n<b>ו</b>. והביאור בזה:\nמצד ענין הבחירה שנתן הקב\"ה לבנ\"י, כמ\"ש<sup data-n=\"159\">32</sup> \"ראה נתתי לפניך גו' את החיים ואת הטוב ואת המות ואת הרע גו' ובחרת בחיים\", הנה בכדי שיוכל להיות ענין הבחירה, צריכים להיות שני הענינים שקולים, כי, כאשר יש מעלה בענין אחד לגבי השני, אזי אין זה אמיתית ענין הבחירה, שהיא בחירה חפשית.\nוזהו שאמיתית ענין הבחירה הוא בעצמותו ית', שאינו מוגבל בשום דבר, ולגבי' הכל שוים, ואעפ\"כ בוחר בבחירתו החפשית בכל אחד מישראל, כמ\"ש<sup data-n=\"160\">33</sup> \"יבחר לנו את נחלתנו את גאון יעקב אשר אהב סלה\", ומצד האהבה העצמית לישראל רצה הקב\"ה שכל אחד ואחת מישראל יבחרו את הטוב בבחירה חפשית, בנתנו להם כח הבחירה של העצמות, שיוכל להיות \"<b>ובחרת</b> בחיים\", גם כאשר ישנם שני קוין שקולים.\nולכן הפליא לעשות – שתהי' אפשריות שגם בעניני העולם תהי' שמחה, ועד לשמחה כזו שתהי' לה השוואה שתוכל להתערב עם השמחה שבמילוי שליחותו של הקב\"ה, ואעפ\"כ, יקיים יהודי את הציווי \"ובחרת בחיים\", עי\"ז שנהי' בבחי' \"<b>גבור בארץ</b>\" – \"איזהו גבור הכובש את יצרו\"<sup data-n=\"161\">34</sup>.\n<b>ז</b>. ביאור הדברים:\nמדובר אמנם אודות ענינים שאינם בערך זל\"ז, ועד שהם ענינים הפכיים זמ\"ז, כך, שלא שייך התערבות ביניהם, אבל אעפ\"כ, כל הגבלות אלו הם רק מצד סדר השתלשלות, או אפילו למעלה מהשתלשלות אבל בבחי' הארות וגילויים, משא\"כ מצד העצמות אין שום הגבלות, ובמילא שייך שיתערבו.\nוכשם שע\"י קיום מצוה בכחו של יהודי ליקח דבר גשמי וחומרי,לבטל את חומריותו עד שתשאר רק גשמיותו, ולברר ולזכך ולהעלות את הגשמיות עד שתתאחד עם העצמות – אף שלכאורה, איזה ערך יש להדבר הגשמי שיומשך בו העצמות, הרי העצמות אינו בגדר מקום כלל, ואיך שייך שיומשך בדבר גשמי מוגבל שבו נעשית המצוה, שנוכל לומר שבדבר זה נמצא העצמות?\nוכידוע בענין \"לית אתר פנוי מיני'\"<sup data-n=\"162\">35</sup>, שנמצא בכל מקום, ואפילו במקום האשפה והטינופת – דלכאורה אינו מובן: כיצד שייך דבר כזה? ומבואר<sup data-n=\"163\">36</sup>, שזהו לפי שאינו מתערב עמהם כו'. וזהו החילוק שבין בחי' הגילויים לבחי' העצמות – שבחי' הגילויים, כיון שיש להם איזו שייכות להמקום שבו נמצאים, אינם יכולים להיות במקום הטינופת, ולכן אסור לומר דברי תורה במקום הטינופת<sup data-n=\"164\">37</sup>; משא\"כ עצמות, לית אתר פנוי מיני', כיון שאינו בגדר מקום כלל, ואינו מתערב בהמקום שנמצא בו.\nואעפ\"כ, הרי ע\"י קיום מצוה, הנה בהגשם שבו נעשית המצוה, במקום זה ישנה המשכת העצמות בפנימיות.\nוטעם הדבר – כיון שעצמותו ית' מסר את עצמו (\"האָט זיך אָפּגעגעבן\") לאיש הישראלי, שאע\"פ שאינו בגדר מקום, מ\"מ, יוכל יהודי ליקח דבר גשמי ולאחד אותו עם העצמות.\nועד\"ז לאידך גיסא – כמובא בתניא<sup data-n=\"165\">38</sup> \"משל האוחז בראשו של מלך ומורידו למטה וטומן פניו כו'\" (במקום הטינופת), והיינו, שאע\"פ שאין שייכות למלך למקום הטינופת, מ\"מ, מסר את עצמו ליהודי שיוכל להוריד אותו כו'.\n<b>ח</b>. ועפ\"ז מובן צורך האזהרה \"אין מערבין שמחה בשמחה\":\nמצד זה שהעצמות מסר את עצמו ליהודי, שייך שיהודי יערב כו', ולכן צריך להזהירו ש\"אין מערבין\", אלא עליו לנצל את הזמן למילוי שליחותו בעולם בעבודה ד\"מלאו את הארץ וכבשוה\", לפעול בגשמיות העולם לעשות ממנו כלי לאלקות, ועד שיהי' דבר אחד עם העצמות.\nועי\"ז הרי הוא מבטל את ההגבלות שבעולם, כיון שממשיך בו בלי גבול, והיינו, שפועל בעולם הענין ד\"ופרצת ימה וקדמה גו'\".וזהו גם הענין ד\"פרזות תשב ירושלים\"<sup data-n=\"166\">39</sup> – שהענין ד\"פרזות\", בלי גבול, נמשך ובא בהתיישבות, \"תשב\".\nוענין זה יתגלה ע\"י \"יעלה הפורץ\", בקרוב ממש.\n***\n<b>ט</b>. צוה לנגן ואמר מאמר ד\"ה העושה סוכתו תחת האילן כו'.\n***\n<b>י</b>. הזמן שבו נמצאים אנו עתה הוא – אור ליום שלישי של חג הסוכות, שהאושפיזא העיקרי שלו הוא יעקב.\nוהנה, בנוגע ליעקב, איתא בזהר&lt;11&gt; שאומר ומברך: \"אז יבקע כשחר אורך\"<sup data-n=\"167\">40</sup>, וזהו ש\"יעקב\" אותיות \"יבקע\" ו\"יבקע\" אותיות \"יעקב\"<sup data-n=\"168\">41</sup>, שהו\"ע הבקיעה – בקיעת האור דרך כל המניעות והעיכובים. וזהו גם תוכן מארז\"ל<sup data-n=\"169\">42</sup> במעלת יעקב לגבי אברהם ויצחק – לא כאברהם שיצא ממנו ישמעאל, לא כיצחק שיצא ממנו עשו, אלא כיעקב שהיתה מטתו שלימה, ועוד אמרו רז\"ל \"לא כאברהם כו' כיצחק כו' אלא כיעקב שכתוב בו ופרצת ימה וקדמה וצפונה ונגבה\"<sup data-n=\"170\">43</sup>, שזוהי \"נחלה בלי מצרים\"<sup data-n=\"171\">44</sup>.\nוהענין בזה:\nאין הכוונה שאצל יעקב לא היו מדידות והגבלות, ואדרבה: התורה מספרת שיעקב הועמד בפני עבודה קשה ביותר; אצל יעקב מצד עצמו היו קשיים והפרעות יותר מאשר אצל יצחק, ואפילו יותר מאשר אצל אברהם, שהרי יעקב הי' צריך להתמודד עם עשו, ולפנ\"ז עם לבן, והוצרך לריבוי עבודה ויגיעה, וכמ\"ש<sup data-n=\"172\">45</sup> \"ביום אכלני חורב וקרח בלילה ותדד שנתי מעיני\"; אלא שע\"י העבודה והיגיעה בקע את כל המניעות והעיכובים, ועד שגם ב\"חרן\", \"חרון אף של עולם\"<sup data-n=\"173\">46</sup>, פרץ גדרו של העולם – הסרת כל המניעות והעיכובים.\nולכן זכה לשכר ד\"ופרצת\" – שלא זו בלבד שנתבטלו המניעות והעיכובים, ונעשה אצלו מעמד ומצב ללא מניעות ועיכובים, כפי שהי'אצל אברהם ויצחק, אלא יתירה מזה, שנעשה אצלו הענין ד\"ופרצת\", בלי גבול.\nוזהו גם שהיתה מטתו שלימה, דלא כאברהם ויצחק – כי, אברהם ויצחק, להיותם בהגבלה, היתה אצלם נתינת מקום ש\"יצא ממנו כו'\", משא\"כ יעקב שאצלו הי' הענין ד\"ופרצת\", היתה מטתו שלימה.\nוזוהי ההוראה מיום שלישי דחג הסוכות – שאין להתחשב בשום קשיים והפרעות, אלא לילך בדרך של \"ופרצת\", ועי\"ז לוקחים את כל הענינים באופן ד\"מטתו שלמה\", והולכים עמהם לקראת \"יעלה הפורץ\".\n***\n<b>יא</b>. בהמשך להמוזכר לעיל (ס\"ה) אודות האושפיזין החסידיים, הרי האושפיזא של יום שלישי דחג הסוכות הוא – אדמו\"ר הזקן.\nוהנה, בנוגע לענינם של הרביים מצינו כמה סדרים:\nהבעש\"ט המגיד ואדמו\"ר הזקן הם בחי' כח\"ב (כתר חכמה בינה) דתורת החסידות (כדברי כ\"ק מו\"ח אדמו\"ר<sup data-n=\"174\">47</sup>). וישנו גם כפי שהם בחי' חב\"ד (חכמה בינה דעת) דתורת החסידות.\nאבל ישנה גם השיחה<sup data-n=\"175\">48</sup> שבה נתבאר שאדמו\"ר הזקן הוא בחי' חכמה, אדמו\"ר האמצעי הוא בחי' בינה וכו', ואילו הבעש\"ט והמגיד הם ב' הבחינות שבכתר: עתיק ואריך.\nועפ\"ז, הנה כשם שנת\"ל בהמאמר<sup data-n=\"176\">49</sup> בענין פנימיות אבא פנימיות עתיק<sup data-n=\"177\">50</sup>, שבבחי' הרצון יש רק חיצוניות התענוג, ובאופן מקיף, ודוקא בבחי' החכמה ישנו פנימיות התענוג, ובאופן פנימי – כמו\"כ יובן גם בנדו\"ד, שהפנימיות של הבעש\"ט, פנימיות עתיק, לוקחים דוקא ע\"י אדמו\"ר הזקן, פנימיות אבא. וזהו חידושו של אדמו\"ר הזקן בתורת חב\"ד – להמשיך את כל הענינים בפנימיות, ובזה דוקא ישנו הפנימיות דהבעש\"ט.\nובהקדמה – ששיחה כזו (דלקמן) שייכת לי\"ט כסלו, ומה שמדברים בזה עתה, הרי זה מפני ששנה זו היא מאתיים שנה להילולא של הבעש\"ט.ומצד זה, ידפיסו בלי נדר את הספר \"צוואת הריב\"ש\", וכדברי אדמו\"ר הזקן<sup data-n=\"178\">51</sup> ש\"הגם שבאמת אינה צוואתו כלל, ולא ציוה כלל לפני פטירתו\", ויתירה מזה, ש\"לא ידעו לכוין הלשון על מתכונתו\", מ\"מ, \"המכוון הוא אמת לאמיתו\".\nוכיון שפנימיות עתיק לוקחים בפנימיות אבא, הרי מובן, שהביאור בספר צוואת הריב\"ש יכולים ליקח מתורתו של אדמו\"ר הזקן, כדלקמן.\n<b>יב</b>. בהתחלת הספר צוואת הריב\"ש איתא: \"להיות תמים בעבודתו יתברך, עבודה תמה\".\nומשמעות הדברים, שזהו ענין עיקרי ביותר, שהרי בהמשך הדברים מונה כמה ענינים עיקריים, וכיון שמקדים בענין זה, הרי מובן, שזהו ענין עיקרי יותר מהענינים העיקריים שמונה לאח\"ז.\nואינו מובן: מהו החידוש שבזה, ומהו הענין העיקרי שבזה?\n<b>יג</b>. ויש לבאר זאת ע\"פ שיעור היומי בתניא<sup data-n=\"179\">52</sup> – שבו מבקש אדמו\"ר הזקן מחסידים וקובע להם סדר בעבודת התפלה – שגם שם נזכר הלשון \"לעבוד עבודה תמה\":\nכדי להבין הפירוש ד\"עבודה תמה\"<sup data-n=\"180\">53</sup> – הנה כשם שיש ענינים בנגלה דתורה שנעשים מוארים ע\"י פנימיות התורה, כמו\"כ יש ענינים בפנימיות התורה שנעשים מוארים ע\"י גליא דתורה, ובנדו\"ד – מצינו בגמרא במסכת יומא<sup data-n=\"181\">54</sup> הלשון \"עבודה תמה\", ופירש רש\"י: \"עבודה שהיא גומרת ומתממת את הדבר\" (\"ולא עבודה שיש אחרי' עבודה\").\nוהענין בזה:\nבשיעור תניא היומי מונה רבינו הזקן כו\"כ מדריגות:\n\"החכמה והתבונה . . לדעת לעשות את כל אשר צוה ה' בהשכל ודעת\", שזוהי העבודה שמצד כחות פנימיים, שהתחלתם הו\"ע השכל והחכמה.\nולמעלה מזה – העבודה מצד בחי' ה\"רצון . . אשר למעלה מן החכמה\". וכיון שברצון גופא יש כמה מדריגות, כידוע שישנו הרצון השייך אל השכל, וכמו \"לעולם ילמוד אדם תורה במקום שלבו חפץ\"<sup data-n=\"182\">55</sup>,שזהו הרצון השייך אל השכל, מקיף השייך לפנימי, ואין זה אמיתית ענין הרצון – לכן מוסיף: \"רצון פשוט\", דהיינו, עצם הרצון, שלמעלה משייכותו אל הפנימי.\nוגם זה אינו מספיק עדיין, אלא צריך להיות – כפי שממשיך שם – \"רוח נדיבה בכל איש אשר ידבנו לבו\", שזוהי העבודה שמצד <b>התענוג</b>, שלמעלה גם מ\"רצון פשוט\". וענינו למעלה הוא בחי' עתיק, שלמעלה גם מבחי' אריך<sup data-n=\"183\">56</sup>.\nאמנם, כל זה אינו אלא בחי' הגילויים בלבד, שהרי גם בחי' עתיק הוא כבר ענין של העתקה, שנעתק ונעשה בחי' עתיק לעולמות. וענינו בעבודה הוא בחי' התענוג כפי שבא במורגש<sup data-n=\"184\">57</sup>.\nועל זה מוסיף, שצריך \"לעבוד עבודה תמה\", שזוהי העבודה שמצד עצם הנשמה, שמתקשרת עם העצמות, ולכן נקראת \"עבודה תמה\" (שאין אחרי' עבודה), \"עבודה שהיא גומרת ומתממת את הדבר\", שזהו הגמר והתכלית.\nובזה גופא יש חילוק בין עבודת הצדיקים לעבודת התשובה – שעבודת הצדיקים שהיא באופן של אור ישר, אינה מגעת בהעצם ממש, כי אם עבודת התשובה שהיא בבחי' אור חוזר<sup data-n=\"185\">58</sup>.\n<b>יד</b>. ועפ\"ז יש לומר גם בפירוש מ\"ש בצוואת הריב\"ש \"להיות תמים בעבודתו יתברך, עבודה תמה\":\nהטעם שענין זה הוא עיקר גדול שלכן מתחיל בו את הספר כולו, הוא – כיון שהתכלית היא לקשר את העצם שלו עם העצמות.\nובפיסקאות שלאח\"ז מבאר את הסדר והאופן כיצד באים ל\"עבודה תמה\".\n[קודם סיום ההתוועדות הורה כ\"ק אדמו\"ר שליט\"א, שבימי חג הסוכות יסדרו התוועדויות בערי השדה, וגם בבית המדרש.\nלאחרי ברכת המזון, תפלת ערבית והבדלה – נתן כ\"ק אדמו\"ר שליט\"א בידו הק' לכל הנאספים מ\"כוס של ברכה\"].\n**********",[["88","1","סוכה פ\"א מ\"ב."],["89","2","ראה גם רד\"ה זה תרד\"ע (המשך תער\"ב ח\"א ע' תיג). ועוד."],["90","3","ב\"ר פמ\"ח, י. וראה גם במדב\"ר פי\"ד, יב."],["91","4","וירא יח, ד."],["92","5","תהלים קה, לט."],["93","6","אמור כג, מב."],["94","7","ישעי' ד, ו."],["95","8","ראה מאמרי אדה\"ז תקס\"ו ע' שעט. אוה\"ת סוכות ע' א'תשנו. ברכה ע' א'תתסו. סה\"מ תרנ\"ד ע' לו. תרנ\"ו ע' רעח. תש\"ב ע' 49."],["96","9","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380937\" data-slug=\"likkutei-torah\" data-id=\"4001380937\">תהלים פא, ד</a>. ר\"ה ח, סע\"א ואילך. וראה לקו\"ת דרושים לר\"ה נד, סע\"ג ואילך. סידור (עם דא\"ח) רלה, ב. ועוד."],["97","10","הל' תשובה פ\"ג ה\"ד. וראה המשך תרס\"ו ע' ב ואילך. סה\"מ תרח\"ץ ע' טו. ה'שי\"ת ע' 8 ואילך."],["98","11","ישעי' נה, ו. ר\"ה יח, א. יבמות מט, ב. קה, א. רמב\"ם שם פ\"ב ה\"ו."],["99","12","שלח יד, כ. וראה תנחומא פקודי יא. פרש\"י תשא לג, יא. עקב ט, יח. תוד\"ה כדי ב\"ק פב, א. וראה לקו\"ש חלק כד ע' 570 הערה 10."],["100","13","ראה מלכים-א א, כא ובפרש\"י. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380650\" data-slug=\"likkutei-torah\" data-id=\"4001380650\">לקו\"ת מטות פב, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380923\" data-slug=\"likkutei-torah\" data-id=\"4001380923\">נצבים נא, א</a>. רד\"ה ע\"כ יאמרו המשלים דש\"פ חו\"ב תרצ\"א. ובכ\"מ."],["101","14","תשא לד, ו. מיכה בסופו."],["102","15","ראה עטרת ראש שער יום הכיפורים לו, סע\"א ואילך. מאמרי אדמו\"ר האמצעי דברים ח\"ד ע' א'רמד. אוה\"ת סוכות ע' א'תשכב ואילך. המשך וככה תרל\"ז פרק פד ואילך. סה\"מ תרנ\"ז ע' קסב. ועוד."],["103","16","אחרי טז, ב."],["104","17","ראה עטרת ראש שם כט, א. מאמרי אדמו\"ר האמצעי דברים ח\"ג ע' א'קלד."],["105","18","ראה זהר ח\"ג רנז, ב."],["106","19","יומא פו, ב. וראה תניא פ\"ז."],["107","20","ראה תקו\"ז בהקדמה (ב, א). שם ריש תיקון ב (יח, סע\"א). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380053\" data-slug=\"likkutei-torah\" data-id=\"4001380053\">לקו\"ת פקודי ג, ב</a>."],["108","21","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310073\" data-slug=\"tanya\" data-id=\"3401310073\">תניא</a> אגה\"ת רפ\"ב (ע\"פ ב\"ק ל, ב)."],["109","22","רמב\"ם הל' תשובה פ\"ז ה\"ד (מברכות לד, ב)."],["110","23","בכל הבא לקמן – ראה ד\"ה העושה סוכתו הנ\"ל. וראה גם ד\"ה סוכה שחמתה מרובה מצלתה תשי\"ד פ\"ב ואילך (תו\"מ ח\"י ע' 22 ואילך)."],["111","24","ראה סה\"מ תרפ\"ט ע' 5 ואילך. וש\"נ."],["112","25","ראה גם מאמרי אדמו\"ר האמצעי שם ח\"ג ע' א'קמא."],["113","26","קהלת ז, כד."],["114","27","שם, כג. וראה קה\"ר עה\"פ (בסופו)."],["115","28","תהלים קלג, ב."],["116","29","ח\"ב קכז, סע\"א ואילך."],["117","30","ראה גם תורת חיים בשלח שמא, סע\"ב ואילך (בהוצאה החדשה – ח\"א רלד, ד ואילך). עטרת ראש דרוש לעשי\"ת סד, ב. סה\"מ תר\"ן ס\"ע שסא ואילך. תרנ\"ז ע' קסו. תרס\"ד ע' קמב ואילך. המשך תרס\"ו ע' שנח."],["118","31","לקו\"ת בשלח בתחלתו. ובכ\"מ."],["119","32","פרקי דר\"א פ\"ג. וראה סה\"מ תרצ\"ו ע' 73. וש\"נ. ספר הערכים – חב\"ד ח\"ד ע' תנג ואילך, ובהנסמן שם."],["120","33","תהלים יח, יב."],["121","34","ע' קפב ואילך. קפח ואילך."],["122","35","ד\"ה שמע ישראל פ\"ג (לעיל ע' 5)."],["123","36","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380432\" data-slug=\"likkutei-torah\" data-id=\"4001380432\">לקו\"ת בהעלותך ל, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380534\" data-slug=\"likkutei-torah\" data-id=\"4001380534\">קרח נה, א</a>. ועוד."],["124","37","ראה פרי עץ חיים שער הק\"ש פט\"ו. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380918\" data-slug=\"likkutei-torah\" data-id=\"4001380918\">לקו\"ת נצבים מט, ד</a>. וש\"נ."],["125","38","המשך תער\"ב ח\"א ע' תכא."],["126","39","ראה תנחומא וארא טו. שמו\"ר פי\"ב, ג."],["127","40","משלי ה, יז. שמו\"ר פט\"ו, כג. וראה סד\"ה ביום השמע\"צ תרע\"ד (המשך תער\"ב שם ע' תלה). ריש וסוף ד\"ה הנ\"ל בסה\"מ עת\"ר ע' לה. מד; תש\"ד ע' 43. 47; תש\"ט ע' 69. 73 (הא'); ה'שי\"ת ע' 71. 82.*) ברשימת ההנחה – איזה תיקונים שתיקן כ\"ק אדמו\"ר שליט\"א (<b>המו\"ל</b>)."],["128","1","סידור עם דא\"ח – שער הסוכות רנז, א ואילך."],["129","2","ח\"ג קג, ב ואילך."],["130","3","ראה שיחת יום ב' דחה\"ס דאשתקד ס\"ב (תו\"מ חכ\"ד ס\"ע 61). וש\"נ."],["131","4","ח\"ב קסא, רע\"ב."],["132","5","ישעי' ס, כא. וראה סנהדרין ר\"פ חלק."],["133","6","מג\"ע אופן קפו."],["134","7","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, א</a>)."],["135","8","ראה זו\"ח רות פח, ד. מג\"ע שם. סה\"מ תש\"ו ע' 46. תש\"ט ע' 41 (נעתק ב\"היום יום\" יג אדר שני). תרפ\"ט ע' 69. וש\"נ."],["136","9","אבות פ\"ה מ\"כ. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131118\" data-slug=\"likkutei-sichot\" data-id=\"1300131118\">לקו\"ש חי\"ג ע' 118</a> ואילך. וש\"נ."],["137","10","איכה ג, כד. וראה סה\"מ תש\"ח ע' 136 ובהנסמן בהערה שם. לקו\"ש שם הערה 34. וש\"נ."],["138","11","שם קד, א."],["139","12","תהלים קיב, ב."],["140","13","ראה גם שיחה הנ\"ל ס\"ג ואילך (תו\"מ שם ע' 62 ואילך)."],["141","14","מקץ מב, ט. שם, יב. וראה קה\"ר פ\"א, ד."],["142","15","ב\"ר פס\"ד, ג. הובא בפרש\"י עה\"ת תולדות כה, כו. כו, ב."],["143","16","תולדות כז, א. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051152\" data-slug=\"likkutei-sichot\" data-id=\"1300051152\">לקו\"ש ח\"ה ע' 140</a>."],["144","17","מגילה ו, רע\"ב."],["145","18","יבמות סא, רע\"א."],["146","19","איוב ה, ז."],["147","20","סנהדרין צט, רע\"ב."],["148","21","ד\"ה לא הביט און ביעקב דש\"פ חו\"ב, י\"ב תמוז פ\"ז; וד\"ה אר\"א כל אדם לעמל נברא די\"ג תמוז (תו\"מ חכ\"ו ע' 67; ע' 80 ואילך)."],["149","22","עקב יא, יב."],["150","23","ספרי ופרש\"י ואתחנן ו, ז."],["151","24","ויצא כח, יד."],["152","25","ע\"פ מיכה ב, יג. וראה ב\"ר פפ\"ה, יד ובפרש\"י שם. אגדת בראשית ספס\"ג."],["153","26","ראה שיחת ליל א' דחה\"ס תרצ\"ז ס\"ד (סה\"ש תרצ\"ז ע' 161). וראה גם שיחה הנ\"ל ס\"ח (תו\"מ שם ע' 65). וש\"נ."],["154","27","או\"ת סתפ\"ג (קיב, סע\"ב ואילך)."],["155","28","מו\"ק ח, ב. וראה גם שיחת שמחת ביה\"ש דאשתקד סט\"ו (תו\"מ חכ\"ד ע' 78)."],["156","29","בראשית א, כח."],["157","30","ראה תו\"מ סה\"מ חשון ע' רעט. וש\"נ."],["158","31","ראה טבול יום פ\"ב מ\"ה. רמב\"ם הל' טומאת אוכלין פ\"ח ה\"י."],["159","32","נצבים ל, טו-יט."],["160","33","תהלים מז, ה."],["161","34","אבות רפ\"ד."],["162","35","תקו\"ז תנ\"ז (צא, סע\"ב). ת\"ע (קכב, ב). הובא ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא שעהיוה\"א פ\"ז</a>."],["163","36","ראה סהמ\"צ להצ\"צ מצות פו\"ר פ\"א (דרמ\"צ ב, ב, ב). סה\"מ תש\"י ע' 135. וראה גם \"מ\"מ, הגהות והערות קצרות\" לתניא שם (ע' פג). וש\"נ. מכתב ח' כסלו שנה זו (אג\"ק חי\"ט ס\"ע פא)."],["164","37","ראה שו\"ע אדה\"ז או\"ח רספ\"ה. וש\"נ."],["165","38","ספכ\"ד."],["166","39","זכרי' ב, ח. וראה גם לעיל ע' 15."],["167","40","ישעי' נח, ח."],["168","41","ראה זהר הרקיע לזהר שם. סידור שם – סע\"ד ואילך. סה\"מ תש\"ט ע' 58, ובהנסמן שם בהערה. וראה גם שיחת יום ב' דחה\"ס תשח\"י ס\"ב (תו\"מ חכ\"א ע' 43). וש\"נ."],["169","42","פסחים נו, א. ספרי ואתחנן ו, ד. ויק\"ר פל\"ו, ה. פרש\"י ויחי מז, לא."],["170","43","שבת קיח, רע\"ב."],["171","44","שם, סע\"א."],["172","45","ויצא לא, מ."],["173","46","ראה פרש\"י ס\"פ נח."],["174","47","ראה לקו\"ד ח\"א לו, סע\"א ואילך."],["175","48","ראה סה\"ש תרצ\"ו ס\"ע 141. תרצ\"ז ע' 215. תרצ\"ט ע' 322. תש\"ב ריש ע' 19. תש\"ה ע' 60. וראה גם אג\"ק אדמו\"ר מהוריי\"צ ח\"ט ס\"ע תטז."],["176","49","ד\"ה העושה סוכתו פ\"ב (לעיל ע' 18)."],["177","50","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380918\" data-slug=\"likkutei-torah\" data-id=\"4001380918\">לקו\"ת נצבים מט, ד</a>. וש\"נ. וראה גם סה\"מ ה'שי\"ת ס\"ע 49, ובהערת כ\"ק אדמו\"ר שליט\"א שם."],["178","51","תניא אגה\"ק רסכ\"ה."],["179","52","אגה\"ק סכ\"ב (קלה, א)."],["180","53","ראה גם מכתב ה' אלול שנה זו (אג\"ק\nחי\"ט ע' תכא): \"והעירותי באחת ההתוועדויות כו'\"."],["181","54","כד, א."],["182","55","ע\"ז יט, א."],["183","56","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830276\" data-slug=\"or-hatorah-hb\" data-id=\"8158830276\">אוה\"ת בלק ע' תתקסג</a> ואילך."],["184","57","ראה המשך תרס\"ו ע' קא ואילך. ועוד."],["185","58","ראה סה\"מ תרס\"א ע' קסג. לקו\"ד ח\"א קמז, א."]]]]});
